// 图文视频小说阅读器 v3.5.5。支持为每本小说绑定配套视觉设定 TXT。

// 图文小说阅读器。依赖酒馆助手 JS-Slash-Runner 的 generateRaw 与 createChatMessages。
// Luker/Tavern Helper no longer injects jQuery into script iframes. Keep the
// reader self-contained while preserving its existing jQuery-style UI code.
const $ = globalThis.$ || function inrDollar(input) {
  if (typeof input === 'function') { if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', input, { once: true }); else input(); return new inrDollar.Collection([]); }
  const toNodes = value => {
    if (!value) return [];
    if (value instanceof inrDollar.Collection) return value.nodes;
    if (typeof value === 'string') return Array.from(document.querySelectorAll(value));
    if (value instanceof Element || value === document || value === window) return [value];
    if (typeof value.length === 'number') return Array.from(value).filter(Boolean);
    return [];
  };
  return new inrDollar.Collection(toNodes(input));
};
$.Collection = class {
  constructor(nodes) { this.nodes = [...new Set(nodes)]; this.length = this.nodes.length; this.nodes.forEach((node, index) => { this[index] = node; }); }
  find(selector) { return $(this.nodes.flatMap(node => Array.from(node.querySelectorAll?.(selector) || []))); }
  on(type, selector, handler) {
    const delegated = typeof selector === 'string'; const callback = delegated ? handler : selector;
    this.nodes.forEach(node => node.addEventListener(type, event => {
      if (!delegated) return callback.call(node, event);
      const target = event.target?.closest?.(selector); if (target && node.contains(target)) return callback.call(target, event);
    }));
    return this;
  }
  attr(name, value) { if (value === undefined) return this.nodes[0]?.getAttribute?.(name); this.nodes.forEach(node => node.setAttribute?.(name, value)); return this; }
  prop(name, value) { if (value === undefined) return this.nodes[0]?.[name]; this.nodes.forEach(node => { node[name] = value; }); return this; }
  val(value) { if (value === undefined) return this.nodes[0]?.value; this.nodes.forEach(node => { node.value = value; }); return this; }
  text(value) { if (value === undefined) return this.nodes[0]?.textContent || ''; this.nodes.forEach(node => { node.textContent = value; }); return this; }
  html(value) { if (value === undefined) return this.nodes[0]?.innerHTML || ''; this.nodes.forEach(node => { node.innerHTML = value; }); return this; }
  data(name, value) { const key = String(name).replace(/-([a-z])/g, (_, char) => char.toUpperCase()); if (value === undefined) return this.nodes[0]?.dataset?.[key] ?? this.nodes[0]?.__inrData?.[key]; this.nodes.forEach(node => { node.__inrData ||= {}; node.__inrData[key] = value; }); return this; }
  removeData(name) { this.nodes.forEach(node => { if (node.__inrData) delete node.__inrData[String(name)]; }); return this; }
  is(selector) { const node = this.nodes[0]; return selector === ':checked' ? Boolean(node?.checked) : Boolean(node?.matches?.(selector)); }
  addClass(name) { this.nodes.forEach(node => node.classList?.add(...String(name).split(/\s+/))); return this; }
  removeClass(name) { this.nodes.forEach(node => node.classList?.remove(...String(name).split(/\s+/))); return this; }
  toggleClass(name, force) { this.nodes.forEach(node => node.classList?.toggle(name, force)); return this; }
  toggle(show) { this.nodes.forEach(node => { node.style.display = show === false ? 'none' : ''; }); return this; }
  show() { return this.toggle(true); } hide() { return this.toggle(false); }
  empty() { this.nodes.forEach(node => { node.replaceChildren?.(); }); return this; }
  children(selector) { const children = this.nodes.flatMap(node => Array.from(node.children || [])); return $(selector ? children.filter(node => node.matches(selector)) : children); }
  closest(selector) { return $(this.nodes.map(node => node.closest?.(selector)).filter(Boolean)); }
  each(callback) { this.nodes.forEach((node, index) => callback.call(node, index, node)); return this; }
  first() { return $(this.nodes.slice(0, 1)); }
  remove() { this.nodes.forEach(node => node.remove?.()); return this; }
  trigger(type) { this.nodes.forEach(node => node.dispatchEvent?.(new Event(type, { bubbles: true, cancelable: true }))); return this; }
};
const INR_LIB = 'illustrated_novel_reader_library';
const INR_CHAT = 'illustrated_novel_reader_chat';
// 视频提示词预设与独立 API 存放在脚本作用域, 与原有 chat 作用域配置互不干扰。
const INR_PRESETS = 'illustrated_novel_reader_video_presets';
const INR_API = 'illustrated_novel_reader_video_api';
const INR_UI = 'illustrated_novel_reader_ui';

// 界面配色。tavern 直接吃酒馆自己的主题变量, 换酒馆主题时面板跟着变。
const INR_THEMES = {
  tavern: {
    name: '跟随酒馆主题（推荐）',
    bg: 'var(--SmartThemeChatTintColor, #0d1117)', panel: 'var(--SmartThemeBotMesBlurTintColor, #161b22)',
    line: 'var(--SmartThemeBorderColor, #30363d)', text: 'var(--SmartThemeBodyColor, #e6edf3)',
    sub: 'var(--SmartThemeEmColor, #8b949e)', accent: 'var(--SmartThemeQuoteColor, #8250df)',
    ok: 'var(--SmartThemeUnderlineColor, #238636)', danger: '#8a3f4d', code: 'rgba(0,0,0,.35)',
  },
  dark: { name: '深灰（GitHub）', bg: '#0d1117', panel: '#161b22', line: '#30363d', text: '#e6edf3', sub: '#8b949e', accent: '#8250df', ok: '#238636', danger: '#8a3f4d', code: '#0d1117' },
  midnight: { name: '午夜蓝', bg: '#0b1220', panel: '#131c31', line: '#26344f', text: '#dce6f7', sub: '#8fa2c4', accent: '#3d6ee0', ok: '#2f9e6f', danger: '#8a3f4d', code: '#0b1220' },
  violet: { name: '紫罗兰', bg: '#150f21', panel: '#1f1633', line: '#372a52', text: '#ece6f7', sub: '#a596c4', accent: '#9b6cf0', ok: '#3f9e78', danger: '#8a3f4d', code: '#150f21' },
  forest: { name: '墨绿', bg: '#0c1512', panel: '#132119', line: '#263b2e', text: '#e2efe6', sub: '#93b3a0', accent: '#3f9e78', ok: '#5aa86a', danger: '#8a3f4d', code: '#0c1512' },
  rose: { name: '暗玫瑰', bg: '#180f12', panel: '#24161b', line: '#43282f', text: '#f4e6ea', sub: '#c396a3', accent: '#d1547a', ok: '#3f9e78', danger: '#8a3f4d', code: '#180f12' },
  sand: { name: '浅色（米白）', bg: '#f6f3ec', panel: '#ffffff', line: '#d9d2c4', text: '#2b2b2b', sub: '#6f6a5e', accent: '#7a5cd0', ok: '#2f7d4f', danger: '#a34a5c', code: '#efeae0' },
  contrast: { name: '高对比（黑金）', bg: '#000000', panel: '#0a0a0a', line: '#4a4a4a', text: '#ffffff', sub: '#c8c8c8', accent: '#f0b400', ok: '#00b050', danger: '#c0392b', code: '#0a0a0a' },
};

async function inrUiConfig() {
  const value = getVariables({ type: 'script' })[INR_UI] || {};
  return {
    theme: INR_THEMES[value.theme] ? value.theme : 'tavern',
    level: value.level === 'pro' ? 'pro' : 'simple',
    aiProvider: value.aiProvider === 'standalone' ? 'standalone' : 'tavern',
  };
}
async function inrSaveUiConfig(value) { return insertOrAssignVariables({ [INR_UI]: value }, { type: 'script' }); }

function inrThemeVars(themeKey) {
  const theme = INR_THEMES[themeKey] || INR_THEMES.tavern;
  return '--inr-bg:' + theme.bg + ';--inr-panel:' + theme.panel + ';--inr-line:' + theme.line
    + ';--inr-text:' + theme.text + ';--inr-sub:' + theme.sub + ';--inr-accent:' + theme.accent
    + ';--inr-ok:' + theme.ok + ';--inr-danger:' + theme.danger + ';--inr-code:' + theme.code;
}

let inrMvuLoader = null;
let inrRecentImageCache = [];
let inrVideoButtonObservers = [];
let inrVideoButtonTimer = null;

function inrPages(text, size) {
  const paragraphs = String(text || '').split(/\n+/).filter(Boolean);
  const pages = []; let current = '';
  for (const paragraph of paragraphs) {
    if (current && current.length + paragraph.length + 1 > size) { pages.push(current); current = paragraph; }
    else current += (current ? '\n' : '') + paragraph;
  }
  if (current) pages.push(current);
  return pages.length ? pages : [''];
}

function inrChapters(text, title, pattern) {
  const regex = new RegExp(pattern, 'i'); const result = []; let name = null; let body = [];
  for (const line of String(text || '').split(/\r?\n/)) {
    if (regex.test(line.trim())) {
      if (name !== null) result.push({ title: name, content: body.join('\n').trim() });
      name = line.trim(); body = [];
    } else body.push(line);
  }
  if (name !== null) result.push({ title: name, content: body.join('\n').trim() });
  return result.length ? result : [{ title, content: String(text || '').trim() }];
}

async function inrLibrary() { return getVariables({ type: 'script' })[INR_LIB] || { books: {} }; }
async function inrSaveLibrary(value) { return insertOrAssignVariables({ [INR_LIB]: value }, { type: 'script' }); }


// v3.5 preserves these proven prompt/API primitives from the live v3.4 baseline.

const INR_PRESET_NAME = '视频提示词预设';

const INR_DEFAULT_PRESETS = [
