const INR_PRESET_ROLES = ['system', 'user', 'assistant'];

function inrPresetNormalize(entry, index) {
  return {
    id: String(entry?.id || 'preset-' + Date.now().toString(36) + '-' + index),
    name: String(entry?.name || '未命名条目'),
    role: INR_PRESET_ROLES.includes(entry?.role) ? entry.role : 'system',
    group: String(entry?.group || ''),
    scope: entry?.scope === 'frames' || entry?.scope === 'text' ? entry.scope : 'all',
    injectionPosition: ['before_context', 'context', 'after_context', 'example'].includes(entry?.injectionPosition) ? entry.injectionPosition : 'context',
    order: Number.isFinite(Number(entry?.order)) ? Number(entry.order) : 1000 + index * 10,
    enabled: entry?.enabled !== false,
    triggerMode: entry?.triggerMode === 'trigger' ? 'trigger' : 'always',
    triggerWords: String(entry?.triggerWords || ''),
    content: String(entry?.content ?? ''),
  };
}

// 预设方案（profile）。共用条目只维护一份, 想要"另一套预设"就新建一个方案。
function inrProfileNormalize(profile, index) {
  return {
    name: String(profile?.name || '方案 ' + (index + 1)),
    entries: (Array.isArray(profile?.entries) ? profile.entries : []).map(inrPresetNormalize),
  };
}

async function inrPresetStore() {
  const value = getVariables({ type: 'script' })[INR_PRESETS];
  // 旧格式 { entries: [...] } 自动迁移成方案结构。
  if (value && Array.isArray(value.entries)) {
    return { active: 'default', profiles: { default: inrProfileNormalize({ name: '默认方案', entries: value.entries }, 0) } };
  }
  const source = value?.profiles && typeof value.profiles === 'object' ? value.profiles : null;
  if (!source || !Object.keys(source).length) {
    return { active: 'default', profiles: { default: inrProfileNormalize({ name: '默认方案', entries: INR_DEFAULT_PRESETS }, 0) } };
  }
  const profiles = {};
  Object.keys(source).forEach((key, index) => { profiles[key] = inrProfileNormalize(source[key], index); });
  const active = profiles[value.active] ? value.active : Object.keys(profiles)[0];
  return { active, profiles };
}
async function inrSaveStore(store) { return insertOrAssignVariables({ [INR_PRESETS]: store }, { type: 'script' }); }

async function inrPresets() {
  const store = await inrPresetStore();
  return { entries: store.profiles[store.active].entries };
}
async function inrSavePresets(value) {
  const store = await inrPresetStore();
  store.profiles[store.active].entries = value.entries.map(inrPresetNormalize);
  return inrSaveStore(store);
}


// 预设占位符。取值为空时, 含该占位符的条目会被整条跳过, 避免发出空标签。
function inrPresetVars(cfg, payload) {
  const at = cfg.videoRefStyle === 'at';
  return {
    '{{时长}}': String(cfg.videoDuration),
    '{{图片1}}': at ? '（@图片1）' : '<Picture 1>',
    '{{图片2}}': at ? '（@图片2）' : '<Picture 2>',
    '{{上下文}}': String(payload?.contextText || ''),
    '{{视觉档案}}': String(payload?.bridgeText || ''),
    '{{首帧}}': String(payload?.firstText || ''),
    '{{尾帧}}': String(payload?.lastText || ''),
    '{{中间正文}}': String(payload?.interstitialText || ''),
    '{{用户需求}}': String(payload?.request || ''),
  };
}

function inrTriggerHit(entry, haystack) {
  if (entry.triggerMode !== 'trigger') return true;
  const words = entry.triggerWords.split(/[,，、;；\s]+/).map(word => word.trim()).filter(Boolean);
  if (!words.length) return false;
  const text = haystack.toLowerCase();
  return words.some(word => text.includes(word.toLowerCase()));
}

// 按条目顺序拼成多轮消息。相邻同 role 条目合并, 避免部分接口不接受连续同角色消息。
function inrPresetMessages(entries, mode, cfg, payload) {
  const vars = inrPresetVars(cfg, payload);
  const haystack = [payload?.contextText, payload?.firstText, payload?.lastText, payload?.interstitialText, payload?.request].filter(Boolean).join('\n');
  const groups = new Set();
  const messages = [];
  for (const entry of [...entries].sort((a, b) => a.order - b.order)) {
    if (!entry.enabled) continue;
    if (entry.scope !== 'all' && entry.scope !== mode) continue;
    if (!inrTriggerHit(entry, haystack)) continue;
    if (entry.group) { if (groups.has(entry.group)) continue; groups.add(entry.group); }
    let content = entry.content;
    if (!content.trim()) continue;
    // 条目里出现的占位符全部取不到值时才跳过整条; 只有部分为空时, 空的那几个写成「（无）」。
    const used = Object.entries(vars).filter(pair => content.includes(pair[0]));
    if (used.length && used.every(pair => !String(pair[1]).trim())) continue;
    for (const [key, value] of used) content = content.split(key).join(String(value).trim() || '（无）');
    const last = messages[messages.length - 1];
    if (last && last.role === entry.role) last.content += '\n\n' + content;
    else messages.push({ role: entry.role, content });
  }
  // 结尾若是 assistant 消息, 追加一句 user 触发, 兼容不接受以 assistant 结尾的接口。
  if (messages.length && messages[messages.length - 1].role === 'assistant') {
    messages.push({ role: 'user', content: '开始输出提示词正文。' });
  }
  return messages;
}

function inrPresetExport(entries, name) {
  return { [name || INR_PRESET_NAME]: { entries: entries.map(entry => ({
    id: entry.id, name: entry.name, role: entry.role, content: entry.content,
    enabled: entry.enabled, triggerMode: entry.triggerMode, triggerWords: entry.triggerWords,
    group: entry.group, scope: entry.scope, injectionPosition: entry.injectionPosition, order: entry.order,
  })) } };
}

// 解析导入的预设文件:
// 1. 智绘姬 / 本脚本导出的上下文预设 { "预设名": { entries: [...] } }
// 2. { entries: [...] } 或裸数组
// 3. 酒馆世界书 { entries: { "0": { comment, content, disable } } }
// 4. 酒馆 OpenAI 预设 { prompts: [...] }
// 5. 纯文本 / Markdown 文档, 整篇作为一个条目
function inrParsePresetFile(filename, text) {
  const base = String(filename || '预设').replace(/\.(json|md|txt|markdown)$/i, '');
  let parsed = null;
  try { parsed = JSON.parse(text); } catch (_) { parsed = null; }
  const fromWorldbook = source => Object.values(source).map((entry, index) => ({
    id: 'wb-' + base + '-' + index,
    name: String(entry?.comment || entry?.name || entry?.key?.[0] || base + ' ' + (index + 1)),
    role: 'system',
    group: String(entry?.group || ''),
    scope: 'all',
    order: Number.isFinite(Number(entry?.order)) ? Number(entry.order) : 1000 + index * 10,
    enabled: entry?.disable === true ? false : entry?.enabled !== false,
    triggerMode: entry?.constant === false ? 'trigger' : 'always',
    triggerWords: Array.isArray(entry?.key) ? entry.key.join(', ') : '',
    content: String(entry?.content || ''),
  }));
  const withOrder = list => list.map((entry, index) => inrPresetNormalize({ order: 1000 + index * 10, ...entry }, index));
  let entries = null;
  if (parsed && typeof parsed === 'object') {
    if (Array.isArray(parsed)) entries = withOrder(parsed);
    else if (Array.isArray(parsed.entries)) entries = withOrder(parsed.entries);
    else if (parsed.entries && typeof parsed.entries === 'object') entries = withOrder(fromWorldbook(parsed.entries));
    else if (Array.isArray(parsed.prompts)) entries = withOrder(parsed.prompts);
    else {
      // 智绘姬格式: 顶层只有一个预设名, 值里带 entries。
      const nested = Object.values(parsed).find(value => value && typeof value === 'object' && Array.isArray(value.entries));
      if (nested) entries = withOrder(nested.entries);
    }
  }
  if (!entries) entries = [inrPresetNormalize({ id: 'doc-' + base + '-' + Date.now().toString(36), name: base, order: 500, enabled: false, content: String(text || '') }, 0)];
  return entries.filter(entry => entry.content.trim());
}

