async function inrApi() {
  const value = getVariables({ type: 'script' })[INR_API] || {};
  return {
    enabled: value.enabled === true,
    url: String(value.url || 'https://api.openai.com/v1'),
    key: String(value.key || ''),
    model: String(value.model || ''),
    temperature: Math.max(0, Math.min(2, Number.isFinite(Number(value.temperature)) ? Number(value.temperature) : 0.8)),
    maxTokens: Math.max(256, Math.min(32000, Number(value.maxTokens) || 2000)),
    headers: String(value.headers || '{}'),
    mergeSystem: value.mergeSystem === true,
    retries: Math.max(0, Math.min(5, Number.isFinite(Number(value.retries)) ? Number(value.retries) : 1)),
    timeout: Math.max(10, Math.min(600, Number(value.timeout) || 120)),
    fallback: value.fallback !== false,
  };
}
async function inrSaveApi(value) { return insertOrAssignVariables({ [INR_API]: value }, { type: 'script' }); }

function inrApiRoot(url) {
  let root = String(url || '').trim().replace(/\/+$/, '').replace(/\/chat\/completions$/i, '');
  if (!/^https?:\/\//i.test(root)) throw new Error('请在独立 API 设置中填写正确的接口地址，例如 https://api.openai.com/v1');
  try { const parsed = new URL(root); if (parsed.pathname === '/' || parsed.pathname === '') root = root.replace(/\/$/, '') + '/v1'; } catch (_) {}
  return root;
}

function inrApiHeaders(api) {
  let extra = {};
  try { extra = JSON.parse(api.headers || '{}'); } catch (_) { throw new Error('独立 API 附加请求头必须是合法 JSON'); }
  const headers = { 'Content-Type': 'application/json', ...extra };
  if (api.key) headers.Authorization = 'Bearer ' + api.key;
  return headers;
}

// 部分接口只接受单条 system 消息, 或不接受 system 之后再出现 system。
function inrApiNormalizeMessages(api, messages) {
  const list = messages.filter(item => String(item?.content || '').trim());
  if (!list.length) throw new Error('预设没有产出任何有效消息，请检查条目开关与占位符');
  if (!api.mergeSystem) return list;
  const system = list.filter(item => item.role === 'system').map(item => item.content).join('\n\n');
  const rest = list.filter(item => item.role !== 'system');
  const merged = system ? [{ role: 'system', content: system }] : [];
  if (!rest.length) merged.push({ role: 'user', content: '开始输出提示词正文。' });
  return merged.concat(rest);
}

async function inrApiChat(api, messages) {
  if (!api.model) throw new Error('请在独立 API 设置中填写模型名');
  const body = JSON.stringify({
    model: api.model, temperature: api.temperature, max_tokens: api.maxTokens, stream: false,
    messages: inrApiNormalizeMessages(api, messages),
  });
  const headers = inrApiHeaders(api);
  const endpoint = inrApiRoot(api.url) + '/chat/completions';
  let lastError = null;
  for (let attempt = 0; attempt <= api.retries; attempt += 1) {
    if (attempt) await new Promise(resolve => setTimeout(resolve, 1200 * attempt));
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), api.timeout * 1000);
    try {
      const response = await fetch(endpoint, { method: 'POST', headers, body, signal: controller.signal });
      if (!response.ok) {
        const detail = (await response.text()).slice(0, 400);
        const error = new Error('独立 API 请求失败（HTTP ' + response.status + '）：' + detail);
        // 4xx 里除了 429 基本都是配置或内容问题, 重试没有意义。
        if (response.status !== 429 && response.status >= 400 && response.status < 500) throw error;
        lastError = error;
        continue;
      }
      const result = await response.json();
      const choice = result?.choices?.[0];
      const text = choice?.message?.content ?? choice?.text ?? result?.content;
      if (!String(text || '').trim()) {
        lastError = new Error('独立 API 没有返回文本内容' + (choice?.finish_reason ? '（finish_reason: ' + choice.finish_reason + '）' : ''));
        continue;
      }
      return String(text);
    } catch (error) {
      if (error?.name === 'AbortError') lastError = new Error('独立 API 请求超时（' + api.timeout + ' 秒）');
      else lastError = error;
      if (/HTTP 4/.test(String(lastError.message))) break;
    } finally { clearTimeout(timer); }
  }
  throw lastError || new Error('独立 API 请求失败');
}

async function inrApiModels(api) {
  const response = await fetch(inrApiRoot(api.url) + '/models', { headers: inrApiHeaders(api) });
  if (!response.ok) throw new Error('拉取模型列表失败（HTTP ' + response.status + '）');
  const result = await response.json();
  const list = Array.isArray(result?.data) ? result.data : Array.isArray(result?.models) ? result.models : [];
  return list.map(item => String(item?.id || item?.name || '')).filter(Boolean).sort();
}


function inrClone(value) { return value == null ? value : JSON.parse(JSON.stringify(value)); }
function inrMerge(target, source) {
  for (const key of Object.keys(source || {})) {
    const value = source[key];
    if (value == null || value === '') continue;
    if (typeof value === 'object' && !Array.isArray(value)) {
      target[key] ||= {};
      inrMerge(target[key], value);
    } else target[key] = value;
  }
  return target;
}

const INR_MVU_BRIDGE_FALLBACK = 'illustrated_novel_reader_mvu_bridge_v1';

function inrMvuApi() {
  if (typeof Mvu !== 'undefined' && Mvu) return Mvu;
  return window?.Mvu || null;
}

async function inrMvuData(messageId = 'latest') {
  try {
    if (!inrMvuApi() && typeof waitGlobalInitialized === 'function') {
      try {
        await Promise.race([
          waitGlobalInitialized('Mvu'),
          new Promise(resolve => setTimeout(resolve, 1500)),
        ]);
      } catch (_) {}
    }
    if (!inrMvuApi() && !inrMvuLoader) {
      inrMvuLoader = import('https://testingcf.jsdelivr.net/gh/MagicalAstrogy/MagVarUpdate@beta/artifact/bundle.js').catch(error => {
        console.warn('[图文小说阅读器] MVU Beta 加载失败', error);
        inrMvuLoader = null;
        return null;
      });
    }
    if (!inrMvuApi() && inrMvuLoader) await inrMvuLoader;
    const api = inrMvuApi();
    if (!api || typeof api.getMvuData !== 'function') return null;
    return inrClone(api.getMvuData({ type: 'message', message_id: messageId })) || { initialized_lorebooks: {}, stat_data: {} };
  } catch (_) { return null; }
}

function inrFallbackBridge(messageId = 'latest') {
  try {
    return inrClone(getVariables({ type: 'message', message_id: messageId })?.[INR_MVU_BRIDGE_FALLBACK]) || {};
  } catch (_) { return {}; }
}

async function inrReaderStateData(messageId = 'latest') {
  const data = (await inrMvuData(messageId)) || { initialized_lorebooks: {}, stat_data: {} };
  data.stat_data ||= {};
  const fallback = inrFallbackBridge(messageId);
  if (fallback && typeof fallback === 'object') {
    data.stat_data.__image_bridge = inrMerge(data.stat_data.__image_bridge || {}, fallback);
  }
  return data;
}

async function inrSaveBridge(bridge, messageId = 'latest') {
  if (!bridge || typeof bridge !== 'object') return { fallback: false, mvu: false };
  const merged = inrMerge(inrFallbackBridge(messageId), inrClone(bridge));
  let fallbackSaved = false;
  try {
    await insertOrAssignVariables({ [INR_MVU_BRIDGE_FALLBACK]: merged }, { type: 'message', message_id: messageId });
    fallbackSaved = true;
  } catch (error) {
    console.warn('[图文小说阅读器] 消息变量桥接保存失败', error);
  }

  const api = inrMvuApi() || (await inrMvuData(messageId), inrMvuApi());
  if (!api || typeof api.replaceMvuData !== 'function') return { fallback: fallbackSaved, mvu: false };
  try {
    const data = (await inrMvuData(messageId)) || { initialized_lorebooks: {}, stat_data: {} };
    data.initialized_lorebooks ||= {};
    data.stat_data ||= {};
    data.stat_data.__image_bridge = inrMerge(data.stat_data.__image_bridge || {}, merged);
    await api.replaceMvuData(data, { type: 'message', message_id: messageId });
    return { fallback: fallbackSaved, mvu: true };
  } catch (error) {
    console.warn('[图文小说阅读器] MVU 桥接保存失败，已保留消息变量回退', error);
    return { fallback: fallbackSaved, mvu: false };
  }
}



