function inrRecentImages() {
  const documents = inrChatDocuments();
  let chat = [];
  try {
    chat = SillyTavern.getContext?.()?.chat || [];
  } catch (_) {}
  const seen = new Set();
  const candidates = documents.flatMap(doc => Array.from(doc.querySelectorAll('.mes .mes_text img')).map(image => {
    const message = image.closest('.mes');
    const rawMessageId = message?.getAttribute('mesid') ?? message?.dataset?.mesid ?? message?.dataset?.messageId;
    const messageId = /^\d+$/.test(String(rawMessageId ?? '')) ? Number(rawMessageId) : null;
    return { src: image.currentSrc || image.src, messageId, element: image };
  })).filter(item => {
    if (!item.src || !Number.isInteger(item.messageId) || seen.has(item.src)) return false;
    seen.add(item.src); return true;
  }).sort((a, b) => a.messageId - b.messageId);
  const imageCounts = new Map();
  const images = candidates.map(item => {
    const imageIndex = imageCounts.get(item.messageId) || 0;
    imageCounts.set(item.messageId, imageIndex + 1);
    const tags = Array.from(String(chat[item.messageId]?.mes || '').matchAll(/<image>image###([\s\S]*?)###<\/image>/gi));
    // label 保留换行, 让模型能逐字段比对两张图的生图提示词; short 只用于下拉框和提示。
    const raw = tags[imageIndex]?.[1] || '';
    const label = raw.replace(/[ \t]+/g, ' ').replace(/\n{3,}/g, '\n\n').trim() || ('聊天插图 ' + (item.messageId + 1) + '-' + (imageIndex + 1));
    const short = label.replace(/\s+/g, ' ').trim();
    return { id: 'inr-image-' + item.messageId + '-' + imageIndex, ...item, imageIndex, label, short };
  });
  inrRecentImageCache = images;
  return images;
}

function inrTextBetweenImages(firstSource, lastSource) {
  const images = inrRecentImageCache.length ? inrRecentImageCache : inrRecentImages();
  const first = images.find(item => item.id === firstSource);
  const last = images.find(item => item.id === lastSource);
  const chat = SillyTavern.getContext?.()?.chat || [];
  if (!first || !last || first.messageId > last.messageId) return '';
  const tagPattern = /<image>image###[\s\S]*?###<\/image>/gi;
  const fragments = [];
  for (let messageId = first.messageId; messageId <= last.messageId; messageId += 1) {
    let text = String(chat[messageId]?.mes || '');
    const tags = Array.from(text.matchAll(tagPattern));
    if (messageId === first.messageId) text = text.slice((tags[first.imageIndex]?.index ?? text.length) + (tags[first.imageIndex]?.[0].length ?? 0));
    if (messageId === last.messageId) text = text.slice(0, tags[last.imageIndex]?.index ?? text.length);
    fragments.push(text);
  }
  return fragments.join('\n').replace(/<video[\s\S]*?<\/video>|<inr_bridge>[\s\S]*?<\/inr_bridge>|<image>[\s\S]*?<\/image>/gi, ' ').replace(/\[[^\]]*过场视频[^\]]*\]\([^)]*\)/gi, ' ').replace(/\s+/g, ' ').trim().slice(0, 2400);
}

function inrStripChatTags(text) {
  return String(text || '')
    .replace(/<video[\s\S]*?<\/video>/gi, ' ')
    .replace(/<inr_bridge>[\s\S]*?<\/inr_bridge>/gi, ' ')
    .replace(/<image>[\s\S]*?<\/image>/gi, ' ')
    .replace(/<details[\s\S]*?<\/details>/gi, ' ')
    .replace(/<!--[\s\S]*?-->/g, ' ')
    .replace(/\[[^\]]*视频[^\]]*\]\([^)]*\)/gi, ' ')
    .replace(/[ \t]+/g, ' ')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

// 取最近若干条聊天消息作为文生视频的剧情上下文。
function inrChatContextText(limit) {
  let context = null;
  try { context = SillyTavern.getContext?.(); } catch (_) {}
  const chat = context?.chat || [];
  const parts = [];
  for (const message of chat.slice(-Math.max(1, Number(limit) || 6))) {
    const text = inrStripChatTags(message?.mes);
    if (!text) continue;
    const who = message?.is_user ? (context?.name1 || '玩家') : (message?.name || context?.name2 || '角色');
    parts.push(who + '：' + text);
  }
  return parts.join('\n\n').slice(-6000);
}

async function inrBridgeText() {
  try {
    const state = (await inrReaderStateData())?.stat_data?.__image_bridge;
    if (!state || typeof state !== 'object') return '';
    return JSON.stringify(state).slice(0, 3000);
  } catch (_) { return ''; }
}

function inrCleanPrompt(raw) {
  return String(raw || '')
    .replace(/<think>[\s\S]*?<\/think>/gi, ' ')
    .replace(/```[a-z]*\n?/gi, '')
    .replace(/<\/?image>|###/g, ' ')
    .replace(/[ \t]+/g, ' ')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

// 生成视频提示词。优先使用独立 API, 失败时按设置回退到酒馆当前 API。
function inrVideoHtml(url, prompt) {
  const player = '\n\n<video controls playsinline preload="metadata" style="width:100%;max-height:45vh;background:#000" src="' + inrEscape(url) + '"></video>\n\n[在新窗口打开视频](' + url + ')';
  const detail = String(prompt || '').trim()
    ? '\n\n<details><summary>本段视频提示词</summary>\n\n' + inrEscape(prompt).replace(/\n/g, '<br>') + '\n\n</details>'
    : '';
  return player + detail;
}

async function inrInsertVideoAtImage(source, url, prompt) {
  const image = inrRecentImageCache.find(item => item.id === source);
  const context = SillyTavern.getContext?.();
  if (!image || !Number.isInteger(image.messageId) || !Number.isInteger(image.imageIndex) || typeof context?.updateMessages !== 'function') return false;
  const message = context.chat?.[image.messageId];
  if (!message?.mes) return false;
  const tags = Array.from(String(message.mes).matchAll(/<image>image###[\s\S]*?###<\/image>/gi));
  const target = tags[image.imageIndex];
  if (!target) return false;
  const video = inrVideoHtml(url, prompt);
  const start = target.index + target[0].length;
  const updated = message.mes.slice(0, start) + video + message.mes.slice(start);
  await context.updateMessages({ index: image.messageId, patch: { mes: updated } });
  return true;
}

async function inrInsertVideoAtMessageEnd(url, prompt) {
  const context = SillyTavern.getContext?.();
  const chat = context?.chat || [];
  const index = chat.length - 1;
  if (index < 0 || typeof context?.updateMessages !== 'function') return false;
  const message = chat[index];
  if (typeof message?.mes !== 'string') return false;
  await context.updateMessages({ index, patch: { mes: message.mes + inrVideoHtml(url, prompt) } });
  return true;
}

async function inrImageBlob(source, file) {
  if (file) return file;
  if (!source) throw new Error('请选择首帧和尾帧图片，或手动选择本地图片');
  const url = inrRecentImageCache.find(item => item.id === source)?.src || source;
  try {
    const response = await fetch(url, { credentials: 'omit' });
    if (response.ok) return response.blob();
  } catch (_) {}
  throw new Error('无法读取这张聊天插图。请点击“刷新最近插图”后重试；若图片来自不允许跨域读取的外部站点，请改用手动选择本地图片');
}

async function inrUploadImage(cfg, baseUrl, blob, filename) {
  const form = new FormData(); form.append('image', blob, filename); form.append('overwrite', 'true');
  const response = await inrComfyFetch(cfg, baseUrl + '/upload/image', { method: 'POST', body: form });
  if (!response.ok) throw new Error('上传图片到 ComfyUI 失败（HTTP ' + response.status + '）' + inrComfyHttpHint(response.status));
  const result = await response.json();
  if (!result?.name) throw new Error('ComfyUI 未返回上传文件名');
  return result.subfolder ? result.subfolder + '/' + result.name : result.name;
}

function inrSourceUrl(source) { return inrRecentImageCache.find(item => item.id === source)?.src || source; }

// 聊天插图若本来就是 ComfyUI 的 /view 输出, 直接复用文件名, 不必重新上传。
// 智绘姬可能用局域网地址出图, 而这里可能走穿透域名, 所以对所有候选地址都比对一次。
function inrComfyImageName(cfg, baseUrl, source) {
  const origins = new Set();
  for (const url of [baseUrl, cfg?.videoPublicUrl].concat(inrComfyCandidates(cfg || {}))) {
    if (!url) continue;
    try { origins.add(new URL(url).origin); } catch (_) {}
  }
  try {
    const url = new URL(inrSourceUrl(source), baseUrl);
    if (!origins.has(url.origin) || !/\/view$/i.test(url.pathname)) return null;
    const filename = url.searchParams.get('filename');
    if (!filename) return null;
    const subfolder = url.searchParams.get('subfolder');
    return subfolder ? subfolder + '/' + filename : filename;
  } catch (_) { return null; }
}

async function inrComfyInputImage(cfg, baseUrl, source, file, filename) {
  if (!file) {
    const direct = inrComfyImageName(cfg, baseUrl, source);
    if (direct) return direct;
  }
  return inrUploadImage(cfg, baseUrl, await inrImageBlob(source, file), filename);
}

function inrVideoOutput(history, promptId) {
  const outputs = history?.[promptId]?.outputs || {};
  for (const output of Object.values(outputs)) for (const key of ['videos', 'gifs', 'images']) for (const item of output?.[key] || []) {
    if (item?.filename && /\.(mp4|webm|mov|mkv)$/i.test(item.filename)) return item;
  }
  return null;
}

function inrSetWorkflowValue(workflow, binding, value, label, optional = false) {
  if (!binding) { if (optional) return false; throw new Error('请在视频设置中填写' + label + '映射'); }
  const match = String(binding).match(/^(\d+)\.([\w.-]+)$/);
  if (!match || !workflow[match[1]]?.inputs || !(match[2] in workflow[match[1]].inputs)) {
    throw new Error(label + '映射无效：' + binding + '。格式应为“节点ID.输入名”，可在「生成后端」页点「自动识别映射」重新识别');
  }
  workflow[match[1]].inputs[match[2]] = value;
  return true;
}

