// 文生视频可以单独用一套时长和分辨率；没开单独设置时就沿用主设置。
function inrModeConfig(cfg, mode) {
  if (mode !== 'text' || !cfg.videoTextSeparate) return cfg;
  return {
    ...cfg,
    videoDuration: cfg.videoDurationText || cfg.videoDuration,
    videoResolution: cfg.videoResolutionText || cfg.videoResolution,
  };
}

// 主菜单换时长时，把预设里「H3时长模板」分组切到同一档。
async function inrSyncDurationPreset(seconds) {
  const store = await inrPresetStore();
  const entries = store.profiles[store.active].entries;
  const group = entries.filter(entry => entry.group === 'H3时长模板');
  if (!group.length) return { matched: false, empty: true };
  const want = String(seconds);
  // 只认 id 和条目名, 不去正文里模糊搜——正文里的「1.7 秒」之类会误命中。
  const pattern = new RegExp('(^|[^0-9.])' + want + '\\s*(秒|S|s)(?![0-9])');
  const hit = group.find(entry => entry.id === 'inr-dur-' + want)
    || group.find(entry => pattern.test(entry.name));
  if (!hit) return { matched: false, empty: false };
  for (const entry of group) entry.enabled = entry === hit;
  await inrSaveStore(store);
  return { matched: true, name: hit.name };
}

// 把分辨率写进工作流。优先改 ResolutionSelector 的 megapixels（保留工作流自己的横竖屏设置），
// 没有这个节点时才直接写 H3 节点的 width / height。
function inrApplyResolution(workflow, bindings, key) {
  const preset = inrResolution(key);
  if (!preset) return { applied: false, skipped: true, preset: null };
  const mpOk = inrSetWorkflowValue(workflow, bindings.megapixels, preset.mp, '分辨率档位', true);
  const wOk = inrSetWorkflowValue(workflow, bindings.width, preset.w, '宽度', true);
  const hOk = inrSetWorkflowValue(workflow, bindings.height, preset.h, '高度', true);
  return { applied: mpOk || (wOk && hOk), skipped: false, preset };
}

