// 工作流可视化与 AI 修复。把节点结构压成清单发给独立 API，让它算出映射该填哪个节点，
// 返回后逐项对着工作流校验，编造的节点会被丢掉，不会写进设置里。
// ---------------------------------------------------------------------------
let inrLastError = '';

function inrWorkflowSummary(workflow, limit = 150) {
  const lines = [];
  for (const [id, node] of Object.entries(workflow || {})) {
    if (lines.length >= limit) { lines.push('…（节点太多，已截断）'); break; }
    const inputs = Object.entries(node?.inputs || {}).map(pair => {
      const key = pair[0];
      const value = pair[1];
      if (Array.isArray(value)) return key + ' <- 节点' + value[0];
      if (typeof value === 'string') {
        const text = value.replace(/\s+/g, ' ').trim();
        return key + ' = "' + text.slice(0, 24) + (text.length > 24 ? '…' : '') + '"';
      }
      return key + ' = ' + value;
    });
    lines.push(id + ' [' + (node?.class_type || '未知') + '] ' + inputs.join('，'));
  }
  return lines.join('\n');
}

// 所有可以被写值的输入（连线过来的不算），用于给映射输入框做下拉候选。
function inrBindingOptions(workflow) {
  const options = [];
  for (const [id, node] of Object.entries(workflow || {})) {
    for (const [key, value] of Object.entries(node?.inputs || {})) {
      if (Array.isArray(value)) continue;
      options.push({ value: id + '.' + key, label: id + '.' + key + '　' + (node?.class_type || '') });
    }
  }
  return options;
}

