  '常见原因参考：ComfyUI 没加 --listen 0.0.0.0 或 --enable-cors-header 导致跨域失败；手机填了 127.0.0.1；',
  '防火墙没放行端口；酒馆是 https 而 ComfyUI 是 http 被混合内容拦；云平台要 token 没填请求头；',
  '节点映射填错或为空导致时长、分辨率没生效；工作流导入的是画布格式而不是 API 格式；模型文件名和工作流里写的不一致。',
].join('\n');

function inrParseJsonLoose(text) {
  const raw = String(text || '').replace(/```[a-z]*/gi, '').trim();
  const match = raw.match(/\{[\s\S]*\}/);
  if (!match) throw new Error('AI 没有返回 JSON');
  return JSON.parse(match[0]);
}

// 校验 AI 给出的映射：节点和输入必须真实存在，否则丢弃并记下来。
function inrValidateBindings(workflow, guess) {
  const keys = ['first', 'last', 'prompt', 'seed', 'duration', 'megapixels', 'width', 'height'];
  const good = {};
  const bad = [];
  for (const key of keys) {
    const value = String(guess?.[key] || '').trim();
    if (!value) { good[key] = ''; continue; }
    const match = value.match(/^(\d+)\.([\w.-]+)$/);
    const node = match && workflow[match[1]];
    const exists = node && node.inputs && match[2] in node.inputs;
    // 连线过来的输入不能当写入目标：写进去会切断连线, 基本都是 AI 认错了。
    const isLink = exists && Array.isArray(node.inputs[match[2]]);
    if (exists && !isLink) good[key] = value;
    else { good[key] = ''; bad.push(key + '=' + value + (isLink ? '（这个输入是连线过来的，不能直接写值）' : '')); }
  }
  return { bindings: good, bad };
}

// AI 分析统一入口：可以用酒馆当前正在用的 API，也可以用「独立 API」页配的那个。
async function inrAiChat(messages, provider) {
  if (provider === 'standalone') {
    const api = await inrApi();
    if (!api.model) throw new Error('独立 API 还没填模型名，去「独立 API」页补上，或者把上面的分析用 API 切成「酒馆当前 API」');
    return inrApiChat(api, messages);
  }
  const raw = await generateRaw({ user_input: '', should_silence: true, ordered_prompts: messages });
  if (!String(raw || '').trim()) throw new Error('酒馆当前 API 没有返回内容，换成独立 API 再试试');
  return String(raw);
}

async function inrAiFixBindings(workflow, provider) {
  const summary = inrWorkflowSummary(workflow);
  const text = await inrAiChat([
    { role: 'system', content: INR_FIX_PROMPT },
    { role: 'user', content: '节点清单：\n' + summary },
  ], provider);
  return inrValidateBindings(workflow, inrParseJsonLoose(text));
}
// 从 API 格式工作流里自动认出首帧 / 尾帧 / 提示词 / 种子 / 时长该写到哪个节点。
function inrDetectBindings(workflow) {
  const found = { first: '', last: '', prompt: '', seed: '', duration: '', megapixels: '', width: '', height: '', unet: '', clip: '', vae: '', audioVae: '' };
  if (!workflow || typeof workflow !== 'object') return found;
  const nodeOf = value => (Array.isArray(value) ? String(value[0]) : '');
  const has = (id, key) => id && workflow[id]?.inputs && key in workflow[id].inputs;
  const core = Object.entries(workflow).find(pair => pair[1]?.class_type === 'MiniMaxH3ReferenceToVideo')
    || Object.entries(workflow).find(pair => /MiniMaxH3/i.test(String(pair[1]?.class_type || '')));
  if (core) {
    const inputs = core[1].inputs || {};
    const refs = Object.keys(inputs).filter(key => /^ref_images\.ref_image_\d+$/.test(key)).sort();
    const firstNode = nodeOf(inputs[refs[0]]);
    const lastNode = nodeOf(inputs[refs[1]]);
    if (has(firstNode, 'image')) found.first = firstNode + '.image';
    if (has(lastNode, 'image')) found.last = lastNode + '.image';
    // 提示词可能是外接的字符串节点, 也可能直接写在本节点的 widget 上。
    const promptNode = nodeOf(inputs.prompt);
    if (has(promptNode, 'value')) found.prompt = promptNode + '.value';
    else if (has(promptNode, 'text')) found.prompt = promptNode + '.text';
    else if ('prompt' in inputs) found.prompt = core[0] + '.prompt';
    // 时长: length 一般接在 ComfyMathExpression 上, 再往上是一个 PrimitiveFloat。
    const lengthNode = nodeOf(inputs.length);
    if (lengthNode && workflow[lengthNode]) {
      const seconds = nodeOf(workflow[lengthNode].inputs?.['values.a']);
      if (has(seconds, 'value')) found.duration = seconds + '.value';
      else if (has(lengthNode, 'value')) found.duration = lengthNode + '.value';
    }
    if (!found.duration && has(lengthNode, 'value')) found.duration = lengthNode + '.value';
    // 分辨率：宽高若是直接写死的数字就直接改它, 若是连线过来的就改上游 ResolutionSelector 的 megapixels。
    if (typeof inputs.width === 'number') found.width = core[0] + '.width';
    if (typeof inputs.height === 'number') found.height = core[0] + '.height';
    const sizeNode = nodeOf(inputs.width);
    if (has(sizeNode, 'megapixels')) found.megapixels = sizeNode + '.megapixels';
    // 模型：视频 VAE 和音频 VAE 靠它们各自接到哪个输入来区分。
    const videoVae = nodeOf(inputs.vae);
    const audioVae = nodeOf(inputs.audio_vae);
    if (has(videoVae, 'vae_name')) found.vae = videoVae + '.vae_name';
    if (has(audioVae, 'vae_name')) found.audioVae = audioVae + '.vae_name';
    const clipNode = nodeOf(inputs.clip);
    if (has(clipNode, 'clip_name')) found.clip = clipNode + '.clip_name';
  }
  if (!found.unet) {
    const unet = Object.entries(workflow).find(pair => pair[1]?.inputs && 'unet_name' in pair[1].inputs);
    if (unet) found.unet = unet[0] + '.unet_name';
  }
  if (!found.clip) {
    const clip = Object.entries(workflow).find(pair => pair[1]?.inputs && 'clip_name' in pair[1].inputs);
    if (clip) found.clip = clip[0] + '.clip_name';
  }
  if (!found.vae || !found.audioVae) {
    const vaes = Object.entries(workflow).filter(pair => pair[1]?.inputs && 'vae_name' in pair[1].inputs);
    if (!found.vae && vaes[0]) found.vae = vaes[0][0] + '.vae_name';
    if (!found.audioVae && vaes[1]) found.audioVae = vaes[1][0] + '.vae_name';
  }
  if (!found.megapixels) {
    const selector = Object.entries(workflow).find(pair => pair[1]?.inputs && 'megapixels' in pair[1].inputs);
    if (selector) found.megapixels = selector[0] + '.megapixels';
  }
  if (!found.duration) {
    const float = Object.entries(workflow).find(pair => pair[1]?.class_type === 'PrimitiveFloat' && pair[1]?.inputs && 'value' in pair[1].inputs);
    if (float) found.duration = float[0] + '.value';
  }
  const noise = Object.entries(workflow).find(pair => pair[1]?.inputs && 'noise_seed' in pair[1].inputs);
  if (noise) found.seed = noise[0] + '.noise_seed';
  else {
    const seed = Object.entries(workflow).find(pair => pair[1]?.inputs && 'seed' in pair[1].inputs);
    if (seed) found.seed = seed[0] + '.seed';
  }
  if (!found.prompt) {
    const text = Object.entries(workflow).find(pair => pair[1]?.class_type === 'PrimitiveStringMultiline' && pair[1]?.inputs && 'value' in pair[1].inputs);
    if (text) found.prompt = text[0] + '.value';
  }
  return found;
}

function inrVideoSeed(cfg) {
  return Number.isSafeInteger(cfg.videoSeed) && cfg.videoSeed >= 0
    ? cfg.videoSeed
    : Math.floor(Math.random() * 9007199254740991);
}

function inrModeWorkflow(cfg, mode) {
  if (mode !== 'text') return inrClone(cfg.videoWorkflow || INR_VIDEO_WORKFLOW);
  if (cfg.videoTextWorkflow) return inrClone(cfg.videoTextWorkflow);
  // 没有为当前聊天单独导入时，使用阅读器内置的 H3 文生视频 API 工作流。
  return inrClone(INR_TEXT_VIDEO_WORKFLOW);
}

function inrUsesH3Fl2va(cfg, mode) {
  return Object.values(inrModeWorkflow(cfg, mode)).some(node => node?.class_type === 'MiniMaxH3ReferenceToVideo');
}

// ---------------------------------------------------------------------------
// ComfyUI 地址解析。支持填多个地址（局域网 / 内网穿透域名），自动探测第一个连得上的；
// 另可单独指定「视频外链地址」，用于写进聊天消息的 <video src>，方便手机远程播放。
// ---------------------------------------------------------------------------
let inrComfyBaseCache = null;

// 云平台的 ComfyUI 常要带 token 或 session, 统一从这里出请求。
function inrComfyHeaders(cfg) {
  try { return JSON.parse(cfg?.videoComfyHeaders || '{}') || {}; }
  catch (_) { throw new Error('ComfyUI 自定义请求头必须是合法 JSON，例如 {"Authorization":"Bearer xxx"}'); }
}

function inrComfyFetch(cfg, url, options) {
  const init = { ...(options || {}) };
  init.headers = { ...inrComfyHeaders(cfg), ...(init.headers || {}) };
  if (cfg?.videoComfyCookies) init.credentials = 'include';
  return fetch(url, init);
}

function inrComfyHttpHint(status) {
  if (status === 401 || status === 403) return '（看起来需要鉴权：在「生成后端」页填 ComfyUI 自定义请求头，或勾选携带 Cookie）';
  if (status === 404) return '（地址不对：填的应该是 ComfyUI 根地址，不要带 /prompt 之类的路径）';
  return '';
}

function inrComfyCandidates(cfg) {
  const seen = new Set();
  return [cfg.videoUrl].concat(String(cfg.videoUrlList || '').split(/[\n,;，；]+/))
    .map(url => String(url || '').trim().replace(/\/+$/, ''))
    .filter(url => {
      if (!/^https?:\/\//i.test(url) || seen.has(url)) return false;
      seen.add(url);
      return true;
    });
}

async function inrComfyProbe(cfg, url, timeout = 6000) {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeout);
  try {
    const response = await inrComfyFetch(cfg, url + '/system_stats', { signal: controller.signal });
    return response.ok;
  } catch (_) { return false; }
  finally { clearTimeout(timer); }
}

async function inrComfyBase(cfg, force) {
  const candidates = inrComfyCandidates(cfg);
  if (!candidates.length) throw new Error('请填写正确的 ComfyUI 地址，例如 http://127.0.0.1:8188');
  if (!force && inrComfyBaseCache && candidates.includes(inrComfyBaseCache)) return inrComfyBaseCache;
  // 只有一个地址时不额外探测, 直接用, 失败会在排队时报出原始错误。
  if (candidates.length === 1) { inrComfyBaseCache = candidates[0]; return candidates[0]; }
  for (const url of candidates) {
    if (await inrComfyProbe(cfg, url)) { inrComfyBaseCache = url; return url; }
  }
  throw new Error('填写的 ComfyUI 地址都连不上：' + candidates.join('、')
    + '。手机远程时请确认内网穿透已开启，且 ComfyUI 以 --listen 0.0.0.0 --enable-cors-header 启动');
}

function inrComfyPublic(cfg, base) {
  return String(cfg.videoPublicUrl || '').replace(/\/+$/, '') || base;
}

// 从 ComfyUI 问「这个节点的这个下拉里有哪些可选项」，用来列出服务器上实际有的模型文件。
async function inrComfyModelList(cfg, baseUrl, classType, inputName) {
  const response = await inrComfyFetch(cfg, baseUrl + '/object_info/' + encodeURIComponent(classType));
  if (!response.ok) throw new Error('拉取 ' + classType + ' 失败（HTTP ' + response.status + '）' + inrComfyHttpHint(response.status));
  const data = await response.json();
  const node = data?.[classType]?.input || {};
  const spec = node.required?.[inputName] ?? node.optional?.[inputName];
  const list = Array.isArray(spec) ? spec[0] : null;
  return Array.isArray(list) ? list.map(String) : [];
}

async function inrVideoPromptText(cfg, opts) {
  if (opts.mode === 'text') {
    const contextText = inrChatContextText(cfg.videoContext);
    if (!contextText) throw new Error('当前聊天没有可用于文生视频的剧情上下文');
    return inrComposeVideoPrompt(cfg, 'text', {
      contextText,
      bridgeText: await inrBridgeText(),
      request: String(opts.request || ''),
    });
  }
  const images = inrRecentImageCache.length ? inrRecentImageCache : inrRecentImages();
  return inrComposeVideoPrompt(cfg, 'frames', {
    contextText: inrChatContextText(cfg.videoContext),
    bridgeText: await inrBridgeText(),
    firstText: images.find(item => item.id === opts.firstSource)?.label || '小说场景的起始画面',
    lastText: images.find(item => item.id === opts.lastSource)?.label || '小说场景的结束画面',
    interstitialText: inrTextBetweenImages(opts.firstSource, opts.lastSource),
    request: String(opts.request || ''),
  });
}

// ---------------------------------------------------------------------------
// 提示词确认。auto 直接送去生成；manual 先弹出可编辑的提示词, 确认后才发给后端。
// ---------------------------------------------------------------------------
const INR_CANCEL = '__inr_cancelled__';
function inrIsCancel(error) { return String(error?.message || error) === INR_CANCEL; }

function inrReviewPanelHtml(cfg, mode, prompt) {
  return '<div class="inr inr-review"><style>'
    + '.inr-review{color:#e6edf3;text-align:left}'
    + '.inr-review textarea{width:100%;box-sizing:border-box;min-height:280px;padding:8px;background:#161b22;color:#e6edf3;border:1px solid #30363d;border-radius:4px;font-family:monospace;font-size:13px}'
    + '.inr-review small{color:#8b949e;display:block;margin-top:6px}'
    + '.inr-review .inr-review-bar{display:flex;gap:8px;flex-wrap:wrap;margin-top:10px}'
    + '.inr-review button{padding:7px 14px;border:0;border-radius:4px;background:#238636;color:#fff;cursor:pointer}'
    + '.inr-review button[data-rv="regen"]{background:#8250df}'
    + '.inr-review button[data-rv="cancel"]{background:#6e2836}'
    + '</style>'
    + '<h3>确认视频提示词</h3>'
    + '<small>模式：' + (mode === 'text' ? '文生视频' : '首尾帧生视频') + '　时长：' + cfg.videoDuration + ' 秒　后端：' + (cfg.videoBackend === 'http' ? '自定义 HTTP API' : 'ComfyUI') + '</small>'
    + '<textarea data-rv-text>' + inrEscape(prompt) + '</textarea>'
    + '<small>可以直接改这段文字，改完点「确认并生成」就按修改后的内容送去渲染。</small>'
    + '<div class="inr-review-bar">'
    + '<button type="button" data-rv="send">确认并生成</button>'
    + '<button type="button" data-rv="regen">让 AI 重写一版</button>'
    + '<button type="button" data-rv="cancel">取消</button>'
    + '</div></div>';
}

async function inrReviewPrompt(cfg, mode, prompt) {
  return new Promise(resolve => {
    let decided = null;
    const popup = new SillyTavern.Popup(inrReviewPanelHtml(cfg, mode, prompt), SillyTavern.POPUP_TYPE.DISPLAY, '', {
      wide: true, large: true, okButton: '关闭', cancelButton: false,
      onOpen: popupRef => {
        const $dlg = $(popupRef.dlg);
        $dlg.on('click', '[data-rv]', function () {
          decided = { action: String($(this).attr('data-rv')), text: String($dlg.find('[data-rv-text]').val() || '') };
          try { popupRef.completeAffirmative(); }
          catch (_) { $dlg.find('.popup-button-ok').trigger('click'); }
        });
      },
    });
    popup.show().then(() => resolve(decided || { action: 'cancel', text: '' }));
  });
}

// 生成提示词, 需要时走人工确认；返回最终要送给后端的提示词。
async function inrResolvePrompt(cfg, opts) {
  for (let round = 0; round < 20; round += 1) {
    const prompt = await inrVideoPromptText(cfg, opts);
    if (cfg.videoReview !== 'manual') return prompt;
    const decision = await inrReviewPrompt(cfg, opts.mode || 'frames', prompt);
    if (decision.action === 'send') {
      const edited = decision.text.trim();
      if (!edited) throw new Error('提示词为空，已取消');
      return edited;
    }
    if (decision.action !== 'regen') throw new Error(INR_CANCEL);
    toastr.info('正在重写提示词…');
  }
  throw new Error(INR_CANCEL);
}

async function inrGenerateComfyVideo(cfg, opts) {
  const baseUrl = await inrComfyBase(cfg);
  const textMode = opts.mode === 'text';
  const workflow = inrModeWorkflow(cfg, opts.mode);
  const bindings = textMode ? cfg.videoTextBindings : cfg.videoBindings;
  if (!textMode) {
    const [firstName, lastName] = await Promise.all([
      inrComfyInputImage(cfg, baseUrl, opts.firstSource, opts.firstFile, 'novel_first.png'),
      inrComfyInputImage(cfg, baseUrl, opts.lastSource, opts.lastFile, 'novel_last.png'),
    ]);
    inrSetWorkflowValue(workflow, cfg.videoBindings.first, firstName, '首帧');
    inrSetWorkflowValue(workflow, cfg.videoBindings.last, lastName, '尾帧');
  }
  const prompt = await inrResolvePrompt(cfg, opts);
  inrSetWorkflowValue(workflow, bindings.prompt, prompt, '提示词');
  inrSetWorkflowValue(workflow, bindings.seed, inrVideoSeed(cfg), '随机种子', true);
  // 时长必须真的写进工作流, 否则会按工作流里存着的秒数跑, 和面板选的不一致。
  const durationOk = inrSetWorkflowValue(workflow, bindings.duration, cfg.videoDuration, '视频时长', true);
  if (!durationOk) {
    toastr.warning('时长映射为空，本次会按工作流里保存的秒数生成，不是面板选的 ' + cfg.videoDuration + ' 秒。到「生成后端」页点「自动识别映射」修一下。');
  }
  const size = inrApplyResolution(workflow, bindings, cfg.videoResolution);
  if (!size.skipped && !size.applied) {
    toastr.warning('分辨率映射为空，本次按工作流里保存的分辨率生成。到「生成后端」页点「自动识别映射」修一下。');
  }
  // 模型覆盖：留空就用工作流里存的，填了就写进去（云端和本地的模型文件名常常不一样）。
  const modelLabels = { unet: '主模型', clip: '文本编码器', vae: '视频 VAE', audioVae: '音频 VAE' };
  const failedModels = [];
  for (const key of ['unet', 'clip', 'vae', 'audioVae']) {
    const wanted = String(cfg.videoModels?.[key] || '').trim();
    if (!wanted) continue;
    if (!inrSetWorkflowValue(workflow, bindings[key], wanted, modelLabels[key], true)) failedModels.push(modelLabels[key]);
  }
  if (failedModels.length) {
    toastr.warning('这些模型没写进工作流（映射为空）：' + failedModels.join('、') + '。到「生成后端」页点「自动识别映射」。');
  }
  const queued = await inrComfyFetch(cfg, baseUrl + '/prompt', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ prompt: workflow, client_id: 'inr_' + (crypto.randomUUID?.() || Date.now()) }) });
  if (!queued.ok) throw new Error('ComfyUI 未接受视频工作流（HTTP ' + queued.status + '）' + inrComfyHttpHint(queued.status) + '：' + (await queued.text()).slice(0, 300));
  const promptId = (await queued.json()).prompt_id;
  if (!promptId) throw new Error('ComfyUI 未返回任务 ID');
  for (let attempt = 0; attempt < 900; attempt += 1) {
    await new Promise(resolve => setTimeout(resolve, 2000));
    const response = await inrComfyFetch(cfg, baseUrl + '/history/' + encodeURIComponent(promptId));
    if (!response.ok) continue;
    const video = inrVideoOutput(await response.json(), promptId);
    if (video) {
      const query = new URLSearchParams({ filename: video.filename, subfolder: video.subfolder || '', type: video.type || 'output' });
      // 写进聊天的地址用「视频外链地址」, 手机换网络后也能播放。
      return { prompt, url: inrComfyPublic(cfg, baseUrl) + '/view?' + query.toString() };
    }
  }
  throw new Error('等待 ComfyUI 视频超时，请在 ComfyUI 队列或历史记录中查看任务');
}

async function inrDataUrl(source, file) {
  const blob = await inrImageBlob(source, file);
  return new Promise((resolve, reject) => { const reader = new FileReader(); reader.onload = () => resolve(reader.result); reader.onerror = () => reject(new Error('无法编码图片')); reader.readAsDataURL(blob); });
}

function inrJsonPath(value, path) {
  return String(path || '').split('.').filter(Boolean).reduce((result, key) => result?.[key], value);
}

async function inrGenerateHttpVideo(cfg, opts) {
  if (!/^https?:\/\//i.test(cfg.videoApiUrl)) throw new Error('请在视频设置中填写自定义 HTTP API 地址');
  const textMode = opts.mode === 'text';
  let headers; let template;
  try { headers = JSON.parse(cfg.videoApiHeaders || '{}'); } catch (_) { throw new Error('自定义 API 请求头必须是合法 JSON'); }
  template = String((textMode ? cfg.videoApiBodyText : cfg.videoApiBody) || '');
  if (!template) throw new Error('请填写自定义 API 的 JSON 请求模板');
  const prompt = await inrResolvePrompt(cfg, opts);
  const values = { '{{prompt}}': prompt, '{{duration}}': cfg.videoDuration, '{{seed}}': inrVideoSeed(cfg) };
  if (!textMode) {
    const [first, last] = await Promise.all([inrDataUrl(opts.firstSource, opts.firstFile), inrDataUrl(opts.lastSource, opts.lastFile)]);
    values['{{first_image_data_url}}'] = first;
    values['{{last_image_data_url}}'] = last;
  }
  for (const [key, value] of Object.entries(values)) template = template.split(key).join(JSON.stringify(value));
  let body;
  try { body = JSON.stringify(JSON.parse(template)); } catch (_) { throw new Error('自定义 API 请求模板不是合法 JSON。占位符不要加引号。'); }
  const response = await fetch(cfg.videoApiUrl, { method: 'POST', headers: { 'Content-Type': 'application/json', ...headers }, body });
  if (!response.ok) throw new Error('自定义视频 API 请求失败（HTTP ' + response.status + '）');
  const result = await response.json(); const url = inrJsonPath(result, cfg.videoApiResultPath);
  if (typeof url !== 'string' || !/^https?:\/\//i.test(url)) throw new Error('未能从 API 响应的“' + cfg.videoApiResultPath + '”读取到视频 URL');
  return { prompt, url };
}



