const INR_V350_BUNDLED_RULES = [{"id":"0","name":"基础规则 - 常驻","content":"<imageTag>\n你负责将正文中的关键画面转化为可供智慧姬和文生图工具使用的图像描述。每轮对话输出图片3-5张，分布在画面相对应文字内容之后。\n\n输出规则：\n1. 仅在确有画面价值时输出 <image>image### [具体画面内容] ###</image>，不为无画面价值的对话强行生图。\n2. 每个 image 块只描述一张静态画面，人物数量、相对位置、视线、服装、动作、光线和背景必须彼此一致。\n3. image 块内使用的语言、语法和提示词结构必须完全遵循当前已启用的模型提示词模式。允许使用换行将标题、人物、服装、动作、镜头和背景分开书写，但所有标点必须使用半角英文标点 , : ; . 。\n4. 格式固定为：先写【图片标题】；再按主要内容、基础设定、位置、眼神、外貌、发型、服装、姿势与动作、神情、光影、背景依次描述；若当前模式要求标签或英文自然语言，则将这些信息转换为对应形式。\n5. 描述客观可见的物理细节。人物有高低差时，写明头部仰角、俯角和视线落点。背对镜头时不描述正面五官。\n6. 服装不得省略。分别写明上装和下装的材质、长度、领口、袖长、褶皱与垂坠状态。\n7. 除非正文明确要求，否则不写文字、水印、界面、签名、镜面中的额外人物。\n8. 同一轮只能使用一个已启用的画风条目和一个已启用的模型提示词模式，不得混合不同模式。\n</imageTag>","enabled":true,"group":"","order":100},{"id":"1","name":"画风开关 - 电影写实","content":"【画风：电影写实】使用真人电影剧照风格。人物比例、皮肤纹理、衣物材质和环境透视遵循现实摄影逻辑。采用自然景深、真实镜头焦段、柔和侧光和低饱和色彩。保留毛孔、发丝、布料织纹和环境细节。避免二次元五官、塑料皮肤、夸张大眼、过度磨皮和插画笔触。","enabled":false,"group":"画风开关","order":200},{"id":"2","name":"画风开关 - 日系动漫","content":"【画风：日系动漫】使用高完成度日系动画插画风格。人物轮廓清晰，眼睛有分层高光，发丝以成束线条表现，肤色平涂后加入少量柔和阴影。服装褶皱使用明确线稿和赛璐璐明暗分区。色彩干净，画面保留动画背景的层次，不使用真人摄影质感。","enabled":false,"group":"画风开关","order":201},{"id":"3","name":"画风开关 - 国风工笔","content":"【画风：国风工笔】使用中国工笔重彩画风格。线条细而稳定，人物服装、发饰和器物具有传统纹样与矿物颜料层次。构图留有呼吸空间，背景使用亭台、屏风、山石、花枝或室内陈设烘托。设色清雅，描金只用于局部边缘和饰物，不使用现代摄影光效。","enabled":false,"group":"画风开关","order":202},{"id":"4","name":"画风开关 - 水墨写意","content":"【画风：水墨写意】使用宣纸水墨与淡彩风格。主体轮廓以浓淡变化的墨线概括，远景留白，近景使用少量淡彩。水汽、雨雾、山石、竹影和衣袖边缘可用晕染表现。人物五官与服装保留足够辨识度，但不追求照片级皮肤纹理，不使用霓虹光或高反差数码质感。","enabled":false,"group":"画风开关","order":203},{"id":"5","name":"画风开关 - 赛博霓虹","content":"【画风：赛博霓虹】使用近未来赛博都市风格。夜景以青蓝、洋红和紫色霓虹光源照亮人物边缘，潮湿地面形成倒影，背景可出现高架道路、密集招牌、金属墙面、透明屏幕和雾气。人物仍保持清晰脸部与服装结构。避免把画面变成抽象光斑，文字招牌应模糊不可读。","enabled":false,"group":"画风开关","order":204},{"id":"6","name":"画风开关 - 暗黑哥特","content":"【画风：暗黑哥特】使用哥特建筑与暗色浪漫风格。场景采用深红、黑、灰蓝和烛火金色，背景可使用拱窗、石墙、旧木家具、天鹅绒帷幔、烛台或雨夜庭院。光线集中在人物面部与手部，阴影覆盖画面边缘。保留服装纹理和环境细节，不使用血腥元素，除非正文明确要求。","enabled":false,"group":"画风开关","order":205},{"id":"7","name":"画风开关 - 时尚杂志","content":"【画风：时尚杂志】使用高端时尚编辑摄影风格。人物姿势有明确重心和肢体线条，服装材质、剪裁和配饰成为视觉重点。采用干净棚拍背景或简约都市空间，主光明确，阴影边缘干净。镜头构图强调全身比例、半身肖像或局部服装细节。画面中不得出现可读文字、品牌标志或杂志排版。","enabled":false,"group":"画风开关","order":206},{"id":"8","name":"画风开关 - 复古胶片","content":"【画风：复古胶片】使用二十世纪末彩色胶片摄影风格。色彩偏暖或轻微褪色，暗部保留颗粒感，高光柔和溢出，边缘可以有轻微暗角。场景使用旧家具、街灯、车站、书店、旅馆或家庭室内等具有年代感的物件。人物面部保持自然，不使用过强磨皮、霓虹色和现代科幻界面。","enabled":false,"group":"画风开关","order":207},{"id":"10","name":"模型提示词模式 - 标签式（Pony、光辉适用）","content":"【模型提示词模式：Pony 标签式】当前使用 Pony 或 PonyXL 系模型。image 块输出英文 Danbooru 风格标签。允许按标签区块换行，推荐一行一个区块。必须严格套用包含完整外层标签的下列范式，不输出范式名称或大括号:\n<image>image###\n[Short English Title],\n{quality tags},\n{subject count and identities},\n{person A visible appearance, hair, eyes, outfit and accessories},\n{person B visible appearance, hair, eyes, outfit and accessories},\n{left/right or front/back spatial relationship},\n{one frozen interaction, left/right hand placement and gaze targets},\n{camera framing and angle},\n{lighting}, {environment}.\n###</image>\n实际双人结构示意:\n<image>image###\n[Library Discussion],\nscore_9, score_8_up, best quality,\n1girl, 1boy, 2people, adult woman, adult man,\nwoman on left, long black hair, brown eyes, white cotton shirt, navy pleated skirt, silver earrings,\nman on right, short dark brown hair, black rectangular glasses, light gray knit sweater, dark trousers,\nsitting beside each other at a wooden desk, shoulders half a meter apart,\nwoman left hand holding an open mathematics book, man right index finger pointing at an equation, both looking at the same page,\nupper body, eye level, from front,\nwarm window light from left, soft shadow on right,\nuniversity library, wooden bookshelves, shallow depth of field.\n###</image>\n方括号内必须是 2 至 5 个英文单词的短标题。其后全部使用小写英文标签与半角逗号。质量区可测试 score_9, score_8_up, score_7_up 或 masterpiece, best quality。单人时可省略 person B 区块；双人或多人时必须先写总人数与身份，再把每个人的外观服装各自集中写完，随后才写左右或前后位置与共同动作。动作区必须写明哪一人的哪只手接触什么物体, 双方视线分别落在哪里；不要把两人的发型, 服装或手部动作混在同一无主语标签组。镜头区写 full body, upper body, cowboy shot, from front, from side, from behind, low angle 等；最后才写光线和环境。禁止中文, 完整自然语言句子, 字段标签, 权重符号, 矛盾动作标签和镜头外不可见的身体细节。","enabled":false,"group":"模型提示词模式","order":300},{"id":"11","name":"模型提示词模式 - 英文自然语言（Anima适用）","content":"【模型提示词模式：Anima 英文自然语言】当前使用 Anima 系模型。image 块固定输出 [Short English Title]. 后接 3 至 4 句英文自然语言，不写中文字段名。允许标题单独一行, 每个句子各占一行。必须严格套用包含完整外层标签的下列范式:\n<image>image###\n[Short English Title].\n{Establishing sentence: setting, subject count, A and B spatial positions, framing, camera angle, main light}.\n{Person A sentence: visible appearance, hair, eyes, accessories, visible clothing}.\n{Person B sentence: visible appearance, hair, eyes, accessories, visible clothing}.\n{Frozen interaction sentence: each person's left/right hand action, body orientation, gaze target, distance or contact, background and atmosphere}.###</image>\n实际双人结构示意:\n<image>image###\n[Library Discussion].\nIn a university library, an adult woman sits on the left and an adult man sits on the right at a wooden desk, shown in an eye-level upper-body front view with warm window light entering from the left.\nA has long black hair, brown eyes, silver earrings, a white cotton shirt with rolled sleeves, and a navy pleated skirt visible below the desk edge.\nB has short dark brown hair, black rectangular glasses, a light gray knit sweater, and dark trousers visible at the desk edge.\nA holds an open mathematics book with her left hand while B points at an equation with his right index finger, their shoulders remain half a meter apart, and both direct their eyes toward the same page as wooden bookshelves fade into the shallow background.###</image>\n允许在标题后加入少量质量标签，例如 masterpiece, best quality，但不要使用 Pony 的完整 score 标签链。第 1 句只建立镜头与空间；单人图第 2 句写人物外观服装, 第 3 句写定格动作与环境；双人图则第 2 句专写 A, 第 3 句专写 B, 第 4 句专写两人的互动。半身, 背影或局部镜头必须删除画外信息；多人图始终使用 A and B 或角色名作为清晰主语，禁止含混代词, 标签堆砌, 权重符号, 中文和解释文字。","enabled":false,"group":"模型提示词模式","order":301},{"id":"12","name":"模型提示词模式 - 中文自然语言(ZIT、Krea2、Qwen适用)","content":"【模型提示词模式：ZIT 与 Krea2 中文自然语言】当前使用 ZIT, Z-Image Turbo 或 Krea2 系模型。image 块必须输出中文分区白描，不使用 Danbooru 标签列表, score 标签链或英文质量词。允许标题单独一行, 每个中文分区各占一行。必须严格套用包含完整外层标签的下列范式:\n<image>image###\n【图片标题】\n画面事件: {人物数量, 身份年龄段, 性别, 姓名, 行为动作, 主语以明确动词作用于对象}.\n人物与空间: {人物、物品相互距离, 画面左右前后位置}.\n构图视角: {景别, 镜头高度, 躯干朝向, 遮挡关系}.\n外观发型: {分别写出 A 与 B 仅可见的脸部轮廓, 肤质, 发长发色, 发丝状态, 配饰}.\n服装材质: {分别写出 A 与 B 可见上装和下装的款式, 面料, 颜色, 领口, 袖长, 褶皱和垂坠}.\n肢体与视线: {分别写出 A 与 B 的左右手, 关节方向, 接触对象, 眼球焦点, 头部仰俯角}.\n神情: {分别写出 A 与 B 的眉眼嘴部物理状态}.\n光影: {光源位置, 色温, 阴影边缘, 高光位置}.\n背景: {场景物体, 景深层次, 雾, 尘埃或雨滴}.###</image>\n实际双人结构示意:\n<image>image###\n【图书馆讨论】\n画面事件: 一名成年女性柳如烟与一名成年男性叶凡并排坐在木桌前查看同一本数学教材.\n人物与空间: 画面中有两名成年中国人物, 柳如烟 位于画面左侧, 叶凡 位于画面右侧, 两人的肩部相距半米, 木桌位于两人前方, 后方书架与两人相距两米.\n构图视角: 两人上半身中景, 镜头与人物平视, 两人的躯干均朝向镜头前方并略微转向桌面, 桌面遮住两人的大腿以下.\n外观发型: 柳如烟 留有垂至锁骨的长直黑发, 棕色眼睛朝向书页, 左耳佩戴银色耳钉, 叶凡 留有短深棕发, 戴黑色矩形眼镜, 深棕色眼睛朝向书页.\n服装材质: 柳如烟 穿白色棉质衬衫, 袖口卷至小臂中段, 深蓝色百褶裙仅露出腰部边缘, 叶凡 穿浅灰色针织圆领毛衣, 深色长裤仅露出腰部边缘.\n肢体与视线: 柳如烟 的左手压住书页左侧, 右手放在桌面边缘, 叶凡 的右手食指指向书页中的一道公式, 左手放在书脊旁, 两人的眼球焦点均落在同一行公式上.\n神情: 柳如烟 的眉间轻微收拢, 嘴唇闭合, 叶凡 的眉毛向内靠拢, 下唇与上唇轻触.\n光影: 左侧窗光照亮两人的左侧面颊和书页边缘, 两人右侧衣物形成柔和阴影, 眼镜边缘有细小高光.\n背景: 深色木书架位于浅景深中, 书脊形成竖向色块, 空气里有少量尘埃.###</image>\n必须使用具体可见的信息替代空泛修饰。单人时删除 B 的信息；人物背对, 半身或局部镜头时删除画外特征；多人互动逐一重复姓名或 A/B 并说明谁在做什么。所有标点只使用半角英文标点 , : ; . 。","enabled":true,"group":"模型提示词模式","order":302},{"id":"13","name":"画风开关 - 东方仙侠","content":"【画风：东方仙侠】使用东方仙侠幻想美术风格。人物服装采用飘逸层叠的广袖长袍, 云纹或暗纹布料, 玉佩, 发冠, 发簪, 剑穗等细节；场景可使用云海, 悬崖, 天游石阶, 古松, 飞瀑, 仙山, 剑阁, 洞府或古典殿宇。光线呈现清晨薄雾, 月光, 暮色云霞或灵气微光, 但人物轮廓和衣物结构保持清晰。法器, 飞剑, 符箓和灵气只作为服务画面的具体物件, 避免堆叠发光特效, 游戏界面或可读文字。","enabled":false,"group":"画风开关","order":208},{"id":"16","name":"生图输出完整性自检 - 常驻","content":"【生图输出完整性自检】这是回复提交前必须在内部完成的最终检查，不输出自检过程, 思考标签或解释文字。最高优先级是确保图片提示词没有遗漏且能被插件解析。\n第一步, 判断本轮是否为有连续剧情的正文；是则先在内部确定 3 至 5 个插图挂载段落，并确保最终正文实际包含同等数量的图片块。短对话, 无明确画面或用户要求不出图时才允许为 0 张。\n第二步, 在输出正文前逐项核对每个挂载段落后是否已经存在完整的 <image>image###提示词###</image>；禁止只写 image###, 漏掉 <image> 或 </image>, 漏掉 ###, 输出空提示词, 把图片块塞进思考区, 状态栏, 总结区, 油猴末尾追加区，或在文末连续堆放。\n第三步, 确认每一个图片块都有标题和完整画面提示词。图片块内部允许换行以分隔标题, 标签区块或描述分区, 但不能有解释文字或代码块；并完全符合当前启用的模型提示词模式。Pony 必须是英文标签式, Anima 必须是英文三句式, ZIT 与 Krea2 必须是中文分区白描式。\n第四步, 若图片数量不足, 格式不完整或某张图未紧跟对应剧情段落，必须先在内部补全或修正，再输出回复；不得因为正文已经写完而省略图片。最后才检查单张图的定格逻辑, 人物位置, 手部动作, 视线, 服装和景别是否一致。","enabled":true,"group":"","order":122},{"id":"20","name":"MVU通用生图桥接 - 状态读取与隔离写入","content":"<mvu_image_bridge>\n以下是当前聊天的 MVU 状态. 该内容仅供内部读取, 不要在正文解释或复述.\n<stat_data>\n{{get_message_variable::stat_data}}\n</stat_data>\n\n执行规则:\n1. 从 stat_data 中提取与当前正文相关的姓名, 外貌, 发型, 发色, 瞳色, 服装, 姿势, 地点和时间, 用于保持正文与 image 块一致. 正文刚明确出现的事实优先级最高, 其次是 __image_bridge, 最后才是其他已有 MVU 字段.\n2. 无论 stat_data 是否已有内容, 都不得初始化, 重命名, 删除或覆盖原角色卡已有变量. 唯一允许写入的路径是 stat_data.__image_bridge. 该命名空间只服务通用生图一致性, 不参与原卡状态栏, 数值或任务逻辑.\n3. 视觉状态字段固定为 __image_bridge.角色.姓名, __image_bridge.角色.外貌.发型, __image_bridge.角色.外貌.发色, __image_bridge.角色.外貌.瞳色, __image_bridge.角色.服装.上装, __image_bridge.角色.服装.下装, __image_bridge.角色.当前姿势, __image_bridge.场景.地点, __image_bridge.场景.时间.\n4. 当正文首次明确给出可见形象或场景事实, 或之后明确发生换装, 发型或发色变化, 饰品变化, 姿势变化, 地点移动或时间变化时, 在完成正文和 image 块后输出一段 UpdateVariable. 只更新本轮首次确认或确实变化的字段. old_value 填写已知旧值或空字符串, new_value 必须是正文已明确出现的事实. 不要编造外貌或服装.\n<UpdateVariable>\n_.set('__image_bridge.角色.服装.上装', '白色衬衫', '黑色西装外套');//正文明确换装\n_.set('__image_bridge.角色.服装.下装', '牛仔裤', '深灰西裤');//正文明确换装\n</UpdateVariable>\n5. UpdateVariable 是供 MVU 解析的隐藏控制段. 它必须位于整条回复末尾, 每轮最多一段, 不得写进 image 块. 若没有明确事实, 不输出该段.\n</mvu_image_bridge>","enabled":true,"group":"","order":90},{"id":"21","name":"MVU通用生图桥接 - 输出自检","content":"<mvu_image_bridge_check>\n回复提交前在内部检查. 仅当正文明确发生可见状态变化时才输出 UpdateVariable. 确认所有 UpdateVariable 路径均以 __image_bridge. 开头, 且没有修改任何原角色卡字段. 不要输出本检查标签或解释.\n</mvu_image_bridge_check>","enabled":true,"group":"","order":91},{"id":"22","name":"[InitVar] MVU通用生图桥接 - 隔离视觉状态初始化（勿开）","content":"<initvar>\n{\n  \"__image_bridge\": {\n    \"角色\": {\n      \"姓名\": [\"\", \"角色姓名, 在正文首次明确出现时更新\"],\n      \"外貌\": {\n        \"发型\": [\"\", \"发型, 在正文首次明确或变化时更新\"],\n        \"发色\": [\"\", \"发色, 在正文首次明确或变化时更新\"],\n        \"瞳色\": [\"\", \"瞳色, 在正文首次明确或变化时更新\"]\n      },\n      \"服装\": {\n        \"上装\": [\"\", \"上装, 在正文首次明确或换装时更新\"],\n        \"下装\": [\"\", \"下装, 在正文首次明确或换装时更新\"]\n      },\n      \"当前姿势\": [\"\", \"当前稳定姿势, 仅在正文明确变化时更新\"]\n    },\n    \"场景\": {\n      \"地点\": [\"\", \"当前地点, 在正文首次明确或移动时更新\"],\n      \"时间\": [\"\", \"当前时间, 在正文首次明确或推进时更新\"]\n    }\n  }\n}\n</initvar>","enabled":false,"group":"","order":80},{"id":"23","name":"图文阅读器 MVU 多角色视觉档案 - 常驻","content":"<inr_multi_character_bridge>\n当当前回复来自图文小说阅读器时，除原有 __image_bridge.角色 外，还读取 __image_bridge.角色档案。角色档案以人物姓名为键，保存多个重要人物的发型、发色、瞳色、上装、下装、当前姿势与关系。\n\n生成每一个 image 块前，先识别该画面实际出现的人物；只读取对应人物的角色档案，不得把甲的外貌、服装或姿势套给乙。正文明确出现换装、受伤、发型变化、地点移动或关系变化时，只更新对应人物的档案字段。原文未明确的字段保持为空，不得补造。\n\n图文阅读器会由脚本保存状态，无需在正文额外输出 UpdateVariable。image 块内应优先使用角色档案中与当前画面匹配的事实，并以当前正文新事实为最高优先级。\n</inr_multi_character_bridge>","enabled":true,"group":"","order":92},{"id":"24","name":"图文阅读器 MVU 多角色自检 - 常驻","content":"<inr_multi_character_check>\n内部检查：每张图片中的所有人物都必须分别对应其姓名档案；同名人物前后外貌与服装保持一致，除非正文明确变化。不可把未出现的人物塞进画面。不要输出本检查标签。\n</inr_multi_character_check>","enabled":true,"group":"","order":93}];

let inrV350Migration = null;
let inrV350Injection = null;
let inrV350Observer = null;
let inrV350MountTimer = null;
let inrV350MvuRetryTimer = null;
let inrV350Started = false;
let inrV350LogsCache = null;

function inrV350Clone(value) { return value == null ? value : JSON.parse(JSON.stringify(value)); }
function inrV350Text(value, fallback = '') { return value == null ? fallback : String(value); }
function inrV350Clamp(value, min, max, fallback) {
  const number = Number(value);
  return Number.isFinite(number) ? Math.max(min, Math.min(max, number)) : fallback;
}
function inrV350Id(prefix) {
  return prefix + '_' + (crypto.randomUUID?.() || (Date.now().toString(36) + Math.random().toString(36).slice(2)));
}
function inrV350Escape(value) { return inrEscape(value); }
function inrV350SafeJson(text, fallback) {
  try { const value = JSON.parse(String(text || '')); return value && typeof value === 'object' ? value : fallback; }
  catch (_) { return fallback; }
}
function inrV350SetPath(target, path, value) {
  const parts = String(path || '').split('.').filter(Boolean);
  if (!parts.length) return;
  let cursor = target;
  for (const part of parts.slice(0, -1)) cursor = cursor[part] ||= {};
  cursor[parts.at(-1)] = value;
}
function inrV350GetPath(target, path, fallback = '') {
  return String(path || '').split('.').filter(Boolean).reduce((value, key) => value?.[key], target) ?? fallback;
}
function inrV350NormalizeMode(value) { return value === 'card' ? 'card' : 'reader'; }
function inrV350NormalizeReaderMode(value) { return value === 'adapted' ? 'adapted' : 'original'; }
function inrV350RuleIds(entries, mode) {
  const defaultIds = entries.filter(entry => entry.enabled).map(entry => entry.id);
  if (mode !== 'card') return defaultIds;
  // Reader-only bridge prose should not be injected into ordinary roleplay.
  return defaultIds.filter(id => {
    const entry = entries.find(item => item.id === id);
    return entry && !/图文阅读器|小说阅读器/.test(entry.name);
  });
}

function inrV350DefaultGlobal(legacy = {}) {
  return {
    version: 3,
    activeMode: 'reader',
    readerMode: inrV350NormalizeReaderMode(legacy.mode),
    size: inrV350Clamp(legacy.size, 500, 20000, 2500),
    images: inrV350Clamp(legacy.images, 1, 8, 2),
    style: inrV350Text(legacy.style),
    adaptation: inrV350Text(legacy.adaptation),
    originalSystemPrompt: inrV350Text(legacy.originalSystemPrompt, INR_V353_ORIGINAL_SYSTEM_PROMPT),
    originalRules: inrV350Text(legacy.originalRules, INR_V353_ORIGINAL_RULES),
    originalSchema: inrV350Text(legacy.originalSchema, INR_V353_ORIGINAL_SCHEMA),
    originalRequireQuote: legacy.originalRequireQuote !== false,
    originalAutoRetry: legacy.originalAutoRetry !== false,
    originalAllowInference: legacy.originalAllowInference === true,
    originalMaxTokens: inrV350Clamp(legacy.originalMaxTokens, 512, 8192, 4096),
    originalTemperature: inrV350Clamp(legacy.originalTemperature, 0, 2, 0.2),
    originalTopP: inrV350Clamp(legacy.originalTopP, 0.05, 1, 0.9),
    originalSkipThinking: legacy.originalSkipThinking !== false,
    videoMode: legacy.videoMode === 'text' ? 'text' : 'frames',
    activeFrameSchemeId: '',
    activeTextSchemeId: '',
  };
}

function inrV350DefaultChat(legacy = {}) {
  return {
    version: 2,
    bookId: legacy.bookId || null,
    progress: legacy.progress && typeof legacy.progress === 'object'
      ? inrV350Clone(legacy.progress)
      : { original: { chapter: 0, page: -1 }, adapted: { chapter: 0, page: -1 } },
    visualReferenceMemory: {},
    lastPage: null,
  };
}

function inrV350NormalizeGlobal(value, legacy = {}) {
  return {
    ...inrV350DefaultGlobal(legacy),
    ...(value && typeof value === 'object' ? value : {}),
    version: 3,
    activeMode: inrV350NormalizeMode(value?.activeMode),
    readerMode: inrV350NormalizeReaderMode(value?.readerMode ?? legacy.mode),
    size: inrV350Clamp(value?.size ?? legacy.size, 500, 20000, 2500),
