    originalRules: inrV350Text(value?.originalRules ?? legacy.originalRules, INR_V353_ORIGINAL_RULES) || INR_V353_ORIGINAL_RULES,
    originalSchema: inrV350Text(value?.originalSchema ?? legacy.originalSchema, INR_V353_ORIGINAL_SCHEMA) || INR_V353_ORIGINAL_SCHEMA,
    originalRequireQuote: (value?.originalRequireQuote ?? legacy.originalRequireQuote) !== false,
    originalAutoRetry: (value?.originalAutoRetry ?? legacy.originalAutoRetry) !== false,
    originalAllowInference: (value?.originalAllowInference ?? legacy.originalAllowInference) === true,
    originalMaxTokens: inrV350Clamp(value?.originalMaxTokens ?? legacy.originalMaxTokens, 512, 8192, 4096),
    originalTemperature: inrV350Clamp(value?.originalTemperature ?? legacy.originalTemperature, 0, 2, 0.2),
    originalTopP: inrV350Clamp(value?.originalTopP ?? legacy.originalTopP, 0.05, 1, 0.9),
    originalSkipThinking: (value?.originalSkipThinking ?? legacy.originalSkipThinking) !== false,
    videoMode: value?.videoMode === 'text' ? 'text' : 'frames',
    activeFrameSchemeId: inrV350Text(value?.activeFrameSchemeId),
    activeTextSchemeId: inrV350Text(value?.activeTextSchemeId),
  };
}

function inrV350NormalizeChat(value, legacy = {}) {
  const source = value && typeof value === 'object' ? value : {};
  const legacyProgress = legacy.progress && typeof legacy.progress === 'object' ? legacy.progress : {};
  const progress = source.progress && typeof source.progress === 'object' ? source.progress : legacyProgress;
  const normalizePos = pos => {
    const chapter = Number(pos?.chapter);
    const page = Number(pos?.page);
    return {
      chapter: Number.isFinite(chapter) ? Math.max(0, chapter) : 0,
      page: Number.isFinite(page) ? Math.max(-1, page) : -1,
    };
  };
  return {
    version: 2,
    bookId: source.bookId || legacy.bookId || null,
    progress: { original: normalizePos(progress.original), adapted: normalizePos(progress.adapted) },
    visualReferenceMemory: source.visualReferenceMemory && typeof source.visualReferenceMemory === 'object'
      ? inrV350Clone(source.visualReferenceMemory)
      : {},
    lastPage: source.lastPage && typeof source.lastPage === 'object' ? inrV350Clone(source.lastPage) : null,
  };
}

function inrV350NormalizeCharacter(value) {
  const source = value && typeof value === 'object' ? value : {};
  return {
    version: 2,
    useOverride: source.useOverride === true,
    settings: source.settings && typeof source.settings === 'object' ? inrV350Clone(source.settings) : {},
    cardRuleIds: Array.isArray(source.cardRuleIds) ? source.cardRuleIds.map(String) : null,
  };
}

function inrV350DefaultBindings(mode) {
  const common = {
    prompt: '138.value', seed: '129.noise_seed', duration: '132.value', megapixels: '',
    width: '136.width', height: '136.height', unet: '127.unet_name', clip: '128.clip_name', vae: '119.vae_name', audioVae: '120.vae_name',
  };
  return mode === 'frames' ? { first: '137.image', last: '139.image', ...common } : common;
}

// The live v3.4 defaults used two convenience custom nodes. New installations
// should not be blocked by them, so the v3.5 default graph is portable ComfyUI
// core: direct H3 model wiring and a 864x480 native size. Existing user-imported
// workflows are preserved exactly during migration.
function inrV350PortableH3Workflow(workflow) {
  const portable = inrV350Clone(workflow);
  for (const node of Object.values(portable)) {
    for (const [key, value] of Object.entries(node?.inputs || {})) {
      if (Array.isArray(value) && String(value[0]) === '152') node.inputs[key] = ['127', value[1]];
      if (Array.isArray(value) && String(value[0]) === '115') {
        if (value[1] === 0) node.inputs[key] = 864;
        if (value[1] === 1) node.inputs[key] = 480;
      }
    }
  }
  delete portable['152'];
  delete portable['115'];
  return portable;
}

function inrV350DefaultMode(mode, legacy = {}) {
  const prefix = mode === 'text' ? 'videoText' : 'video';
  const fallbackWorkflow = mode === 'text' ? INR_TEXT_VIDEO_WORKFLOW : INR_VIDEO_WORKFLOW;
  const legacyWorkflow = legacy[`${prefix}Workflow`];
  const legacyBindings = legacyWorkflow && typeof legacyWorkflow === 'object'
    ? (mode === 'text' ? legacy.videoTextBindings : legacy.videoBindings)
    : null;
  return {
    workflow: inrV350Clone(legacyWorkflow || inrV350PortableH3Workflow(fallbackWorkflow)),
    bindings: { ...inrV350DefaultBindings(mode), ...(legacyBindings && typeof legacyBindings === 'object' ? legacyBindings : {}) },
    duration: inrV350Clamp(mode === 'text' ? (legacy.videoDurationText || legacy.videoDuration) : legacy.videoDuration, 3, 15, 5),
    seed: Number.isSafeInteger(Number(legacy.videoSeed)) ? Number(legacy.videoSeed) : -1,
    resolution: inrV350Text(mode === 'text' ? (legacy.videoResolutionText || legacy.videoResolution) : legacy.videoResolution),
    models: {
      unet: inrV350Text(legacy.videoModels?.unet), clip: inrV350Text(legacy.videoModels?.clip),
      vae: inrV350Text(legacy.videoModels?.vae), audioVae: inrV350Text(legacy.videoModels?.audioVae),
    },
    promptProfileId: '',
    llmProfileId: '',
  };
}

function inrV350NormalizeModeSettings(value, mode, legacy = {}) {
  const source = value && typeof value === 'object' ? value : {};
  const defaults = inrV350DefaultMode(mode, legacy);
  return {
    ...defaults,
    ...source,
    workflow: source.workflow && typeof source.workflow === 'object' ? inrV350Clone(source.workflow) : defaults.workflow,
    bindings: { ...defaults.bindings, ...(source.bindings && typeof source.bindings === 'object' ? source.bindings : {}) },
    duration: inrV350Clamp(source.duration ?? defaults.duration, 3, 15, defaults.duration),
    seed: Number.isSafeInteger(Number(source.seed)) ? Number(source.seed) : defaults.seed,
    resolution: inrV350Text(source.resolution ?? defaults.resolution),
    models: { ...defaults.models, ...(source.models && typeof source.models === 'object' ? source.models : {}) },
    promptProfileId: inrV350Text(source.promptProfileId),
    llmProfileId: inrV350Text(source.llmProfileId),
  };
}

