function inrV350NormalizeScheme(value, index, legacy = {}) {
  const defaults = inrV350DefaultScheme(legacy);
  const source = value && typeof value === 'object' ? value : {};
  return {
    ...defaults,
    ...source,
    id: inrV350Text(source.id || (index ? inrV350Id('scheme') : defaults.id)),
    name: inrV350Text(source.name || `视频方案 ${index + 1}`),
    appliesTo: ['frames', 'text', 'both'].includes(source.appliesTo) ? source.appliesTo : 'both',
    modelFamily: inrV350Text(source.modelFamily || '自定义模型'),
    backend: source.backend === 'http' ? 'http' : 'comfy',
    comfy: { ...defaults.comfy, ...(source.comfy && typeof source.comfy === 'object' ? source.comfy : {}) },
    http: { ...defaults.http, ...(source.http && typeof source.http === 'object' ? source.http : {}) },
    frames: inrV350NormalizeModeSettings(source.frames, 'frames', legacy),
    text: inrV350NormalizeModeSettings(source.text, 'text', legacy),
    createdAt: Number(source.createdAt) || Date.now(),
    updatedAt: Number(source.updatedAt) || Date.now(),
  };
}

function inrV350NormalizeSchemes(value, legacy = {}) {
  const source = value && typeof value === 'object' ? value : {};
  const schemes = Array.isArray(source.schemes) && source.schemes.length
    ? source.schemes.map((item, index) => inrV350NormalizeScheme(item, index, legacy))
    : [inrV350DefaultScheme(legacy)];
  return { version: 1, schemes };
}

function inrV350DefaultLlmProfiles(legacy = {}) {
  const standalone = {
    id: 'legacy-openai', name: '迁移的独立 OpenAI 兼容 API', provider: 'openai',
    url: inrV350Text(legacy.url), key: inrV350Text(legacy.key), model: inrV350Text(legacy.model),
    temperature: inrV350Clamp(legacy.temperature, 0, 2, 0.8), maxTokens: inrV350Clamp(legacy.maxTokens, 256, 32000, 2000),
    headers: inrV350Text(legacy.headers, '{}'), retries: inrV350Clamp(legacy.retries, 0, 5, 1),
    timeout: inrV350Clamp(legacy.timeout, 10, 600, 120), fallback: legacy.fallback !== false,
  };
  return { version: 1, profiles: [{ id: 'tavern-current', name: '酒馆当前 API', provider: 'tavern' }, standalone] };
}

function inrV350NormalizeLlmProfiles(value, legacy = {}) {
  const source = value && typeof value === 'object' ? value : {};
  const fallback = inrV350DefaultLlmProfiles(legacy).profiles;
  const raw = Array.isArray(source.profiles) && source.profiles.length ? source.profiles : fallback;
  const profiles = raw.map((item, index) => ({
    id: inrV350Text(item?.id || (index ? inrV350Id('llm') : 'tavern-current')),
    name: inrV350Text(item?.name || `提示词 API ${index + 1}`),
    provider: item?.provider === 'openai' ? 'openai' : 'tavern',
    url: inrV350Text(item?.url), key: inrV350Text(item?.key), model: inrV350Text(item?.model),
    temperature: inrV350Clamp(item?.temperature, 0, 2, 0.8), maxTokens: inrV350Clamp(item?.maxTokens, 256, 32000, 2000),
    headers: inrV350Text(item?.headers, '{}'), retries: inrV350Clamp(item?.retries, 0, 5, 1),
    timeout: inrV350Clamp(item?.timeout, 10, 600, 120), fallback: item?.fallback !== false,
  }));
  if (!profiles.some(profile => profile.id === 'tavern-current')) profiles.unshift({ id: 'tavern-current', name: '酒馆当前 API', provider: 'tavern' });
  return { version: 1, profiles };
}

function inrV350NormalizeRules(value) {
  const source = value && typeof value === 'object' ? value : {};
  const rawEntries = Array.isArray(source.entries) && source.entries.length ? source.entries : INR_V350_BUNDLED_RULES;
  const entries = rawEntries.map((entry, index) => ({
    id: inrV350Text(entry?.id || entry?.uid || `rule-${index}`),
    name: inrV350Text(entry?.name || entry?.comment || `规则 ${index + 1}`),
    content: inrV350Text(entry?.content), enabled: entry?.enabled !== false && entry?.disable !== true,
    group: inrV350Text(entry?.group), order: Number(entry?.order) || index,
  })).filter(entry => entry.content.trim());
  const known = new Set(entries.map(entry => entry.id));
  const normalizeIds = (ids, mode) => {
    const candidate = Array.isArray(ids) ? ids.map(String).filter(id => known.has(id)) : inrV350RuleIds(entries, mode);
    return [...new Set(candidate)];
  };
  return { version: 1, entries, readerEnabledIds: normalizeIds(source.readerEnabledIds, 'reader'), cardEnabledIds: normalizeIds(source.cardEnabledIds, 'card') };
}

async function inrV350ScriptValue(key, fallback = {}) { return getVariables({ type: 'script' })[key] || fallback; }
async function inrV350WriteScript(key, value) { return insertOrAssignVariables({ [key]: value }, { type: 'script' }); }
async function inrV350ChatValue(key, fallback = {}) { return getVariables({ type: 'chat' })[key] || fallback; }
async function inrV350WriteChat(key, value) { return insertOrAssignVariables({ [key]: value }, { type: 'chat' }); }
async function inrV350CharacterValue(key, fallback = {}) {
  try { return getVariables({ type: 'character' })[key] || fallback; }
  catch (_) { return fallback; }
}
async function inrV350WriteCharacter(key, value) {
  try { return await insertOrAssignVariables({ [key]: value }, { type: 'character' }); }
  catch (_) { throw new Error('当前没有打开角色卡，无法保存角色独立设置'); }
}

async function inrV350EnsureMigrated() {
  if (inrV350Migration) return inrV350Migration;
  inrV350Migration = (async () => {
    const script = getVariables({ type: 'script' }) || {};
    const chat = getVariables({ type: 'chat' }) || {};
    const legacy = chat[INR_CHAT] && typeof chat[INR_CHAT] === 'object' ? chat[INR_CHAT] : {};
    const legacyApi = script[INR_API] && typeof script[INR_API] === 'object' ? script[INR_API] : {};
    const global = inrV350NormalizeGlobal(script[INR_V350_GLOBAL], legacy);
    const state = inrV350NormalizeChat(chat[INR_V350_CHAT], legacy);
    const schemes = inrV350NormalizeSchemes(script[INR_V350_SCHEMES], legacy);
    const llm = inrV350NormalizeLlmProfiles(script[INR_V350_LLM], legacyApi);
    const rules = inrV350NormalizeRules(script[INR_V350_RULES]);
    const defaultScheme = schemes.schemes[0]?.id || '';
    if (!global.activeFrameSchemeId || !schemes.schemes.some(item => item.id === global.activeFrameSchemeId)) global.activeFrameSchemeId = defaultScheme;
    if (!global.activeTextSchemeId || !schemes.schemes.some(item => item.id === global.activeTextSchemeId)) global.activeTextSchemeId = defaultScheme;
    for (const scheme of schemes.schemes) {
      scheme.frames.promptProfileId ||= 'default'; scheme.text.promptProfileId ||= 'default';
      scheme.frames.llmProfileId ||= legacyApi.enabled ? 'legacy-openai' : 'tavern-current';
      scheme.text.llmProfileId ||= legacyApi.enabled ? 'legacy-openai' : 'tavern-current';
    }
    await Promise.all([
      inrV350WriteScript(INR_V350_GLOBAL, global),
      inrV350WriteChat(INR_V350_CHAT, state),
      inrV350WriteScript(INR_V350_SCHEMES, schemes),
      inrV350WriteScript(INR_V350_LLM, llm),
      inrV350WriteScript(INR_V350_RULES, rules),
    ]);
    return { global, state, schemes, llm, rules };
  })().catch(error => { inrV350Migration = null; throw error; });
  return inrV350Migration;
}

async function inrV350Global() {
  const values = await inrV350EnsureMigrated();
  return inrV350NormalizeGlobal(await inrV350ScriptValue(INR_V350_GLOBAL), values.global);
}
async function inrV350SaveGlobal(value) { return inrV350WriteScript(INR_V350_GLOBAL, inrV350NormalizeGlobal(value)); }
async function inrV350ChatState() {
  await inrV350EnsureMigrated();
  return inrV350NormalizeChat(await inrV350ChatValue(INR_V350_CHAT));
}
async function inrV350SaveChatState(value) { return inrV350WriteChat(INR_V350_CHAT, inrV350NormalizeChat(value)); }
async function inrV350Character() {
  await inrV350EnsureMigrated();
  return inrV350NormalizeCharacter(await inrV350CharacterValue(INR_V350_CHARACTER));
}
async function inrV350SaveCharacter(value) { return inrV350WriteCharacter(INR_V350_CHARACTER, inrV350NormalizeCharacter(value)); }
async function inrV350Rules() {
  await inrV350EnsureMigrated();
  return inrV350NormalizeRules(await inrV350ScriptValue(INR_V350_RULES));
}
async function inrV350SaveRules(value) { return inrV350WriteScript(INR_V350_RULES, inrV350NormalizeRules(value)); }
async function inrV350Schemes() {
  await inrV350EnsureMigrated();
  return inrV350NormalizeSchemes(await inrV350ScriptValue(INR_V350_SCHEMES));
}
async function inrV350SaveSchemes(value) { return inrV350WriteScript(INR_V350_SCHEMES, inrV350NormalizeSchemes(value)); }
async function inrV350LlmProfiles() {
  await inrV350EnsureMigrated();
  return inrV350NormalizeLlmProfiles(await inrV350ScriptValue(INR_V350_LLM));
}
async function inrV350SaveLlmProfiles(value) { return inrV350WriteScript(INR_V350_LLM, inrV350NormalizeLlmProfiles(value)); }

async function inrV350EffectiveSettings() {
  const global = await inrV350Global();
  const character = await inrV350Character();
  if (!character.useOverride) return { ...global, scope: 'global', character };
  return {
    ...global,
    ...(character.settings || {}),
    activeMode: inrV350NormalizeMode(character.settings?.activeMode || global.activeMode),
    readerMode: inrV350NormalizeReaderMode(character.settings?.readerMode || global.readerMode),
    scope: 'character',
    character,
  };
}

async function inrV350RuleText(mode, explicitIds) {
  const rules = await inrV350Rules();
  const ids = new Set(explicitIds || (mode === 'card' ? rules.cardEnabledIds : rules.readerEnabledIds));
  const state = (await inrReaderStateData())?.stat_data || {};
  const content = rules.entries
    .filter(entry => ids.has(entry.id) && entry.enabled && entry.content.trim())
    .sort((left, right) => left.order - right.order)
    .map(entry => '## ' + entry.name + '\n' + entry.content.replace('{{get_message_variable::stat_data}}', JSON.stringify(state)))
    .join('\n\n');
  return content.slice(0, 60000);
}

