async function inrV350FindScheme(mode, global) {
  const schemes = await inrV350Schemes();
  const id = mode === 'text' ? global.activeTextSchemeId : global.activeFrameSchemeId;
  const compatible = schemes.schemes.filter(item => item.appliesTo === 'both' || item.appliesTo === mode);
  const scheme = compatible.find(item => item.id === id) || compatible[0];
  if (!scheme) throw new Error('尚未创建视频方案');
  return scheme;
}

// Retained video backend helpers call inrConfig(). The returned object has their
// established field shape, but all persistent ownership is v3.5 scoped state.
async function inrConfig() {
  const [effective, state] = await Promise.all([inrV350EffectiveSettings(), inrV350ChatState()]);
  const scheme = await inrV350FindScheme(effective.videoMode, effective);
  return {
    ...effective,
    ...state,
    bookId: state.bookId,
    mode: effective.readerMode,
    progress: state.progress,
    ...inrV350SchemeLegacy(scheme, effective.videoMode),
