}

async function inrSaveConfig(value) {
  const global = await inrV350Global();
  const state = await inrV350ChatState();
  const nextGlobal = {
    ...global,
    readerMode: inrV350NormalizeReaderMode(value?.mode ?? value?.readerMode ?? global.readerMode),
    size: inrV350Clamp(value?.size, 500, 20000, global.size),
    images: inrV350Clamp(value?.images, 1, 8, global.images),
    style: inrV350Text(value?.style, global.style),
    adaptation: inrV350Text(value?.adaptation, global.adaptation),
    videoMode: value?.videoMode === 'text' ? 'text' : global.videoMode,
  };
  const nextState = {
    ...state,
    bookId: value?.bookId ?? state.bookId,
    progress: value?.progress && typeof value.progress === 'object' ? value.progress : state.progress,
  };
  await Promise.all([inrV350SaveGlobal(nextGlobal), inrV350SaveChatState(nextState)]);
}

function inrV350RedactText(value) {
  return String(value ?? '')
    .replace(/((?:authorization|x-api-key|api[_-]?key|cookie|token|secret|password)\s*["']?\s*[:=]\s*["']?)(?:bearer\s+)?[^\s,;"'}]+/gi, '$1[redacted]')
    .replace(/([?&](?:key|access[_-]?key|api[_-]?key|token|authorization|cookie|secret|password)=)[^&#\s]+/gi, '$1[redacted]')
    .replace(/\bBearer\s+[A-Za-z0-9._~+\/-]+=*/gi, 'Bearer [redacted]')
    .replace(/\bsk-[A-Za-z0-9_-]{8,}\b/g, '[redacted]');
}

function inrV350SafeError(error) {
  return inrV350RedactText(error?.message || String(error || 'Unknown error'));
}

function inrV350Redact(value, depth = 0, key = '') {
  if (depth > 8) return '[truncated]';
  if (/authorization|cookie|token|secret|password|api[_-]?key|^key$/i.test(key)) return value ? '[redacted]' : '';
  if (/headers?$/i.test(key) && typeof value === 'string') {
    const parsed = inrV350SafeJson(value, null);
    return parsed && typeof parsed === 'object'
      ? JSON.stringify(inrV350Redact(parsed, depth + 1, 'headers'))
      : inrV350RedactText(value);
  }
  if (Array.isArray(value)) return value.map(item => inrV350Redact(item, depth + 1));
  if (value && typeof value === 'object') return Object.fromEntries(Object.entries(value).map(([name, item]) => [name, inrV350Redact(item, depth + 1, name)]));
  return typeof value === 'string' ? inrV350RedactText(value) : value;
}

async function inrV350Log(level, action, detail = {}) {
  if (!inrV350LogsCache) inrV350LogsCache = Array.isArray(await inrV350ScriptValue(INR_V350_LOGS, [])) ? await inrV350ScriptValue(INR_V350_LOGS, []) : [];
  inrV350LogsCache.push({ at: new Date().toISOString(), level, action, detail: inrV350Redact(detail) });
  inrV350LogsCache = inrV350LogsCache.slice(-80);
  await inrV350WriteScript(INR_V350_LOGS, inrV350LogsCache);
}

function inrV350CanInject() {
  return typeof injectPrompts === 'function' && typeof uninjectPrompts === 'function';
}

async function inrV350RemoveCardInjection() {
  try { inrV350Injection?.uninject?.(); } catch (_) {}
  try { if (typeof uninjectPrompts === 'function') uninjectPrompts([INR_V350_CARD_INJECTION]); } catch (_) {}
  inrV350Injection = null;
}

async function inrV350RefreshCardInjection() {
  await inrV350RemoveCardInjection();
  const effective = await inrV350EffectiveSettings();
  if (effective.activeMode !== 'card') return { active: false, reason: 'reader-mode' };
  if (!inrV350CanInject()) {
    await inrV350Log('warn', 'card-injection-unavailable', { helper: 'injectPrompts/uninjectPrompts' });
    toastr?.warning?.('当前酒馆助手版本没有可用的提示词注入能力，角色卡模式未启用。');
    return { active: false, reason: 'helper-unavailable' };
  }
  const ids = effective.character?.useOverride && Array.isArray(effective.character.cardRuleIds)
    ? effective.character.cardRuleIds
    : null;
  const content = await inrV350RuleText('card', ids);
  if (!content.trim()) return { active: false, reason: 'no-rules' };
  const result = injectPrompts([{
    id: INR_V350_CARD_INJECTION,
    position: 'in_chat',
    depth: 0,
    role: 'system',
    content,
  }]);
  inrV350Injection = result && typeof result === 'object' ? result : null;
  await inrV350Log('info', 'card-injection-active', { rules: content.split('\n## ').length });
  return { active: true };
}

function inrV350LlmApi(profile) {
