async function inrV350ComposeVideoPrompt(cfg, mode, payload) {
  const selected = await inrV350PromptProfile(cfg.__inrV350PromptProfileId);
  const entries = selected.profile?.entries || [];
  const messages = inrPresetMessages(entries, mode, cfg, payload);
  if (!messages.length) throw new Error('视频提示词预设没有启用的有效条目');
  const llm = await inrV350LlmProfiles();
  const profile = llm.profiles.find(item => item.id === cfg.__inrV350LlmProfileId) || llm.profiles.find(item => item.id === 'tavern-current') || llm.profiles[0];
  if (profile?.provider === 'openai') {
    try {
      return inrCleanPrompt(await inrApiChat(inrV350LlmApi(profile), messages));
    } catch (error) {
      await inrV350Log('warn', 'video-prompt-api-failed', { profile: profile.name, error: inrV350SafeError(error) });
      if (profile.fallback === false) throw error;
      toastr?.warning?.('独立视频提示词 API 失败，已改用酒馆当前 API。');
    }
  }
  const raw = await generateRaw({ user_input: '', should_silence: true, ordered_prompts: messages });
  const cleaned = inrCleanPrompt(raw);
  if (!cleaned) throw new Error('提示词 API 没有返回可用文本');
  return cleaned;
}

