  await inrV350Log('info', 'video-generate-start', { mode, scheme: scheme.name, backend: scheme.backend, model: scheme.modelFamily });
  try {
    const result = cfg.videoBackend === 'http'
      ? await inrGenerateHttpVideo(cfg, { ...opts, mode })
      : await inrGenerateComfyVideo(cfg, { ...opts, mode });
