async function inrFramesVideo(opts = {}) {
  const images = inrRecentImages();
  let firstSource = inrV350Text(opts.firstSource);
  let lastSource = inrV350Text(opts.lastSource);
  if (!firstSource || !lastSource) {
    if (images.length < 2) throw new Error('首尾帧方案需要至少两张已经显示在聊天中的插图');
    firstSource = images.at(-2).id;
    lastSource = images.at(-1).id;
  }
  if (firstSource === lastSource) throw new Error('首帧和尾帧不能是同一张图');
  const result = await inrGenerateVideo(null, { mode: 'frames', firstSource, lastSource, request: inrV350Text(opts.request) });
  const inserted = await inrInsertVideoAtImage(firstSource, result.url, result.prompt);
  if (!inserted) await createChatMessages([{ role: 'assistant', name: SillyTavern.name2, message: '**剧情视频**' + inrVideoHtml(result.url, result.prompt) }]);
