// Use only message-body images. This avoids the v3.4 issue where a button could
// land under unrelated UI or media elsewhere on a message floor.
function inrChatDocuments() { return inrV350HostDocuments(); }

function inrV350ScheduleVideoButtons() {
  clearTimeout(inrV350MountTimer);
  inrV350MountTimer = setTimeout(() => { inrMountVideoButtons(); }, 120);
}

function inrMountVideoButtons() {
  const images = inrRecentImages().filter(item => item.element?.closest?.('.mes_text'));
  const valid = new Set(images.map(item => item.id));
  for (const doc of inrV350HostDocuments()) {
    for (const button of doc.querySelectorAll('[data-inr-v35-frame]')) {
      if (!valid.has(button.dataset.inrV35Frame)) button.remove();
    }
  }
  for (let index = 0; index < images.length; index += 1) {
    const current = images[index];
    const next = images[index + 1];
    const image = current.element;
    const parent = image?.parentElement;
    if (!parent || !image.closest('.mes_text')) continue;
    const escapedId = typeof CSS !== 'undefined' && typeof CSS.escape === 'function'
      ? CSS.escape(current.id)
      : String(current.id).replace(/["\\]/g, '\\$&');
    let button = parent.querySelector('[data-inr-v35-frame="' + escapedId + '"]');
    if (!button) {
      button = image.ownerDocument.createElement('button');
      button.type = 'button';
      button.dataset.inrV35Frame = current.id;
      button.className = 'inr-v35-video-button';
      button.style.cssText = 'display:block;margin:6px 0 12px;max-width:100%;box-sizing:border-box;padding:6px 10px;border:1px solid var(--SmartThemeQuoteColor,#8250df);border-radius:4px;background:var(--SmartThemeBlurTintColor,#2d214a);color:var(--SmartThemeBodyColor,#e6edf3);cursor:pointer;font-size:12px;white-space:normal;text-align:left';
      button.addEventListener('click', async () => {
        if (button.disabled) return;
        const live = inrRecentImages().filter(item => item.element?.closest?.('.mes_text'));
        const at = live.findIndex(item => item.id === button.dataset.inrV35Frame);
        const first = live[at], last = live[at + 1];
        if (!first || !last) { toastr?.warning?.('下一张图片尚未显示，暂时不能生成过场视频'); return; }
        const old = button.textContent; button.disabled = true; button.textContent = '正在生成视频…';
        try { await inrFramesVideo({ firstSource: first.id, lastSource: last.id, request: '保持人物、服装、场景和画风连续，生成自然的过场镜头。' }); }
        catch (error) { toastr?.error?.('过场视频：' + (error?.message || error)); button.disabled = false; button.textContent = old; }
      });
      image.insertAdjacentElement('afterend', button);
    }
    button.disabled = !next;
    button.textContent = next ? '生成至下一图的过场视频' : '等待下一张图片';
  }
}

function inrV350WatchVideoButtons() {
  if (inrV350Observer) return;
  const doc = inrV350HostDocuments()[0];
  if (!doc?.body) return;
  inrV350Observer = new MutationObserver(inrV350ScheduleVideoButtons);
  inrV350Observer.observe(doc.body, { childList: true, subtree: true, attributes: true, attributeFilter: ['src', 'data-src', 'srcset'] });
  inrV350ScheduleVideoButtons();
}

function inrV350Next(book, state, settings, direction) {
  const readerMode = settings.readerMode;
  const pos = state.progress[readerMode] || { chapter: 0, page: -1 };
  let chapter = pos.chapter;
  let page = pos.page + (direction === 'previous' ? -1 : 1);
  if (page < 0) {
    chapter -= 1;
    if (chapter >= 0) page = inrPages(book.chapters[chapter].content, settings.size).length - 1;
  }
  let pages = inrPages(book.chapters[chapter]?.content, settings.size);
  if (page >= pages.length) { chapter += 1; page = 0; pages = inrPages(book.chapters[chapter]?.content, settings.size); }
  if (chapter < 0 || chapter >= book.chapters.length) return null;
  return { chapter, page, pages, content: pages[page], title: book.chapters[chapter].title };
}

function inrV353ModelOutputText(raw) {
  return String(raw || '')
    .replace(/<think>[\s\S]*?<\/think>/gi, ' ')
    .replace(/```(?:json)?/gi, '')
    .trim();
}

function inrV353ExtractJson(raw) {
  const text = inrV353ModelOutputText(raw);
  let start = -1; let depth = 0; let quoted = false; let escaped = false;
  for (let index = 0; index < text.length; index += 1) {
    const char = text[index];
    if (start < 0) {
      if (char === '{') { start = index; depth = 1; }
      continue;
    }
    if (quoted) {
      if (escaped) escaped = false;
      else if (char === '\\') escaped = true;
      else if (char === '"') quoted = false;
      continue;
    }
    if (char === '"') quoted = true;
    else if (char === '{') depth += 1;
    else if (char === '}') {
      depth -= 1;
      if (depth === 0) return JSON.parse(text.slice(start, index + 1));
    }
  }
  throw new Error('没有找到完整 JSON 对象');
}

function inrV353ComparableQuote(value) {
  return String(value || '').replace(/\s+/g, '').replace(/[“”]/g, '"').replace(/[‘’]/g, "'");
}

function inrV353NormalizeOriginalPlan(parsed, paragraphs, settings) {
  if (!parsed || typeof parsed !== 'object' || !Array.isArray(parsed.images)) throw new Error('JSON 缺少 images 数组');
  const images = []; const errors = [];
  for (const item of parsed.images.slice(0, settings.images)) {
    const after = Number(item?.after); const sourceQuote = String(item?.source_quote || '').trim();
    let prompt = String(item?.prompt || '').replace(/\\_/g, '_').trim();
    const subjectType = String(item?.subject_type || '').trim().toLowerCase();
    if (!Number.isInteger(after) || after < 0 || after >= paragraphs.length) { errors.push('段落序号无效'); continue; }
    if (!prompt) { errors.push('提示词为空'); continue; }
    if (/[\u3400-\u9fff]/.test(prompt)) { errors.push('Pony 提示词仍含中文'); continue; }
    if (!['person', 'object', 'environment'].includes(subjectType)) { errors.push('缺少有效的 subject_type'); continue; }
    if (/\b(?:goal|requirement|pressure|relationship|emotion|desire|rule|rules|mechanic|mechanics|concept|symbolism|meaning|intention|motivation|victory|defeat)\b/i.test(prompt)) {
      errors.push('提示词含有不可直接成像的抽象概念'); continue;
    }
    if (subjectType !== 'person') {
      const promptWithoutNoHumans = prompt.replace(/\bno humans\b/ig, '');
      if (/\b(?:\d*girls?|\d*boys?|women|men|woman|man|people|persons?|humans?|players?|characters?)\b/i.test(promptWithoutNoHumans)) {
        errors.push('纯物件或环境画面混入了人物标签'); continue;
      }
      if (!/\bno humans\b/i.test(prompt)) prompt = 'no humans, ' + prompt;
      if (!/\bscenery\b/i.test(prompt)) prompt = 'scenery, ' + prompt;
    }
    if (subjectType === 'person' && /\bno humans\b/i.test(prompt)) { errors.push('人物画面的 subject_type 与 no humans 冲突'); continue; }
    if (settings.originalRequireQuote) {
      if (!sourceQuote) { errors.push('缺少 source_quote'); continue; }
      const paragraph = inrV353ComparableQuote(paragraphs[after]); const quote = inrV353ComparableQuote(sourceQuote);
      if (!quote || !paragraph.includes(quote)) { errors.push('source_quote 不在对应段落中'); continue; }
    }
    images.push({ after, sourceQuote, subjectType, prompt });
  }
  if (!images.length) throw new Error(errors.length ? [...new Set(errors)].join('；') : 'images 为空');
  return { images, bridge: parsed.bridge && typeof parsed.bridge === 'object' ? parsed.bridge : {} };
}

async function inrV353OriginalRequest(request, settings, correction = '') {
  const userInput = correction
    ? [
      '你上一轮返回了内容，但格式校验失败。',
      '错误原因：' + correction,
      '重新执行下面的原始任务。不要复述错误输出，不要总结材料，只返回完整 JSON。',
      '原始任务：\n' + request,
    ].join('\n\n')
    : request;
  const orderedPrompts = [
    { role: 'system', content: settings.originalSystemPrompt || INR_V353_ORIGINAL_SYSTEM_PROMPT },
    'user_input',
  ];
  if (settings.originalSkipThinking !== false) orderedPrompts.push({ role: 'assistant', content: '<think>\n\n</think>\n\n' });
  return String(await generateRaw({
    user_input: userInput,
    should_silence: true,
    max_chat_history: 0,
    custom_api: {
      max_tokens: inrV350Clamp(settings.originalMaxTokens, 512, 8192, 4096),
      temperature: inrV350Clamp(settings.originalTemperature, 0, 2, 0.2),
      top_p: inrV350Clamp(settings.originalTopP, 0.05, 1, 0.9),
      frequency_penalty: 0,
      presence_penalty: 0,
    },
    ordered_prompts: orderedPrompts,
  }));
}

function inrV354OriginalStyle(value) {
  const text = inrV350Text(value).trim();
  if (!text) return { text: '', ignored: false };
  const looksLikeSourceMaterial = text.length > 1000 || /<\/?content>|剧情总结|编号原文段落|角色总结|第[一二三四五六七八九十百千\d]+章/.test(text);
  return looksLikeSourceMaterial ? { text: '', ignored: true } : { text, ignored: false };
}

function inrV355VisualReferenceIndex(value) {
  const source = inrV350Text(value)
    .replace(/<\/?content>/gi, '')
    .replace(/\r\n?/g, '\n')
    .trim();
  if (!source) return { opening: '', characters: [], locations: [] };
  const blocks = source.split(/\n\s*\n+/).map(item => item.trim()).filter(Boolean);
  const characterHeading = value => /^[^<>\n【】]{1,20}·[^<>\n【】]{1,20}$/.test(value);
  const characters = [];
  const locations = [];
  let opening = '';
  for (let index = 0; index < blocks.length; index += 1) {
    const block = blocks[index];
    const lines = block.split('\n').map(item => item.trim()).filter(Boolean);
    const firstLine = lines[0] || '';
    if (!opening && block.length >= 30 && block.length <= 600 && /[\u3400-\u9fff]/.test(block)
      && !/^[>＊*【]/.test(block) && !characterHeading(block) && !/天赋[:：]/.test(block)) opening = block;
    if (characterHeading(firstLine)) {
      const description = lines.slice(1).join('\n') || blocks[index + 1] || '';
      if (description && !/^[>＊*【]/.test(description) && !characterHeading(description)) {
        const cleaned = firstLine.replace(/[「」『』“”]/g, '').trim();
        const aliases = [cleaned, ...cleaned.split('·')]
          .map(item => item.trim())
          .filter(item => item.length >= 2);
        characters.push({ id: 'character:' + cleaned, name: cleaned, aliases: [...new Set(aliases)], text: firstLine + '\n' + description });
      }
    }
    for (const segment of block.split(/[；;]/)) {
      const match = segment.trim().match(/^([^—\n]{2,24})——(.{8,})$/);
      if (!match) continue;
      const name = match[1].trim();
      if (!locations.some(item => item.name === name)) locations.push({ id: 'location:' + name, name, aliases: [name], text: name + '——' + match[2].trim() });
    }
  }
  return { opening, characters, locations };
}

function inrV355SelectVisualReference(value, pageText, previousKeys = []) {
  const index = inrV355VisualReferenceIndex(value);
  if (!index.opening && !index.characters.length && !index.locations.length) return { text: '', keys: [], matched: 0 };
  const page = inrV350Text(pageText);
  const previous = new Set(Array.isArray(previousKeys) ? previousKeys.map(String) : []);
  const directCharacters = index.characters.filter(entry => entry.aliases.some(alias => page.includes(alias)));
  const directLocations = index.locations.filter(entry => entry.aliases.some(alias => page.includes(alias)));
  const selectedCharacters = [...directCharacters];
  const selectedLocations = [...directLocations];
  for (const entry of index.characters) {
    if (selectedCharacters.length >= 6) break;
    if (previous.has(entry.id) && !selectedCharacters.some(item => item.id === entry.id)) selectedCharacters.push(entry);
  }
  for (const entry of index.locations) {
    if (selectedLocations.length >= 2) break;
    if (previous.has(entry.id) && !selectedLocations.some(item => item.id === entry.id)) selectedLocations.push(entry);
  }
  const keys = [...selectedCharacters.map(item => item.id), ...selectedLocations.map(item => item.id)];
  const sections = [
    index.opening ? '全局视觉氛围：\n' + index.opening : '',
    selectedCharacters.length ? '本页相关人物外观：\n' + selectedCharacters.map(item => item.text).join('\n\n') : '',
    selectedLocations.length ? '本页相关地点：\n' + selectedLocations.map(item => item.text).join('\n') : '',
  ].filter(Boolean);
  return {
    text: sections.join('\n\n').slice(0, 6000),
    keys,
    matched: directCharacters.length + directLocations.length,
    indexedCharacters: index.characters.length,
    indexedLocations: index.locations.length,
  };
}

async function inrV350Original(content, settings, referenceContext = {}) {
  const paragraphs = String(content || '').split(/\n+/).map(item => item.trim()).filter(Boolean);
  if (!paragraphs.length) throw new Error('当前页没有可供取景的原文段落');
  const numbered = paragraphs.map((item, index) => '[' + index + '] ' + item).join('\n');
  const state = (await inrReaderStateData())?.stat_data?.__image_bridge || {};
  const inferenceRule = settings.originalAllowInference
    ? '允许补充不改变原文事实的光线、镜头和背景细节，但不得补造人物身份、人数、外貌、服装、关系或关键动作。'
    : '严格模式：原文没有写明的视觉事实全部省略，不得为了填满标签而补造。';
  const style = inrV354OriginalStyle(settings.style);
  if (style.ignored) await inrV350Log('warn', 'original-style-ignored', { reason: '画风补充疑似包含小说、设定或总结，已避免重复注入' });
  const visualReference = inrV355SelectVisualReference(
    referenceContext.book?.visualReference?.text,
    content,
    referenceContext.state?.visualReferenceMemory?.[referenceContext.state?.bookId],
  );
  const request = [
    settings.originalRules || INR_V353_ORIGINAL_RULES,
    INR_V355_VISUAL_GROUNDING_RULES,
    '输出结构：' + (settings.originalSchema || INR_V353_ORIGINAL_SCHEMA),
    'images 最多 ' + settings.images + ' 项。after 必须是方括号中的段落序号。每项都必须包含 subject_type，值只能是 person、object 或 environment。prompt 不要包含 <image>、image###、### 或 Markdown。',
    settings.originalRequireQuote ? '每个图片项目都必须提供 source_quote，且必须能在 after 对应的原文段落中逐字找到。' : 'source_quote 可以省略。',
    inferenceRule,
    style.text ? '仅在不改变原文事实的前提下应用以下画风：' + style.text : '',
    visualReference.text ? '配套视觉设定（只用于校准本页已经出现的人物和地点；不得把设定库中的其他人物添加到画面）：\n' + visualReference.text : '',
    Object.keys(state).length ? '已有视觉档案（仅用于保持同名人物一致，原文新事实优先）：' + JSON.stringify(state).slice(0, 5000) : '',
    '编号原文段落：\n' + numbered,
  ].filter(Boolean).join('\n\n');

  let raw = await inrV353OriginalRequest(request, settings); let plan;
  let firstReason = '';
  try {
    plan = inrV353NormalizeOriginalPlan(inrV353ExtractJson(raw), paragraphs, settings);
  } catch (firstError) {
    firstReason = inrV350SafeError(firstError);
    if (!settings.originalAutoRetry) throw new Error('模型返回了内容，但取景 JSON 无效：' + firstReason);
    await inrV350Log('warn', 'original-plan-retry', { error: firstReason });
    raw = await inrV353OriginalRequest(request, settings, firstReason);
    try { plan = inrV353NormalizeOriginalPlan(inrV353ExtractJson(raw), paragraphs, settings); }
    catch (secondError) {
      throw new Error('模型两次都有返回，但取景 JSON 均无效。第一次：' + firstReason + '；第二次：' + inrV350SafeError(secondError));
    }
  }

  const inserted = new Map();
  for (const item of plan.images) inserted.set(item.after, [...(inserted.get(item.after) || []), inrTag(item.prompt)]);
  return {
    body: paragraphs.map((item, index) => item + (inserted.has(index) ? '\n\n' + inserted.get(index).join('\n\n') : '')).join('\n\n'),
    bridge: plan.bridge,
    referenceKeys: visualReference.keys,
  };
}

async function inrV350Adapt(content, settings, referenceContext = {}) {
  const systemRules = await inrV350RuleText('reader');
  const visualReference = inrV355SelectVisualReference(
    referenceContext.book?.visualReference?.text,
    content,
    referenceContext.state?.visualReferenceMemory?.[referenceContext.state?.bookId],
  );
  const request = [
    '将下列小说片段改编为沉浸式图文小说。保留人物、事件顺序、关键信息和世界观。',
    '默认只改写重述，不增加原文未出现的剧情、心理、对白或细节；只有“改写要求”明确要求时才扩写。',
    '输出正文并插入恰好 ' + settings.images + ' 个 <image>image###提示词###</image> 标签。每条提示词对应当前可见场景。',
    '正文最后额外输出 <inr_bridge>JSON</inr_bridge>，只记录正文明确的角色和场景可见事实。',
    '图片标签必须完整保留 <image> 和 </image> 外层，不能写成 image###...###，也不能用 Markdown 粗体 **image###...###** 包裹；Pony/PonyXL 使用英文标签，中文模型使用中文描述。',
    settings.adaptation ? '改写要求：' + settings.adaptation : '',
    settings.style ? '画风补充：' + settings.style : '',
    visualReference.text ? '配套视觉设定（只用于校准本页已经出现的人物和地点；不得添加设定库中的其他人物）：\n' + visualReference.text : '',
    '原文：\n' + content,
  ].filter(Boolean).join('\n\n');
  const raw = String(await generateRaw({ user_input: request, should_silence: true, ordered_prompts: [{ role: 'system', content: '你是忠于原著的图文小说改编编辑。\n\n' + systemRules }, 'user_input'] })).trim();
  const normalized = inrNormalizeImageBlocks(raw);
  const bridge = normalized.match(/<inr_bridge>([\s\S]*?)<\/inr_bridge>/i);
  let bridgeData = {};
  if (bridge) try { bridgeData = JSON.parse(bridge[1].trim()); } catch (_) {}
  return {
    body: normalized.replace(/<inr_bridge>[\s\S]*?<\/inr_bridge>/ig, '').trim(),
    bridge: bridgeData,
    referenceKeys: visualReference.keys,
  };
}

async function inrV350PageBody(content, settings, referenceContext = {}) {
  return settings.readerMode === 'adapted'
    ? inrV350Adapt(content, settings, referenceContext)
    : inrV350Original(content, settings, referenceContext);
}

function inrV350PageHeader(book, pos) {
  return '<!--inr-reader-page v3.5-->' + '\n**《' + inrV350Escape(book.title) + '》 · ' + inrV350Escape(pos.title) + ' · 第' + (pos.page + 1) + '/' + pos.pages.length + '页**';
}

async function inrV350CreatePage(book, pos, settings, state, advance) {
  const rendered = await inrV350PageBody(pos.content, settings, { book, state });
  const meta = {
    version: INR_V350_VERSION, bookId: state.bookId, chapter: pos.chapter, page: pos.page,
    mode: settings.readerMode, size: settings.size, images: settings.images,
    sourceLength: String(pos.content || '').length, createdAt: Date.now(),
  };
  const message = inrV350PageHeader(book, pos) + '\n\n' + rendered.body;
  await createChatMessages([{ role: 'assistant', name: SillyTavern.name2, message, data: { [INR_V350_PAGE_META]: meta } }]);
  let messageId = null;
  try { messageId = getChatMessages(-1, { include_swipes: true })?.[0]?.message_id ?? null; } catch (_) {}
  meta.messageId = Number.isInteger(messageId) ? messageId : null;
  const bridgeTarget = Number.isInteger(meta.messageId) ? meta.messageId : 'latest';
  const bridgeResult = await inrSaveBridge(rendered.bridge, bridgeTarget);
  const nextState = inrV350Clone(state);
  if (advance) nextState.progress[settings.readerMode] = { chapter: pos.chapter, page: pos.page };
  nextState.visualReferenceMemory ||= {};
  nextState.visualReferenceMemory[state.bookId] = Array.isArray(rendered.referenceKeys) ? rendered.referenceKeys : [];
  nextState.lastPage = meta;
  await inrV350SaveChatState(nextState);
  await inrV350Log('info', 'reader-page-created', { mode: settings.readerMode, bridge: bridgeResult });
  return meta;
}

async function inrRead(direction) {
  const [settings, state, library] = await Promise.all([inrV350EffectiveSettings(), inrV350ChatState(), inrLibrary()]);
  if (settings.activeMode !== 'reader') throw new Error('当前是角色卡剧情模式，请切回“小说阅读”后再翻页');
  if (!state.bookId) throw new Error('请先导入并选择小说');
  const book = library.books?.[state.bookId];
  if (!book) throw new Error('找不到当前小说');
  const pos = inrV350Next(book, state, settings, direction);
  if (!pos) throw new Error(direction === 'previous' ? '已经是第一页' : '已经是最后一页');
  toastr?.info?.('正在生成图文阅读页…');
  await inrV350CreatePage(book, pos, settings, state, true);
  toastr?.success?.('已发送图文阅读页');
}

async function inrV350RerollPage() {
  const [settings, state, library] = await Promise.all([inrV350EffectiveSettings(), inrV350ChatState(), inrLibrary()]);
  const meta = state.lastPage;
  if (!meta || !meta.bookId) throw new Error('还没有可重 Roll 的阅读页');
  const book = library.books?.[meta.bookId];
  if (!book || !book.chapters?.[meta.chapter]) throw new Error('当前阅读页对应的小说或章节已不存在');
  const pages = inrPages(book.chapters[meta.chapter].content, meta.size || settings.size);
  const content = pages[meta.page];
  if (content === undefined) throw new Error('原文分页已变化，无法安全重 Roll；请重新选择章节');
  if (!Number.isInteger(meta.messageId) || typeof getChatMessages !== 'function' || typeof setChatMessages !== 'function') {
    throw new Error('当前酒馆助手无法定位原阅读楼层，不能安全重 Roll');
  }
  const current = getChatMessages(meta.messageId, { include_swipes: true })?.[0];
  if (!current) throw new Error('原阅读楼层已被删除，不能安全重 Roll');
  toastr?.info?.('正在重 Roll 当前页…');
  const pageSettings = { ...settings, readerMode: inrV350NormalizeReaderMode(meta.mode), size: meta.size || settings.size, images: meta.images || settings.images };
  const pos = { chapter: meta.chapter, page: meta.page, pages, content, title: book.chapters[meta.chapter].title };
  const rendered = await inrV350PageBody(content, pageSettings, { book, state });
  const nextMeta = { ...meta, createdAt: Date.now(), rerolledAt: Date.now() };
  const message = inrV350PageHeader(book, pos) + '\n\n' + rendered.body;
  const activeIndex = Number.isInteger(current.swipe_id) ? current.swipe_id : 0;
  const baseSwipes = Array.isArray(current.swipes) && current.swipes.length ? [...current.swipes] : [current.message || ''];
  const baseData = Array.isArray(current.swipes_data) && current.swipes_data.length ? [...current.swipes_data] : [current.data || {}];
  const baseInfo = Array.isArray(current.swipes_info) && current.swipes_info.length ? [...current.swipes_info] : [{}];
  if (!baseSwipes[activeIndex]) baseSwipes[activeIndex] = current.message || '';
  baseSwipes.push(message);
  baseData.push({ ...(current.data || {}), [INR_V350_PAGE_META]: nextMeta });
  baseInfo.push({ generated_by: 'illustrated-novel-reader-v3.5.5', generated_at: Date.now() });
  await setChatMessages([{
    message_id: meta.messageId, swipes: baseSwipes, swipes_data: baseData, swipes_info: baseInfo, swipe_id: baseSwipes.length - 1,
  }], { refresh: 'affected' });
  const bridgeResult = await inrSaveBridge(rendered.bridge, meta.messageId);
  const nextState = { ...state, lastPage: nextMeta };
  await inrV350SaveChatState(nextState);
  await inrV350Log('info', 'reader-page-rerolled', { mode: pageSettings.readerMode, bridge: bridgeResult });
  toastr?.success?.('当前页已生成新的 swipe，阅读进度未改变');
}

