function inrV350Option(value, label, selected) {
  return '<option value="' + inrV350Escape(value) + '"' + (String(value) === String(selected) ? ' selected' : '') + '>' + inrV350Escape(label) + '</option>';
}

function inrV350BookOptions(library, selected) {
  const rows = [inrV350Option('', '请选择小说', selected)];
  for (const [id, book] of Object.entries(library.books || {})) rows.push(inrV350Option(id, book.title || id, selected));
  return rows.join('');
}

function inrV350ChapterOptions(book, selected) {
  if (!book) return inrV350Option('0', '请先选择小说', '0');
  return (book.chapters || []).map((chapter, index) => inrV350Option(String(index), '第' + (index + 1) + '章 · ' + inrV350Text(chapter.title), String(selected))).join('');
}

function inrV355ReferenceSummary(book) {
  const reference = book?.visualReference;
  if (!reference?.text) return '尚未绑定设定 TXT。小说正文仍可正常阅读，但模型不会自动知道其他章节的人物外观。';
  return '已绑定：' + inrV350Text(reference.name, '设定 TXT') + '（' + String(reference.text).length + ' 字符）。每页只提取当前人物和地点的相关设定。';
}

