  return '<div class="inr-v35">' + inrV350BaseStyles() + '<div class="inr-v35-shell"><div class="inr-v35-head"><div><h2>图文视频小说阅读器 v3.5.5</h2><small>每本小说可绑定配套设定 TXT，并按当前人物与地点选择性注入。</small></div><div class="inr-v35-tabs" role="tablist"><button type="button" data-inr-v35-reader="tab-reader" aria-selected="' + (!card) + '">小说阅读</button><button type="button" data-inr-v35-reader="tab-card" aria-selected="' + card + '">角色卡剧情</button></div></div>' + (card ? cardPane : readerPane) + '</div></div>';
}

async function inrV350ReaderVm() {
  const [global, effective, character, state, library, rules] = await Promise.all([
    inrV350Global(), inrV350EffectiveSettings(), inrV350Character(), inrV350ChatState(), inrLibrary(), inrV350Rules(),
  ]);
  const injection = effective.activeMode === 'card' ? await inrV350RefreshCardInjection() : { active: false, reason: 'reader-mode' };
  return { global, effective, character, state, library, rules, injection };
}

function inrV350ReaderDraft($dlg, vm) {
  const field = selector => $dlg.find(selector).val();
  const global = { ...vm.global };
  $dlg.find('[data-inr-v35-global]').each(function () {
    global[$(this).attr('data-inr-v35-global')] = this.type === 'checkbox' ? $(this).is(':checked') : $(this).val();
  });
  global.readerMode = inrV350NormalizeReaderMode(global.readerMode);
  global.size = inrV350Clamp(global.size, 500, 20000, vm.global.size);
  global.images = inrV350Clamp(global.images, 1, 8, vm.global.images);
  global.originalMaxTokens = inrV350Clamp(global.originalMaxTokens, 512, 8192, vm.global.originalMaxTokens);
  global.originalTemperature = inrV350Clamp(global.originalTemperature, 0, 2, vm.global.originalTemperature);
  global.originalTopP = inrV350Clamp(global.originalTopP, 0.05, 1, vm.global.originalTopP);
  const state = inrV350Clone(vm.state);
  const bookId = field('[data-inr-v35-field="bookId"]');
  if (bookId !== state.bookId) {
    state.bookId = bookId || null;
    state.progress = { original: { chapter: 0, page: -1 }, adapted: { chapter: 0, page: -1 } };
  }
  return { global, state, chapter: Math.max(0, Number(field('[data-inr-v35-field="chapter"]')) || 0) };
}

async function inrV350ImportTxt(file, title, pattern) {
  const name = inrV350Text(file?.name, '未命名小说.txt');
  const text = inrV350Text(file?.text);
  const baseTitle = inrV350Text(title || name.replace(/\.txt$/i, '')).trim();
  if (!baseTitle) throw new Error('请填写书名');
  const library = await inrLibrary(); library.books ||= {};
  const titles = new Set(Object.values(library.books).map(book => inrV350Text(book?.title).trim()));
  let cleanTitle = baseTitle; let titleIndex = 2;
  while (titles.has(cleanTitle)) cleanTitle = baseTitle + ' (' + titleIndex++ + ')';
  let id = 'book_' + Date.now();
  while (library.books[id]) id += '_1';
  library.books[id] = { title: cleanTitle, chapters: inrChapters(text, cleanTitle, inrV350Text(pattern)), createdAt: Date.now() };
  await inrSaveLibrary(library);
  const state = await inrV350ChatState();
  state.bookId = id;
  state.progress = { original: { chapter: 0, page: -1 }, adapted: { chapter: 0, page: -1 } };
  state.lastPage = null;
  await inrV350SaveChatState(state);
  await inrV350Log('info', 'txt-imported', { scope: 'script-library' });
  return { id, title: cleanTitle, library, state };
}

async function inrOpen() {
  const initial = await inrV350ReaderVm();
  const popup = new SillyTavern.Popup(inrV350ReaderPanelHtml(initial), SillyTavern.POPUP_TYPE.DISPLAY, '', {
    wide: true, large: true, okButton: '关闭', cancelButton: false,
    onOpen: popupRef => {
      const $dlg = $(popupRef.content);
      let vm = initial;
      const render = async () => { vm = await inrV350ReaderVm(); $dlg.html(inrV350ReaderPanelHtml(vm)); };
      const status = (text, level = '') => { const node = $dlg.find('[data-inr-v35-status]'); node.text(text); node.attr('data-level', level); };
      const setActiveMode = async mode => {
        if (vm.character.useOverride) {
          await inrV350SaveCharacter({ ...vm.character, settings: { ...vm.character.settings, activeMode: mode } });
        } else await inrV350SaveGlobal({ ...vm.global, activeMode: mode });
      };
      $dlg.on('change', '[data-inr-v35-field="bookId"]', async function () {
        const library = await inrLibrary(); const book = library.books?.[$(this).val()];
        $dlg.find('[data-inr-v35-field="chapter"]').html(inrV350ChapterOptions(book, 0));
        $dlg.find('[data-inr-v35-reference-summary]').text(inrV355ReferenceSummary(book));
      });
      $dlg.on('click', '[data-inr-v35-reader]', async function () {
          const action = $(this).attr('data-inr-v35-reader');
        try {
          if (action === 'tab-reader' || action === 'reader-mode') {
            await setActiveMode('reader'); await inrV350RefreshCardInjection(); await render(); return;
          }
          if (action === 'tab-card') { await setActiveMode('card'); await inrV350RefreshCardInjection(); await render(); return; }
          if (action === 'rules') { await inrV350OpenRuleManager(() => render()); return; }
          if (action === 'choose-reference') {
            const bookId = inrV350Text($dlg.find('[data-inr-v35-field="bookId"]').val() || vm.state.bookId);
            if (!bookId) throw new Error('请先导入并选择一本小说');
            const input = document.createElement('input'); input.type = 'file'; input.accept = '.txt,text/plain';
            input.onchange = async event => {
              try {
                const file = event.target.files?.[0]; if (!file) return;
                if (file.size > 2 * 1024 * 1024) throw new Error('设定 TXT 不能超过 2 MB');
                const text = await file.text();
                if (!text.trim()) throw new Error('设定 TXT 是空文件');
                const library = await inrLibrary(); const book = library.books?.[bookId];
                if (!book) throw new Error('找不到刚才选择的小说，请重新选择');
                book.visualReference = { name: file.name, text, attachedAt: Date.now() };
                await inrSaveLibrary(library);
                const state = await inrV350ChatState();
                state.bookId = bookId;
                state.visualReferenceMemory ||= {}; state.visualReferenceMemory[bookId] = [];
                await inrV350SaveChatState(state);
                await render();
                status('已将《' + book.title + '》绑定到设定文件“' + file.name + '”。', 'ok');
                toastr?.success?.('配套设定 TXT 已绑定');
              } catch (error) {
                const safe = inrV350SafeError(error); status(safe, 'error'); toastr?.error?.(safe);
              }
            };
            input.click(); return;
          }
          if (action === 'choose-file') {
            const input = document.createElement('input'); input.type = 'file'; input.accept = '.txt,text/plain';
            input.onchange = async event => {
              const file = event.target.files?.[0]; if (!file) return;
              $dlg.data('inrV350Import', { name: file.name, text: await file.text() });
              $dlg.find('[data-inr-v35-import="title"]').val(file.name.replace(/\.txt$/i, ''));
              $dlg.find('[data-inr-v35-file]').text('已选择：' + file.name);
            };
            input.click(); return;
          }
          if (action === 'import') {
            const file = $dlg.data('inrV350Import'); if (!file) throw new Error('请先选择 TXT 文件');
            const title = inrV350Text($dlg.find('[data-inr-v35-import="title"]').val() || file.name).trim();
            const pattern = inrV350Text($dlg.find('[data-inr-v35-import="pattern"]').val());
            const imported = await inrV350ImportTxt(file, title, pattern);
            $dlg.removeData('inrV350Import');
            await render();
            status('已导入《' + imported.title + '》，已选中并刷新章节列表。', 'ok');
            toastr?.success?.('小说导入成功'); return;
          }
          if (action === 'card-save') {
            const scope = $dlg.find('[data-inr-v35-card="scope"]').val();
            const selectedRules = []; $dlg.find('[data-inr-v35-card-rule]').each(function () { if ($(this).is(':checked')) selectedRules.push($(this).attr('data-inr-v35-card-rule')); });
            if (scope === 'character') {
              await inrV350SaveCharacter({ ...vm.character, useOverride: true, settings: { ...vm.character.settings, activeMode: 'card' }, cardRuleIds: selectedRules });
            } else {
              await inrV350SaveCharacter({ ...vm.character, useOverride: false, cardRuleIds: vm.character.cardRuleIds });
              await inrV350SaveGlobal({ ...vm.global, activeMode: 'card' });
            }
            await inrV350RefreshCardInjection(); await render(); toastr?.success?.('角色卡剧情模式已保存'); return;
          }
          const draft = inrV350ReaderDraft($dlg, vm);
          if (vm.character.useOverride) {
            const patch = Object.fromEntries([
              'readerMode', 'size', 'images', 'style', 'adaptation',
              'originalSystemPrompt', 'originalRules', 'originalSchema', 'originalRequireQuote', 'originalAutoRetry', 'originalAllowInference',
              'originalMaxTokens', 'originalTemperature', 'originalTopP', 'originalSkipThinking',
            ].map(key => [key, draft.global[key]]));
            await inrV350SaveCharacter({ ...vm.character, settings: { ...vm.character.settings, ...patch } });
          } else await inrV350SaveGlobal(draft.global);
          await inrV350SaveChatState(draft.state);
          if (action === 'save') { status((vm.character.useOverride ? '当前角色独立设置' : '全局设置') + '已保存；书籍进度已保存到当前聊天。', 'ok'); return; }
          if (action === 'chapter') {
            const state = await inrV350ChatState(); state.progress[draft.global.readerMode] = { chapter: draft.chapter, page: -1 }; await inrV350SaveChatState(state); await inrRead('next'); return;
          }
          if (action === 'reroll') { await inrV350RerollPage(); return; }
          if (action === 'previous' || action === 'next') { await inrRead(action); return; }
        } catch (error) { const safe = inrV350SafeError(error); status(safe, 'error'); toastr?.error?.('图文阅读器：' + safe); console.error('[图文阅读器] 操作失败', safe); }
      });
    },
  });
  await popup.show();
}

