function inrV350ParseRulesFile(text) {
  const parsed = JSON.parse(String(text || ''));
  const entries = Array.isArray(parsed?.entries) ? parsed.entries : Object.values(parsed?.entries || parsed || {});
  if (!Array.isArray(entries) || !entries.length) throw new Error('文件中没有可导入的世界书条目');
  return entries.map((entry, index) => ({
    id: inrV350Text(entry?.id || entry?.uid || `import-rule-${Date.now()}-${index}`),
    name: inrV350Text(entry?.name || entry?.comment || `导入规则 ${index + 1}`),
    content: inrV350Text(entry?.content), enabled: entry?.enabled !== false && entry?.disable !== true,
    group: inrV350Text(entry?.group), order: Number(entry?.order) || index,
  })).filter(entry => entry.content.trim());
}

async function inrV350OpenRuleManager(onChanged) {
  let rules = await inrV350Rules();
  const popup = new SillyTavern.Popup(inrV350RuleManagerHtml(rules), SillyTavern.POPUP_TYPE.DISPLAY, '', {
    wide: true, large: true, okButton: '关闭', cancelButton: false,
    onOpen: popupRef => {
      const $dlg = $(popupRef.content);
      const render = () => $dlg.html(inrV350RuleManagerHtml(rules));
      const status = (text, level = '') => { const node = $dlg.find('[data-inr-v35-rule-status]'); node.text(text); node.attr('data-level', level); };
      const collect = () => {
        const entries = rules.entries.map(entry => ({ ...entry }));
        const byId = new Map(entries.map(entry => [entry.id, entry]));
        $dlg.find('[data-inr-v35-rule-name]').each(function () { const item = byId.get($(this).attr('data-inr-v35-rule-name')); if (item) item.name = inrV350Text($(this).val()).trim() || item.name; });
        $dlg.find('[data-inr-v35-rule-content]').each(function () { const item = byId.get($(this).attr('data-inr-v35-rule-content')); if (item) item.content = inrV350Text($(this).val()); });
        $dlg.find('[data-inr-v35-rule-enabled]').each(function () { const item = byId.get($(this).attr('data-inr-v35-rule-enabled')); if (item) item.enabled = $(this).is(':checked'); });
        const readerEnabledIds = []; $dlg.find('[data-inr-v35-reader-rule]').each(function () { if ($(this).is(':checked')) readerEnabledIds.push($(this).attr('data-inr-v35-reader-rule')); });
        const cardEnabledIds = []; $dlg.find('[data-inr-v35-card-rule]').each(function () { if ($(this).is(':checked')) cardEnabledIds.push($(this).attr('data-inr-v35-card-rule')); });
        return { ...rules, entries, readerEnabledIds, cardEnabledIds };
      };
      $dlg.on('click', '[data-inr-v35-rules]', async function () {
        const action = $(this).attr('data-inr-v35-rules');
        try {
          if (action === 'import') {
            const input = document.createElement('input'); input.type = 'file'; input.accept = '.json,application/json';
            input.onchange = async event => {
              const file = event.target.files?.[0]; if (!file) return;
              try {
                const entries = inrV350ParseRulesFile(await file.text());
                rules = inrV350NormalizeRules({ entries, readerEnabledIds: inrV350RuleIds(entries, 'reader'), cardEnabledIds: inrV350RuleIds(entries, 'card') });
                render(); status('已在面板中载入 ' + entries.length + ' 条规则，点击“保存规则”后写入脚本。', 'ok');
              } catch (error) { status(inrV350SafeError(error), 'error'); }
            };
            input.click(); return;
          }
          if (action === 'reset') { rules = inrV350NormalizeRules({ entries: INR_V350_BUNDLED_RULES }); render(); status('已恢复内置默认，点击“保存规则”后生效。', 'ok'); return; }
          if (action === 'save') {
            rules = inrV350NormalizeRules(collect()); await inrV350SaveRules(rules); await inrV350RefreshCardInjection(); await onChanged?.(); status('规则已保存。', 'ok'); return;
          }
        } catch (error) { status(inrV350SafeError(error), 'error'); }
      });
    },
  });
  await popup.show();
}

function inrV350WorkflowToApi(value) {
  if (!value || typeof value !== 'object') throw new Error('工作流 JSON 为空');
  if (!Array.isArray(value.nodes) || !Array.isArray(value.links)) return value;
  const links = new Map(value.links.filter(Array.isArray).map(link => [String(link[0]), link]));
  const workflow = {};
  for (const node of value.nodes) {
    if (node?.id == null || !node?.type) continue;
    const inputs = {}; const widgets = Array.isArray(node.widgets_values) ? node.widgets_values : []; let index = 0;
    for (const input of Array.isArray(node.inputs) ? node.inputs : []) {
      if (!input?.name) continue;
      const hasWidget = input.widget && typeof input.widget === 'object';
      const widgetValue = hasWidget ? widgets[index++] : undefined;
      if (input.link != null) {
        const link = links.get(String(input.link));
        if (link) inputs[input.name] = [String(link[1]), Number(link[2]) || 0];
      } else if (hasWidget && input.type !== 'IMAGEUPLOAD' && widgetValue !== undefined) {
        inputs[input.name] = inrV350Clone(widgetValue);
      }
    }
    workflow[String(node.id)] = { class_type: String(node.type), inputs };
  }
  if (!Object.keys(workflow).length) throw new Error('画布工作流没有可转换的节点');
  return workflow;
}

function inrV350WorkflowSummary(workflow) {
  return Object.entries(workflow || {}).map(([id, node]) => ({ id, type: inrV350Text(node?.class_type, 'Unknown'), inputs: Object.keys(node?.inputs || {}) }));
}

