function inrV350ApplyVideoFields($dlg, state) {
  const scheme = state.schemes.schemes.find(item => item.id === state.selectedSchemeId);
  if (!scheme) throw new Error('当前视频方案不存在');
  $dlg.find('[data-inr-v35-video-field]').each(function () {
    const path = $(this).attr('data-inr-v35-video-field');
    const value = this.type === 'checkbox' ? $(this).is(':checked') : $(this).val();
    inrV350SetPath(scheme, path, value);
  });
  $dlg.find('[data-inr-v35-global-video]').each(function () { state.global[$(this).attr('data-inr-v35-global-video')] = $(this).val(); });
  scheme.backend = scheme.backend === 'http' ? 'http' : 'comfy';
  for (const mode of ['frames', 'text']) {
    const part = scheme[mode];
    part.duration = inrV350Clamp(part.duration, 3, 15, 5);
    part.seed = Number.isSafeInteger(Number(part.seed)) ? Number(part.seed) : -1;
    part.bindings = { ...inrV350DefaultBindings(mode), ...(part.bindings || {}) };
    part.models ||= {};
  }
  scheme.updatedAt = Date.now();
  return scheme;
}

function inrV350Download(name, value) {
  const blob = new Blob([JSON.stringify(value, null, 2)], { type: 'application/json;charset=utf-8' });
  const url = URL.createObjectURL(blob); const anchor = document.createElement('a');
  anchor.href = url; anchor.download = name; anchor.click(); setTimeout(() => URL.revokeObjectURL(url), 3000);
}

function inrV350WorkflowGraph(workflow) {
  const rawNodes = Object.entries(workflow || {}).map(([id, node]) => ({
    id: String(id), type: inrV350Text(node?.class_type, 'Unknown'), inputs: node?.inputs || {},
  }));
  const known = new Set(rawNodes.map(node => node.id));
  const incoming = new Map(rawNodes.map(node => [node.id, []]));
  const edges = [];
  for (const node of rawNodes) {
    for (const [input, value] of Object.entries(node.inputs)) {
      if (!Array.isArray(value) || !known.has(String(value[0]))) continue;
      const edge = { from: String(value[0]), to: node.id, input: String(input) };
      incoming.get(node.id).push(edge); edges.push(edge);
    }
  }
  const depths = new Map(); const visiting = new Set();
  const depthOf = id => {
    if (depths.has(id)) return depths.get(id);
    if (visiting.has(id)) return 0;
    visiting.add(id);
    const depth = Math.max(0, ...(incoming.get(id) || []).map(edge => depthOf(edge.from) + 1));
    visiting.delete(id); depths.set(id, depth); return depth;
  };
  const columns = new Map();
  for (const node of rawNodes) {
    const depth = depthOf(node.id); const list = columns.get(depth) || []; list.push(node); columns.set(depth, list);
  }
  const positioned = [];
  for (const [depth, list] of columns) {
    list.forEach((node, row) => positioned.push({ ...node, x: 22 + depth * 230, y: 22 + row * 116 }));
  }
  const lookup = new Map(positioned.map(node => [node.id, node]));
  const width = Math.max(680, ...positioned.map(node => node.x + 202));
  const height = Math.max(360, ...positioned.map(node => node.y + 88));
  return { nodes: positioned, edges, lookup, width, height };
}

function inrV350WorkflowValueText(value) {
  return value && typeof value === 'object' ? JSON.stringify(value) : String(value ?? '');
}

function inrV350CoerceWorkflowValue(raw, previous) {
  if (typeof previous === 'number') {
    const value = Number(raw); if (!Number.isFinite(value)) throw new Error('数值参数必须是有效数字'); return value;
  }
  if (typeof previous === 'boolean') return String(raw).trim().toLowerCase() === 'true';
  if (previous && typeof previous === 'object') {
    try { return JSON.parse(String(raw)); } catch (_) { throw new Error('对象参数必须是合法 JSON'); }
  }
  return String(raw);
}

function inrV350WorkflowViewerHtml(mode, workflow, selected = '') {
  const graph = inrV350WorkflowGraph(workflow);
  const lines = graph.edges.map(edge => {
    const from = graph.lookup.get(edge.from), to = graph.lookup.get(edge.to);
    return from && to ? '<line x1="' + (from.x + 194) + '" y1="' + (from.y + 43) + '" x2="' + to.x + '" y2="' + (to.y + 43) + '"></line>' : '';
  }).join('');
  const cards = graph.nodes.map(node => '<button type="button" class="inr-v35-workflow-node' + (node.id === selected ? ' is-selected' : '') + '" data-inr-v35-workflow="node" data-node="' + inrV350Escape(node.id) + '" style="left:' + node.x + 'px;top:' + node.y + 'px"><b>#' + inrV350Escape(node.id) + '</b><span>' + inrV350Escape(node.type) + '</span><small>' + Object.keys(node.inputs).length + ' 个输入</small></button>').join('');
  const title = mode === 'frames' ? '首尾帧' : '文生视频';
  return '<div class="inr-v35">' + inrV350BaseStyles()
    + '<style>.inr-v35 .inr-v35-workflow-layout{display:grid;grid-template-columns:minmax(520px,1fr) minmax(250px,320px);gap:10px;min-width:0}.inr-v35 .inr-v35-workflow-canvas{overflow:auto;min-height:420px;border:1px solid var(--inr-line);border-radius:6px;background:repeating-linear-gradient(0deg,transparent 0 19px,color-mix(in srgb,var(--inr-line) 28%,transparent) 20px),repeating-linear-gradient(90deg,transparent 0 19px,color-mix(in srgb,var(--inr-line) 28%,transparent) 20px)}.inr-v35 .inr-v35-workflow-graph{position:relative}.inr-v35 .inr-v35-workflow-graph svg{position:absolute;inset:0;pointer-events:none}.inr-v35 .inr-v35-workflow-graph line{stroke:var(--inr-accent);stroke-width:1.5;opacity:.72}.inr-v35 .inr-v35-workflow-node{position:absolute;width:194px;min-height:86px;margin:0;text-align:left;overflow:hidden;background:var(--inr-panel);border-color:var(--inr-line)}.inr-v35 .inr-v35-workflow-node.is-selected{border-color:var(--inr-accent);box-shadow:0 0 0 1px var(--inr-accent)}.inr-v35 .inr-v35-workflow-node b,.inr-v35 .inr-v35-workflow-node span,.inr-v35 .inr-v35-workflow-node small{display:block;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.inr-v35 .inr-v35-workflow-node small{margin-top:4px;color:var(--inr-sub)}.inr-v35 .inr-v35-workflow-inspector{min-width:0;max-height:520px;overflow:auto}.inr-v35 .inr-v35-workflow-inspector textarea{min-height:56px}.inr-v35 .inr-v35-workflow-json{min-height:360px;font-family:monospace;font-size:12px}@media(max-width:700px){.inr-v35 .inr-v35-workflow-layout{grid-template-columns:minmax(0,1fr)}.inr-v35 .inr-v35-workflow-canvas{min-height:330px}.inr-v35 .inr-v35-workflow-inspector{max-height:none}}</style>'
    + '<div class="inr-v35-shell"><h2>' + title + '工作流查看 / 编辑</h2><p class="inr-v35-note">点选节点可编辑未连线参数；连线输入只读。下方 JSON 仅在点击“应用 JSON”时被解析，脚本不会执行其中的字符串或代码。</p><div class="inr-v35-workflow-layout"><div class="inr-v35-workflow-canvas"><div class="inr-v35-workflow-graph" style="width:' + graph.width + 'px;height:' + graph.height + 'px"><svg width="' + graph.width + '" height="' + graph.height + '">' + lines + '</svg>' + cards + '</div></div><aside class="inr-v35-card inr-v35-workflow-inspector"><h3>节点参数</h3><div data-inr-v35-workflow-inspector><p class="inr-v35-muted">从左侧选择一个节点。</p></div></aside></div><details><summary>高级：直接编辑 API JSON</summary><textarea class="inr-v35-workflow-json" data-inr-v35-workflow-json>' + inrV350Escape(JSON.stringify(workflow, null, 2)) + '</textarea><div class="inr-v35-actions"><button type="button" data-inr-v35-workflow="apply-json">应用 JSON 到节点图</button></div></details><div class="inr-v35-actions"><button type="button" data-kind="primary" data-inr-v35-workflow="save">保存到当前方案</button></div><div class="inr-v35-status" data-inr-v35-workflow-status></div></div></div>';
}

async function inrV350OpenWorkflowViewer(mode, workflow, onSave) {
  let working = inrV350Clone(workflow); let selected = '';
  const popup = new SillyTavern.Popup(inrV350WorkflowViewerHtml(mode, working, selected), SillyTavern.POPUP_TYPE.DISPLAY, '', {
    wide: true, large: true, okButton: '关闭', cancelButton: false,
    onOpen: popupRef => {
      const $dlg = $(popupRef.content);
      const status = (text, level = '') => $dlg.find('[data-inr-v35-workflow-status]').text(text).attr('data-level', level);
      const captureSelected = () => {
        if (!selected || !working[selected]) return;
        $dlg.find('[data-inr-v35-workflow-input]').each(function () {
          const input = $(this).attr('data-inr-v35-workflow-input');
          working[selected].inputs[input] = inrV350CoerceWorkflowValue($(this).val(), working[selected].inputs[input]);
        });
      };
      const showInspector = id => {
        selected = String(id); const node = working[selected]; if (!node) return;
        const editable = Object.entries(node.inputs || {}).filter(([, value]) => !Array.isArray(value));
        const linked = Object.entries(node.inputs || {}).filter(([, value]) => Array.isArray(value));
        const fields = editable.length
          ? editable.map(([name, value]) => '<label><span>' + inrV350Escape(name) + '</span><textarea data-inr-v35-workflow-input="' + inrV350Escape(name) + '">' + inrV350Escape(inrV350WorkflowValueText(value)) + '</textarea></label>').join('')
          : '<p class="inr-v35-muted">这个节点没有可直接编辑的未连线参数。</p>';
        const links = linked.length ? '<p class="inr-v35-muted">连线输入：<br>' + linked.map(([name, value]) => inrV350Escape(name + ' ← #' + value[0] + ':' + value[1])).join('<br>') + '</p>' : '';
        $dlg.find('[data-inr-v35-workflow-inspector]').html('<b>#' + inrV350Escape(selected) + '</b><br><span class="inr-v35-muted">' + inrV350Escape(node.class_type || '') + '</span>' + fields + links);
      };
      const render = () => { $dlg.html(inrV350WorkflowViewerHtml(mode, working, selected)); if (selected) showInspector(selected); };
      $dlg.on('click', '[data-inr-v35-workflow]', async function () {
        const action = $(this).attr('data-inr-v35-workflow');
        try {
          if (action === 'node') { captureSelected(); showInspector($(this).attr('data-node')); $dlg.find('[data-inr-v35-workflow="node"]').removeClass('is-selected'); $(this).addClass('is-selected'); return; }
          if (action === 'apply-json') {
            captureSelected(); working = inrV350WorkflowToApi(JSON.parse($dlg.find('[data-inr-v35-workflow-json]').val())); selected = ''; render(); status('JSON 已应用到节点图。', 'ok'); return;
          }
          if (action === 'save') { captureSelected(); await onSave(inrV350Clone(working)); status('已暂存到当前方案。回到视频设置后点击“保存所有设置”正式写入。', 'ok'); }
        } catch (error) { status(inrV350SafeError(error), 'error'); }
      });
    },
  });
  await popup.show();
}

function inrV350PromptManagerHtml(store, activeId) {
  const profile = store.profiles[activeId] || store.profiles[store.active] || Object.values(store.profiles)[0];
  const active = Object.entries(store.profiles).find(([, item]) => item === profile)?.[0] || store.active;
  return '<div class="inr-v35">' + inrV350BaseStyles() + '<div class="inr-v35-shell"><h2>视频提示词预设</h2><div class="inr-v35-grid"><label><span>预设方案</span><select data-inr-v35-preset="select">' + inrV350ProfileOptions(store, active) + '</select></label><label><span>方案名称</span><input data-inr-v35-preset="name" value="' + inrV350Escape(profile.name) + '"></label></div><p class="inr-v35-note">预设内容用 JSON 数组保存。每个条目包含 name、role、content、enabled、scope（all/frames/text）、order 等字段；可从旧版导出的预设继续迁移。</p><textarea data-inr-v35-preset="entries" style="min-height:420px;font-family:monospace;font-size:12px">' + inrV350Escape(JSON.stringify(profile.entries, null, 2)) + '</textarea><div class="inr-v35-actions"><button type="button" data-inr-v35-preset="new">新建方案</button><button type="button" data-inr-v35-preset="duplicate">复制方案</button><button type="button" data-kind="danger" data-inr-v35-preset="delete">删除方案</button><button type="button" data-kind="primary" data-inr-v35-preset="save">保存预设</button></div><div class="inr-v35-status" data-inr-v35-preset-status></div></div></div>';
}

async function inrV350OpenPromptManager(onChanged) {
  let store = await inrPresetStore(); let active = store.active;
  const popup = new SillyTavern.Popup(inrV350PromptManagerHtml(store, active), SillyTavern.POPUP_TYPE.DISPLAY, '', {
    wide: true, large: true, okButton: '关闭', cancelButton: false,
    onOpen: popupRef => {
      const $dlg = $(popupRef.content);
      const render = () => $dlg.html(inrV350PromptManagerHtml(store, active));
      const status = (text, level = '') => $dlg.find('[data-inr-v35-preset-status]').text(text).attr('data-level', level);
      $dlg.on('click', '[data-inr-v35-preset]', async function () {
        const action = $(this).attr('data-inr-v35-preset');
        try {
          if (action === 'select') { active = $(this).val(); render(); return; }
          if (action === 'new' || action === 'duplicate') {
            const id = inrV350Id('profile'); const template = action === 'duplicate' ? inrV350Clone(store.profiles[active]) : { name: '新视频提示词预设', entries: [] };
            store.profiles[id] = { name: (template.name || '预设') + (action === 'duplicate' ? ' 副本' : ''), entries: (template.entries || []).map(inrPresetNormalize) }; active = id; render(); return;
          }
          if (action === 'delete') {
            if (Object.keys(store.profiles).length <= 1) throw new Error('至少保留一个提示词预设');
            delete store.profiles[active]; active = Object.keys(store.profiles)[0]; render(); return;
          }
          if (action === 'save') {
            const profile = store.profiles[active]; profile.name = inrV350Text($dlg.find('[data-inr-v35-preset="name"]').val()).trim() || profile.name;
            const entries = JSON.parse($dlg.find('[data-inr-v35-preset="entries"]').val());
            if (!Array.isArray(entries)) throw new Error('预设条目必须是 JSON 数组');
            profile.entries = entries.map(inrPresetNormalize); store.active = active; await inrSaveStore(store); await onChanged?.(); status('提示词预设已保存。', 'ok'); return;
          }
        } catch (error) { status(inrV350SafeError(error), 'error'); }
      });
      $dlg.on('change', '[data-inr-v35-preset="select"]', function () { active = $(this).val(); render(); });
    },
  });
  await popup.show();
}

function inrV350LlmManagerHtml(store, selected) {
  const profile = store.profiles.find(item => item.id === selected) || store.profiles[0];
  const selectedId = profile.id;
  const openai = profile.provider === 'openai';
  return '<div class="inr-v35">' + inrV350BaseStyles() + '<div class="inr-v35-shell"><h2>视频提示词独立 API</h2><p class="inr-v35-note">这里仅用于生成视频提示词。使用“酒馆当前 API”时不会保存或复制主 API；独立 API 的密钥不会包含在视频方案导出和诊断中。</p><div class="inr-v35-grid"><label><span>API 方案</span><select data-inr-v35-llm="select">' + inrV350LlmOptions(store, selectedId) + '</select></label><label><span>名称</span><input data-inr-v35-llm="name" value="' + inrV350Escape(profile.name) + '"></label><label><span>类型</span><select data-inr-v35-llm="provider">' + inrV350Option('tavern', '酒馆当前 API', profile.provider) + inrV350Option('openai', '独立 OpenAI 兼容 API', profile.provider) + '</select></label></div><div' + (openai ? '' : ' class="inr-v35-muted"') + '><div class="inr-v35-grid"><label><span>接口地址</span><input data-inr-v35-llm="url" value="' + inrV350Escape(profile.url) + '" placeholder="https://example.com/v1"></label><label><span>模型名</span><input data-inr-v35-llm="model" value="' + inrV350Escape(profile.model) + '"></label><label><span>API Key</span><input type="password" data-inr-v35-llm="key" value="' + inrV350Escape(profile.key) + '"></label><label><span>附加请求头 JSON</span><textarea data-inr-v35-llm="headers">' + inrV350Escape(profile.headers) + '</textarea></label><label><span>温度</span><input type="number" min="0" max="2" step="0.1" data-inr-v35-llm="temperature" value="' + profile.temperature + '"></label><label><span>超时（秒）</span><input type="number" min="10" max="600" step="10" data-inr-v35-llm="timeout" value="' + profile.timeout + '"></label></div><label class="inr-v35-check"><input type="checkbox" data-inr-v35-llm="fallback"' + (profile.fallback ? ' checked' : '') + '><span>独立 API 失败后改用酒馆当前 API</span></label></div><div class="inr-v35-actions"><button type="button" data-inr-v35-llm="new">新建 API 方案</button><button type="button" data-kind="danger" data-inr-v35-llm="delete">删除方案</button><button type="button" data-inr-v35-llm="test">测试当前 API</button><button type="button" data-kind="primary" data-inr-v35-llm="save">保存 API 方案</button></div><div class="inr-v35-status" data-inr-v35-llm-status></div></div></div>';
}

async function inrV350OpenLlmManager(onChanged) {
  let store = await inrV350LlmProfiles(); let selected = store.profiles[0]?.id;
  const popup = new SillyTavern.Popup(inrV350LlmManagerHtml(store, selected), SillyTavern.POPUP_TYPE.DISPLAY, '', {
    wide: true, large: true, okButton: '关闭', cancelButton: false,
    onOpen: popupRef => {
      const $dlg = $(popupRef.content);
      const render = () => $dlg.html(inrV350LlmManagerHtml(store, selected));
      const status = (text, level = '') => $dlg.find('[data-inr-v35-llm-status]').text(text).attr('data-level', level);
      const collect = () => {
        const profile = store.profiles.find(item => item.id === selected); if (!profile) throw new Error('当前 API 方案不存在');
        ['name', 'provider', 'url', 'model', 'key', 'headers', 'temperature', 'timeout'].forEach(key => { const node = $dlg.find('[data-inr-v35-llm="' + key + '"]'); if (node.length) profile[key] = node.val(); });
        profile.fallback = $dlg.find('[data-inr-v35-llm="fallback"]').is(':checked');
        return profile;
      };
      $dlg.on('change', '[data-inr-v35-llm="select"],[data-inr-v35-llm="provider"]', function () { if ($(this).attr('data-inr-v35-llm') === 'select') selected = $(this).val(); else collect(); render(); });
      $dlg.on('click', '[data-inr-v35-llm]', async function () {
        const action = $(this).attr('data-inr-v35-llm');
        try {
          if (action === 'new') { const profile = { id: inrV350Id('llm'), name: '新的独立 API', provider: 'openai', url: '', key: '', model: '', temperature: 0.8, maxTokens: 2000, headers: '{}', retries: 1, timeout: 120, fallback: true }; store.profiles.push(profile); selected = profile.id; render(); return; }
          if (action === 'delete') { if (selected === 'tavern-current') throw new Error('“酒馆当前 API”是内置方案，不能删除'); if (store.profiles.length <= 1) throw new Error('至少保留一个 API 方案'); store.profiles = store.profiles.filter(item => item.id !== selected); selected = store.profiles[0].id; render(); return; }
          const profile = collect();
          if (action === 'test') { const api = inrV350LlmApi(profile); if (profile.provider !== 'openai') { status('酒馆当前 API 将在实际生成提示词时使用。', 'ok'); return; } const reply = await inrApiChat(api, [{ role: 'user', content: 'Reply with OK only.' }]); status('测试成功：' + inrV350Text(reply).slice(0, 80), 'ok'); return; }
          if (action === 'save') { store = inrV350NormalizeLlmProfiles(store); await inrV350SaveLlmProfiles(store); await onChanged?.(); status('独立 API 方案已保存。', 'ok'); return; }
        } catch (error) { status(inrV350SafeError(error), 'error'); }
      });
    },
  });
  await popup.show();
}

async function inrV350VideoVm(tab = 'overview', selectedSchemeId = '') {
  const [global, schemes, presets, llm, logs] = await Promise.all([
    inrV350Global(), inrV350Schemes(), inrPresetStore(), inrV350LlmProfiles(), inrV350ScriptValue(INR_V350_LOGS, []),
  ]);
  return {
    global: inrV350Clone(global), schemes: inrV350Clone(schemes), presets: inrV350Clone(presets), llm: inrV350Clone(llm),
    tab: ['overview', 'frames', 'text', 'prompt', 'diagnostics'].includes(tab) ? tab : 'overview',
    selectedSchemeId: selectedSchemeId || schemes.schemes[0]?.id || '', logs: Array.isArray(logs) ? logs : [],
  };
}

function inrV350ImportSchemePayload(text) {
  const parsed = JSON.parse(String(text || ''));
  const list = Array.isArray(parsed?.schemes) ? parsed.schemes : (Array.isArray(parsed) ? parsed : [parsed]);
  const valid = list.filter(item => item && typeof item === 'object' && (item.frames || item.text || item.backend));
  if (!valid.length) throw new Error('文件中没有可导入的视频方案');
  return valid.map((scheme, index) => inrV350NormalizeScheme({ ...scheme, id: inrV350Id('scheme'), name: (scheme.name || '导入方案') + (valid.length > 1 ? ' ' + (index + 1) : '') }, index));
}

async function inrOpenVideoSettings() {
  let vm = await inrV350VideoVm();
  const popup = new SillyTavern.Popup(inrV350VideoPanelHtml(vm), SillyTavern.POPUP_TYPE.DISPLAY, '', {
    wide: true, large: true, okButton: '关闭', cancelButton: false,
    onOpen: popupRef => {
      const $dlg = $(popupRef.content);
      const render = () => $dlg.html(inrV350VideoPanelHtml(vm));
      const status = (text, level = '') => $dlg.find('[data-inr-v35-video-status]').text(text).attr('data-level', level);
      const current = () => vm.schemes.schemes.find(item => item.id === vm.selectedSchemeId) || vm.schemes.schemes[0];
      const persist = async () => {
        inrV350ApplyVideoFields($dlg, vm);
        vm.schemes = inrV350NormalizeSchemes(vm.schemes);
        vm.global = inrV350NormalizeGlobal(vm.global);
        await Promise.all([inrV350SaveSchemes(vm.schemes), inrV350SaveGlobal(vm.global)]);
      };
      const loadWorkflow = async (input, mode) => {
        const file = input.files?.[0]; if (!file) return;
        try {
          const workflow = inrV350WorkflowToApi(JSON.parse(await file.text()));
          const scheme = current(); scheme[mode].workflow = workflow;
          const detected = inrDetectBindings(workflow);
          scheme[mode].bindings = { ...scheme[mode].bindings, ...detected };
          status((mode === 'frames' ? '首尾帧' : '文生视频') + '工作流已导入并自动识别映射；点击“保存所有设置”生效。', 'ok');
          render();
        } catch (error) { status('导入工作流：' + (error?.message || error), 'error'); }
        finally { input.value = ''; }
      };
      $dlg.on('change', '[data-inr-v35-video-workflow]', function () { loadWorkflow(this, $(this).attr('data-inr-v35-video-workflow')); });
      $dlg.on('change', '[data-inr-v35-video="scheme-select"]', function () {
        try { inrV350ApplyVideoFields($dlg, vm); } catch (_) {}
        vm.selectedSchemeId = $(this).val(); render();
      });
      $dlg.on('click', '[data-inr-v35-video]', async function () {
        const action = $(this).attr('data-inr-v35-video');
        const mode = $(this).attr('data-mode');
        try {
          if (action === 'tab') { try { inrV350ApplyVideoFields($dlg, vm); } catch (_) {} vm.tab = $(this).attr('data-tab'); render(); return; }
          if (action === 'save') { await persist(); status('视频设置已保存。', 'ok'); return; }
          if (action === 'new-scheme') {
            try { inrV350ApplyVideoFields($dlg, vm); } catch (_) {}
            const scheme = inrV350DefaultScheme({}); scheme.id = inrV350Id('scheme'); scheme.name = '新视频方案'; vm.schemes.schemes.push(scheme); vm.selectedSchemeId = scheme.id; render(); return;
          }
          if (action === 'copy-scheme') {
            try { inrV350ApplyVideoFields($dlg, vm); } catch (_) {}
            const copy = inrV350Clone(current()); copy.id = inrV350Id('scheme'); copy.name += ' 副本'; copy.createdAt = copy.updatedAt = Date.now(); vm.schemes.schemes.push(copy); vm.selectedSchemeId = copy.id; render(); return;
          }
          if (action === 'delete-scheme') {
            if (vm.schemes.schemes.length <= 1) throw new Error('至少保留一个视频方案');
            const removed = current(); vm.schemes.schemes = vm.schemes.schemes.filter(item => item.id !== removed.id); vm.selectedSchemeId = vm.schemes.schemes[0].id;
            if (vm.global.activeFrameSchemeId === removed.id) vm.global.activeFrameSchemeId = vm.selectedSchemeId;
            if (vm.global.activeTextSchemeId === removed.id) vm.global.activeTextSchemeId = vm.selectedSchemeId;
            render(); return;
          }
          if (action === 'export-scheme') { try { inrV350ApplyVideoFields($dlg, vm); } catch (_) {} inrV350Download('图文小说阅读器_视频方案_' + current().name.replace(/[\\/:*?"<>|]/g, '_') + '.json', inrV350Redact({ schemaVersion: 1, schemes: [current()] })); status('已导出脱敏方案。', 'ok'); return; }
          if (action === 'import-scheme') {
            const input = document.createElement('input'); input.type = 'file'; input.accept = '.json,application/json';
            input.onchange = async event => {
              const file = event.target.files?.[0]; if (!file) return;
              try { const imported = inrV350ImportSchemePayload(await file.text()); vm.schemes.schemes.push(...imported); vm.selectedSchemeId = imported[0].id; render(); status('已导入 ' + imported.length + ' 个方案，点击“保存所有设置”写入。', 'ok'); }
              catch (error) { status('导入方案：' + inrV350SafeError(error), 'error'); }
            };
            input.click(); return;
          }
          if (action === 'view-workflow') {
            try { inrV350ApplyVideoFields($dlg, vm); } catch (_) {}
            const scheme = current(); await inrV350OpenWorkflowViewer(mode, scheme[mode].workflow, async workflow => { scheme[mode].workflow = workflow; scheme[mode].bindings = { ...scheme[mode].bindings, ...inrDetectBindings(workflow) }; }); return;
          }
          if (action === 'detect-bindings') {
            try { inrV350ApplyVideoFields($dlg, vm); } catch (_) {}
            const scheme = current(); const detected = inrDetectBindings(scheme[mode].workflow); scheme[mode].bindings = { ...scheme[mode].bindings, ...detected }; render(); status((mode === 'frames' ? '首尾帧' : '文生视频') + '映射已自动识别。', 'ok'); return;
          }
          if (action === 'manage-presets') { await inrV350OpenPromptManager(async () => { vm.presets = await inrPresetStore(); render(); }); return; }
          if (action === 'manage-llm') { await inrV350OpenLlmManager(async () => { vm.llm = await inrV350LlmProfiles(); render(); }); return; }
          if (action === 'test-llm') {
            try { inrV350ApplyVideoFields($dlg, vm); } catch (_) {}
            const mode = $(this).attr('data-mode') === 'text' ? 'text' : 'frames';
            const scheme = current(); const profileId = scheme[mode].llmProfileId;
            const profile = (await inrV350LlmProfiles()).profiles.find(item => item.id === profileId);
            if (!profile || profile.provider === 'tavern') { status('酒馆当前 API 会在实际提示词生成时使用；无需额外连接测试。', 'ok'); return; }
            const answer = await inrApiChat(inrV350LlmApi(profile), [{ role: 'user', content: 'Reply with OK only.' }]); status('独立 API 测试成功：' + inrV350Text(answer).slice(0, 80), 'ok'); return;
          }
          if (action === 'test-comfy') {
            try { inrV350ApplyVideoFields($dlg, vm); } catch (_) {}
            const cfg = inrV350SchemeLegacy(current(), 'frames'); const base = await inrComfyBase(cfg, true); status('ComfyUI 连接成功：' + base, 'ok'); return;
          }
          if (action === 'copy-diagnostics') {
            const safe = inrV350Redact({ version: INR_V350_VERSION, schemes: vm.schemes.schemes.map(item => ({ name: item.name, modelFamily: item.modelFamily, appliesTo: item.appliesTo, backend: item.backend, frames: { bindings: item.frames.bindings }, text: { bindings: item.text.bindings } })), logs: vm.logs });
            await navigator.clipboard?.writeText(JSON.stringify(safe, null, 2)); status('脱敏诊断已复制。', 'ok'); return;
          }
          if (action === 'clear-logs') { inrV350LogsCache = []; await inrV350WriteScript(INR_V350_LOGS, []); vm.logs = []; render(); status('日志已清除。', 'ok'); return; }
        } catch (error) { const safe = inrV350SafeError(error); await inrV350Log('error', 'video-settings-action', { action, error: safe }); status(safe, 'error'); console.error('[图文阅读器] 视频设置操作失败', safe); }
      });
    },
  });
  await popup.show();
}

async function inrV350EnsureMvuBridge(attempt = 0) {
  let hasMessage = false;
  try { hasMessage = !!getChatMessages(-1, { include_swipes: true })?.length; } catch (_) {}
  if (!hasMessage) {
    if (attempt < 5) {
      clearTimeout(inrV350MvuRetryTimer);
      inrV350MvuRetryTimer = setTimeout(() => {
        inrV350EnsureMvuBridge(attempt + 1).catch(() => {});
      }, 1500);
    }
    return { ready: false, reason: 'no-message' };
  }
  const bridge = inrFallbackBridge('latest');
  const result = await inrSaveBridge(bridge, 'latest');
  await inrV350Log(result.mvu ? 'info' : 'warn', 'mvu-bridge-ready', result);
  return { ready: result.fallback || result.mvu, ...result };
}

async function inrV350Init() {
  if (inrV350Started) return;
  inrV350Started = true;
  await inrV350EnsureMigrated();
  replaceScriptButtons([
    { name: '图文阅读', visible: true },
    { name: '视频设置', visible: true },
    { name: '生成视频', visible: true },
    { name: '上一页', visible: true },
    { name: '下一页', visible: true },
  ]);
  eventOn(getButtonEvent('图文阅读'), () => inrOpen().catch(error => toastr?.error?.(inrV350SafeError(error))));
  eventOn(getButtonEvent('视频设置'), () => inrOpenVideoSettings().catch(error => toastr?.error?.(inrV350SafeError(error))));
  eventOn(getButtonEvent('生成视频'), () => inrGenerateByMode('').catch(error => { if (!inrIsCancel(error)) toastr?.error?.('生成视频：' + inrV350SafeError(error)); }));
  eventOn(getButtonEvent('上一页'), () => inrRead('previous').catch(error => toastr?.warning?.(inrV350SafeError(error))));
  eventOn(getButtonEvent('下一页'), () => inrRead('next').catch(error => toastr?.warning?.(inrV350SafeError(error))));
  if (typeof tavern_events !== 'undefined' && tavern_events.CHAT_CHANGED) {
    eventOn(tavern_events.CHAT_CHANGED, () => {
      inrV350Migration = null;
      inrV350RefreshCardInjection().catch(error => console.warn('[图文小说阅读器] 角色卡规则重绑失败', inrV350SafeError(error)));
      inrV350EnsureMvuBridge().catch(error => console.warn('[图文小说阅读器] MVU 桥接重绑失败', inrV350SafeError(error)));
      inrV350ScheduleVideoButtons();
    });
  }
  if (typeof tavern_events !== 'undefined' && tavern_events.MESSAGE_SWIPED) {
    eventOn(tavern_events.MESSAGE_SWIPED, () => inrV350ScheduleVideoButtons());
  }
  await inrV350RefreshCardInjection();
  inrV350EnsureMvuBridge().catch(error => console.warn('[图文小说阅读器] MVU 桥接初始化失败', inrV350SafeError(error)));
  inrV350WatchVideoButtons();
  await inrV350Log('info', 'startup', { version: INR_V350_VERSION, helper: typeof getTavernHelperVersion === 'function' ? getTavernHelperVersion() : 'unknown' });
  addEventListener('pagehide', () => {
    clearTimeout(inrV350MountTimer);
    clearTimeout(inrV350MvuRetryTimer);
    inrV350Observer?.disconnect(); inrV350Observer = null;
    inrV350RemoveCardInjection().catch(() => {});
  }, { once: true });
}

setTimeout(() => {
  inrV350Init().catch(error => {
    inrV350Started = false;
    const safe = inrV350SafeError(error);
    console.error('[图文视频小说阅读器 v3.5.5] 初始化失败', safe);
    toastr?.error?.('图文小说阅读器初始化失败：' + safe);
  });
}, 0);

