uiThemes.custom_css:
/* 感谢墨千尾（discord@这对吗/inkfoxxxx）拼好码 */
/* 如CSS中有引用哪位老师忘记标注先致歉辛苦戳DearQS */
/* 隐藏qr感谢twelve.老和qiyigeming两位老师 */
/* ===== 一、全局控制 ===== */

@import url("https://fontsapi.zeoseven.com/875/main/result.css");

:root {
  --rm-deep: #2a3a58;
  --rm-mid: #3d527a;
  --rm-accent: #5878a8;
  --rm-moon: #e0ebff;
  --rm-silver: #b8c8e0;
  --rm-text: #eaf0fa;
  --rm-rain: #7b9cc8;

}

body {
  font-family: "ChillHuoSong_F", "Noto Serif SC", serif;
  font-weight: normal;
}

.drawer-content,
#table_drawer_content,
.options-content {
  background-color: rgba(42, 58, 88, 0.75) !important;
  border: 1px solid rgba(224, 235, 255, 0.3) !important;
  border-radius: 0 !important;
  backdrop-filter: blur(12px) !important;
  -webkit-backdrop-filter: blur(12px) !important;
}

/* ===== 二、顶栏 ===== */
#top-settings-holder {
  background: rgba(42, 58, 88, 0.55) !important;
  border: 1px solid rgba(224, 235, 255, 0.25) !important;
  border-radius: 0 !important;
  box-shadow:
    0 4px 20px rgba(0,0,0,0.4),
    inset 0 0 30px rgba(88,120,168,0.15),
    inset 0 0 0 1px rgba(224,235,255,0.1) !important;
  backdrop-filter: blur(14px) !important;
  -webkit-backdrop-filter: blur(14px) !important;
}

#top-bar {
  border-radius: 0 !important;
  background-color: transparent !important;
  box-shadow: none !important;
  border: none !important;
}

#top-settings-holder .drawer-icon::before {
  font-size: 18px;
  color: transparent !important;
  background: linear-gradient(180deg, #ffffff, #b8c8e0);
  -webkit-background-clip: text;
  background-clip: text;
  filter: drop-shadow(0 0 4px rgba(224,235,255,0.6));
  transition: all 0.4s ease;
}

#top-settings-holder .drawer-icon:hover::before {
  transform: scale(1.15);
  filter: drop-shadow(0 0 8px rgba(224,235,255,0.9));
}

/* ===== 三、底栏 ===== */
#send_form {
  background: rgba(42, 58, 88, 0.55) !important;
  border: 1px solid rgba(224, 235, 255, 0.3) !important;
  border-radius: 0 !important;
  box-shadow:
    0 4px 20px rgba(0,0,0,0.5),
    inset 0 0 20px rgba(88,120,168,0.2),
    inset 0 0 0 1px rgba(224,235,255,0.15) !important;
  padding: 6px !important;
  backdrop-filter: blur(14px) !important;
  -webkit-backdrop-filter: blur(14px) !important;
}

#send_textarea {
  border-radius: 0 !important;
  background-color: transparent !important;
  border-color: transparent !important;
  color: var(--rm-text) !important;
  clip-path: none !important;
}

#send_form [class*="fa-"]::before {
  font-size: 16px;
  color: transparent !important;
  background: linear-gradient(180deg, #ffffff, #b8c8e0);
  -webkit-background-clip: text;
  background-clip: text;
  filter: drop-shadow(0 0 3px rgba(224,235,255,0.6));
  vertical-align: middle;
  transition: all 0.3s ease;
}

#send_form [class*="fa-"]:hover::before {
  transform: scale(1.2);
  filter: drop-shadow(0 0 6px rgba(224,235,255,1));
}

/* ===== 四、聊天区域 ===== */

/* ---1. 聊天区域背景：透明 --- */
#chat {
  background-color: transparent !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
}

/* ---2. 聊天气泡：全宽居中 + 浅色毛玻璃 + 直角 --- */

.mes {
  display: flex !important;
  flex-direction: column !important;
  align-items: center !important;

  padding: 210px 32px 50px 32px !important;
  margin: 50px 0 30px 0 !important;
  max-width: 100% !important;
  width: 100% !important;
  box-sizing: border-box !important;

  background: linear-gradient(145deg,
    rgba(88, 120, 168, 0.22),
    rgba(61, 82, 122, 0.20)) !important;
  backdrop-filter: blur(16px) saturate(140%) !important;
  -webkit-backdrop-filter: blur(16px) saturate(140%) !important;

  border-radius: 0 !important;

  border: 1px solid rgba(224, 235, 255, 0.45) !important;
  box-shadow:
    0 0 0 1px rgba(224, 235, 255, 0.15),
    0 8px 32px rgba(0, 0, 0, 0.45),
    0 16px 48px rgba(42, 58, 88, 0.35),
    inset 0 0 0 1px rgba(255, 255, 255, 0.15),
    inset 0 0 40px rgba(224, 235, 255, 0.08),
    inset 0 1px 0 rgba(255, 255, 255, 0.25),
    inset 0 -1px 0 rgba(0, 0, 0, 0.3) !important;

  position: relative !important;
  overflow: visible !important;

  outline: 1px solid rgba(224, 235, 255, 0.2);
  outline-offset: 6px;
}

/* ===== 气泡四角雨月角标装饰 ===== */

/* 左上角 - 月牙 + 雨滴 */
.mes .mes_block::before {
  content: '☾ ˖°';
  position: absolute;
  top: 14px;
  left: 18px;
  font-size: 14px;
  color: rgba(224, 235, 255, 0.55);
  letter-spacing: 3px;
  text-shadow:
    0 0 8px rgba(224, 235, 255, 0.5),
    0 0 16px rgba(88, 120, 168, 0.3);
  pointer-events: none;
  z-index: 15;
  animation: corner-glow 4s ease-in-out infinite alternate;
}

/* 右上角 - 星辰雨点 */
.mes .mes_block::after {
  content: '°˖ ⋆';
  position: absolute;
  top: 14px;
  right: 18px;
  font-size: 14px;
  color: rgba(224, 235, 255, 0.55);
  letter-spacing: 3px;
  text-shadow:
    0 0 8px rgba(224, 235, 255, 0.5),
    0 0 16px rgba(88, 120, 168, 0.3);
  pointer-events: none;
  z-index: 15;
  animation: corner-glow 4s ease-in-out 1s infinite alternate;
}

/* 左下角  */
.mes .mes_text::before {
  content: '⊹ ࣪ ˖';
  position: absolute;
  bottom: 28px;
  left: 18px;
  font-size: 12px;
  color: rgba(224, 235, 255, 0.4);
  letter-spacing: 4px;
  text-shadow: 0 0 6px rgba(224, 235, 255, 0.4);
  pointer-events: none;
  z-index: 15;
  animation: corner-glow 5s ease-in-out 2s infinite alternate;
}

/* 右下角 -*/
.mes .mes_text::after {
  content: '˖ ࣪ ⊹';
  position: absolute;
  bottom: 28px;
  right: 18px;
  font-size: 12px;
  color: rgba(224, 235, 255, 0.4);
  letter-spacing: 4px;
  text-shadow: 0 0 6px rgba(224, 235, 255, 0.4);
  pointer-events: none;
  z-index: 15;
  animation: corner-glow 5s ease-in-out 3s infinite alternate;
}

@keyframes corner-glow {
  0% {
    opacity: 0.4;
    text-shadow: 0 0 6px rgba(224, 235, 255, 0.3);
  }
  50% {
    opacity: 0.9;
    text-shadow:
      0 0 12px rgba(224, 235, 255, 0.7),
      0 0 24px rgba(88, 120, 168, 0.4);
  }
  100% {
    opacity: 0.5;
    text-shadow: 0 0 8px rgba(224, 235, 255, 0.4);
  }
}

/* ===== 气泡左右 ===== */
.mes::before {
  content: '';
  position: absolute !important;
  top: 14px;
  left: 14px;
  right: 14px;
  height: 140px;
  background-image: url('https://iili.io/B49hNBs.gif');
  background-size: cover;
  background-position: center;
  background-repeat: no-repeat;
  border-radius: 0;
  border: 1px solid rgba(224, 235, 255, 0.35);
  box-shadow:
    inset 0 0 30px rgba(42, 58, 88, 0.5),
    0 2px 8px rgba(0, 0, 0, 0.4),
    0 0 0 1px rgba(255, 255, 255, 0.1);
  filter: brightness(0.95) contrast(1.05);
  z-index: 1;
  pointer-events: none;
}

/* 气泡底部 */
.mes::after {
  content: '☾ ･ ⋆ ˖ ࣪ ⊹ ･ ☽';
  position: absolute;
  bottom: 14px;
  left: 50%;
  transform: translateX(-50%);
  font-size: 10px;
  color: rgba(224, 235, 255, 0.45);
  letter-spacing: 5px;
  pointer-events: none;
  z-index: 2;
  text-shadow: 0 0 6px rgba(224, 235, 255, 0.4);
  animation: moon-phase-drift 8s ease-in-out infinite;
}

@keyframes moon-phase-drift {
  0%, 100% { letter-spacing: 5px; opacity: 0.45; }
  50% { letter-spacing: 8px; opacity: 0.7; }
}

/* ===== 头像 ===== */
.mes .mesAvatarWrapper {
  position: absolute !important;
  top: 34px !important;
  left: 50% !important;
  transform: translateX(-50%) !important;
  display: flex !important;
  flex-direction: column !important;
  align-items: center !important;
  gap: 6px !important;
  z-index: 10 !important;
  background: transparent !important;
  width: auto !important;
  height: auto !important;
}

/* 头像本体 */
.mes .avatar {
  width: 100px !important;
  height: 100px !important;
  min-width: 100px !important;
  min-height: 100px !important;
  max-width: 100px !important;
  max-height: 100px !important;
  flex: 0 0 100px !important;
  aspect-ratio: 1 / 1 !important;
  border-radius: 50% !important;
  overflow: visible !important;
  position: relative !important;
  margin: 0 !important;
  padding: 0 !important;
}

.mes .avatar img {
  width: 100% !important;
  height: 100% !important;
  aspect-ratio: 1 / 1 !important;
  border-radius: 50% !important;
  object-fit: cover !important;
  border: 2px solid rgba(224, 235, 255, 0.7) !important;
  box-shadow:
    0 0 20px rgba(224, 235, 255, 0.5),
    0 4px 12px rgba(0, 0, 0, 0.6) !important;
  position: relative;
  z-index: 2;
  display: block;
}

/* 头像*/
.mes .avatar .img_avatar {
  position: relative !important;
}

.mes .avatar::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  width: 100px;
  height: 100px;
  border-radius: 50%;
  background-image: url('https://iili.io/BryqDf2.gif');
  background-size: cover;
  background-position: center;
  background-repeat: no-repeat;
  opacity: 0.3;
  z-index: 3;
  pointer-events: none;
}

/* ---3. 月光流动灯 --- （改用 .mesAvatarWrapper::before 和 ::after 替代原 .avatar::before/::after） */
.mes .mesAvatarWrapper::before {
  content: '';
  position: absolute;
  top: -10px;
  left: 50%;
  transform: translateX(-50%);
  width: 120px;
  height: 120px;
  border-radius: 50%;
  background: conic-gradient(
    from 0deg,
    transparent 0%,
    rgba(224, 235, 255, 0.2) 15%,
    rgba(224, 235, 255, 0.9) 25%,
    rgba(255, 255, 255, 1) 35%,
    rgba(224, 235, 255, 0.9) 45%,
    rgba(88, 120, 168, 0.4) 60%,
    transparent 75%,
    transparent 100%
  );
  animation: moonlight-rotate 6s linear infinite;
  filter: blur(3px);
  z-index: 1;
  pointer-events: none;
}

.mes .mesAvatarWrapper::after {
  content: '';
  position: absolute;
  top: -4px;
  left: 50%;
  transform: translateX(-50%);
  width: 108px;
  height: 108px;
  border-radius: 50%;
  border: 1px solid rgba(224, 235, 255, 0.5);
  box-shadow:
    0 0 15px rgba(224, 235, 255, 0.7),
    0 0 30px rgba(224, 235, 255, 0.4),
    inset 0 0 10px rgba(224, 235, 255, 0.3);
  animation: moon-pulse 3s ease-in-out infinite;
  z-index: 1;
  pointer-events: none;
}

@keyframes moonlight-rotate {
  from { transform: translateX(-50%) rotate(0deg); }
  to   { transform: translateX(-50%) rotate(360deg); }
}

@keyframes moon-pulse {
  0%, 100% {
    opacity: 0.75;
    box-shadow:
      0 0 15px rgba(224, 235, 255, 0.6),
      0 0 30px rgba(224, 235, 255, 0.3),
      inset 0 0 10px rgba(224, 235, 255, 0.3);
  }
  50% {
    opacity: 1;
    box-shadow:
      0 0 25px rgba(224, 235, 255, 0.9),
      0 0 50px rgba(224, 235, 255, 0.5),
      inset 0 0 15px rgba(224, 235, 255, 0.4);
  }
}

/* 防误触 */
.mesAvatarWrapper .avatar { pointer-events: none !important; }
.mes .avatar img { pointer-events: auto !important; }

/* ---4. mes_block --- */
.mes .mes_block {
  width: 100% !important;
  margin-top: 10px !important;
  padding: 10px 0 0 0 !important;
  position: relative;
  z-index: 5;
  background: transparent !important;
  border: none !important;
}

/* 名字 */
.mes .name_text {
  display: block !important;
  text-align: center !important;
  font-size: 1.25em !important;
  font-weight: 600 !important;
  font-family: "ChillHuoSong_F", "Noto Serif SC", serif !important;
  color: #ffffff !important;
  letter-spacing: 5px !important;
  text-shadow:
    0 0 10px rgba(224, 235, 255, 0.8),
    0 2px 4px rgba(0, 0, 0, 0.5) !important;
  padding: 8px 0 !important;
  margin-bottom: 10px !important;
  border-top: 1px solid rgba(224, 235, 255, 0.3) !important;
  border-bottom: 1px solid rgba(224, 235, 255, 0.3) !important;
  position: relative;
}

.mes .name_text::before,
.mes .name_text::after {
  content: '';
  margin: 0 14px;
  color: rgba(224, 235, 255, 0.7);
  font-size: 0.85em;
}

/* 三元素 */
.mes .mesIDDisplay,
.mes .tokenCounterDisplay,
.mes .mes_timer {
  color: var(--rm-silver) !important;
  font-size: 0.75em !important;
  text-shadow: 0 0 4px rgba(0,0,0,0.6) !important;
  background: transparent !important;
}

.mes .timestamp {
  color: var(--rm-silver) !important;
  font-size: 0.78em !important;
  font-style: italic !important;
  letter-spacing: 1px !important;
}

/* ===== 正文 ===== */
.mes .mes_text {
  color: var(--rm-text) !important;
  font-family: "ChillHuoSong_F", "Noto Serif SC", serif !important;
  line-height: 1.6 !important;
  padding: 12px 8px !important;
  width: 100%;
  text-align: justify;
  text-shadow: 0 1px 2px rgba(0, 0, 0, 0.3);
  position: relative;
}

/* ===== 文字样式精细调整 ===== */

/* ** 加粗 **  */
.mes_text strong {
  color: #ffffff !important;
  font-weight: 700 !important;
  font-family: "ChillHuoSong_F", "Noto Serif SC", serif !important;
  text-shadow: 0 0 8px rgba(224, 235, 255, 0.8) !important;
  border-bottom: 1px dashed rgba(224, 235, 255, 0.6);
  padding: 0 2px;
}

/* * 斜体 * — 雨中呢喃，手写感 */
.mes_text em {
  color: var(--rm-silver) !important;
  font-style: italic !important;
  font-family: "ChillHuoSong_F", "LXGW WenKai", "楷体", KaiTi, serif !important;
  font-size: 0.95em !important;
  letter-spacing: 1.5px;
  opacity: 0.92;
}

/* "" 引号对话 — 清澈月光字 */
.mes_text q {
  color: #ffffff !important;
  font-family: "ChillHuoSong_F", "Noto Serif SC", serif !important;
  font-size: 1.02em !important;
  font-weight: 500 !important;
  background: linear-gradient(135deg,
    rgba(88, 120, 168, 0.35),
    rgba(224, 235, 255, 0.12)) !important;
  padding: 3px 12px;
  border-left: 2px solid rgba(224, 235, 255, 0.7);
  border-radius: 0;
  font-style: normal !important;
  margin: 0 3px;
  text-shadow:
    0 0 6px rgba(224, 235, 255, 0.6),
    0 1px 2px rgba(0, 0, 0, 0.4);
  box-shadow: inset 0 0 12px rgba(224, 235, 255, 0.08);
  display: inline;
  position: relative;
line-height: 1.8 !important; 
}

/* q 标签 */
.mes_text q::before {
  content: '「';
  color: rgba(224, 235, 255, 0.7);
  font-size: 0.9em;
  margin-right: 2px;
}
.mes_text q::after {
  content: '」';
  color: rgba(224, 235, 255, 0.7);
  font-size: 0.9em;
  margin-left: 2px;
}

/* > 引用块 — 深色窗牖·旧信笺 */
.mes_text blockquote {
  background: linear-gradient(135deg,
    rgba(42, 58, 88, 0.55),
    rgba(61, 82, 122, 0.35)) !important;
  border-left: 3px solid var(--rm-moon) !important;
  border-radius: 0 !important;
  padding: 14px 20px 14px 24px !important;
  margin: 18px 0 !important;
  color: var(--rm-silver) !important;
  font-family: "ChillHuoSong_F", "LXGW WenKai", "楷体", KaiTi, serif !important;
  font-style: italic;
  font-size: 0.92em !important;
  line-height: 1.5 !important;
  letter-spacing: 1px;
  position: relative;
  box-shadow:
    0 2px 12px rgba(0, 0, 0, 0.3),
    inset 0 0 25px rgba(88, 120, 168, 0.12);
  border-right: 1px solid rgba(224, 235, 255, 0.15);
  border-top: 1px solid rgba(224, 235, 255, 0.1);
  border-bottom: 1px solid rgba(224, 235, 255, 0.1);
}

.mes_text blockquote::before {
  content: '☾';
  position: absolute;
  left: -12px;
  top: 50%;
  transform: translateY(-50%);
  background: var(--rm-deep);
  color: var(--rm-moon);
  width: 22px;
  height: 22px;
  line-height: 22px;
  text-align: center;
  border-radius: 50%;
  font-size: 11px;
  border: 1px solid rgba(224, 235, 255, 0.5);
  box-shadow: 0 0 10px rgba(224, 235, 255, 0.5);
}

/* 引用块 */
.mes_text blockquote::after {
  content: '𝑅𝑎𝑖𝑛';
  position: absolute;
  right: 10px;
  bottom: 6px;
  font-size: 9px;
  color: rgba(224, 235, 255, 0.25);
  font-family: "ChillHuoSong_F", serif;
  font-style: italic;
  letter-spacing: 3px;
}

:not(pre) > code {
  background: rgba(42, 58, 88, 0.7) !important;
  color: var(--rm-moon) !important;
  border: 1px solid rgba(224, 235, 255, 0.35);
  border-radius: 0;
  padding: 2px 7px;
  font-family: "Fira Code", "Consolas", monospace !important;
}

pre {
  background: rgba(42, 58, 88, 0.7) !important;
  border: 1px solid rgba(224, 235, 255, 0.3) !important;
  border-left: 3px solid var(--rm-moon) !important;
  border-radius: 0 !important;
  padding: 14px !important;
  box-shadow:
    0 4px 16px rgba(0, 0, 0, 0.4),
    inset 0 0 0 1px rgba(255, 255, 255, 0.08);
}

hr {
  border: none !important;
  height: 1px;
  background: linear-gradient(90deg,
    transparent 0%,
    rgba(224,235,255,0.2) 15%,
    rgba(224,235,255,0.6) 50%,
    rgba(224,235,255,0.2) 85%,
    transparent 100%);
  margin: 24px 0 !important;
  position: relative;
}

/* hr 中央月亮 */
hr::after {
  content: '☽';
  position: absolute;
  left: 50%;
  top: 50%;
  transform: translate(-50%, -50%);
  background: rgba(42, 58, 88, 0.9);
  color: rgba(224, 235, 255, 0.6);
  padding: 0 10px;
  font-size: 12px;
}

.mes .mes_buttons {
  color: var(--rm-silver) !important;
  opacity: 0.7;
  transition: opacity 0.3s ease;
}
.mes:hover .mes_buttons { opacity: 1; }

.mes.last_mes .mesAvatarWrapper { padding-bottom: 0 !important; }

/* ===== 五、滚动条 + 滑动条 ===== */
::-webkit-scrollbar {
  width: 8px;
  height: 8px;
  background-color: transparent;
}
::-webkit-scrollbar-track { background-color: transparent; }
::-webkit-scrollbar-thumb {
  background-image: linear-gradient(to bottom, #e0ebff, #5878a8);
  border-radius: 0;
  box-shadow: 0 0 6px rgba(224, 235, 255, 0.5);
}

input[type="range"] {
  -webkit-appearance: none;
  appearance: none;
  width: 100%;
  background: transparent !important;
  cursor: pointer;
}
input[type="range"]::-webkit-slider-runnable-track {
  height: 4px;
  background: linear-gradient(to right, #5878a8, #e0ebff);
  border-radius: 0;
  border: 1px solid rgba(224, 235, 255, 0.3);
}
input[type="range"]::-webkit-slider-thumb {
  -webkit-appearance: none;
  margin-top: -7px;
  height: 16px;
  width: 16px;
  border-radius: 50%;
  background: radial-gradient(circle at 35% 35%, #ffffff, #e0ebff 60%, #5878a8);
  border: 1px solid rgba(224, 235, 255, 0.8);
  box-shadow: 0 0 10px rgba(224, 235, 255, 0.8);
  transition: transform 0.2s ease;
}
input[type="range"]:hover::-webkit-slider-thumb { transform: scale(1.2); }

input[type="range"]::-moz-range-track {
  height: 4px;
  background: linear-gradient(to right, #5878a8, #e0ebff);
}
input[type="range"]::-moz-range-thumb {
  height: 16px;
  width: 16px;
  border-radius: 50%;
  background: radial-gradient(circle at 35% 35%, #ffffff, #e0ebff 60%, #5878a8);
  border: 1px solid rgba(224, 235, 255, 0.8);
}

/* ===== 六、输入框提示文字（去掉斜体 + 缩小字体） ===== */
#nonQRFormItems { position: relative; }

#send_textarea::placeholder {
  color: transparent !important;
  text-shadow: none !important;
}

#nonQRFormItems:has(#send_textarea:placeholder-shown)::before {
  content: "";
  color: rgba(224, 235, 255, 0.6);
  position: absolute;
  left: 50%;
  top: 50%;
  transform: translate(-50%, -50%);
  font-style: normal;
  font-size: 0.72em;
  font-family: "ChillHuoSong_F", "Noto Serif SC", serif;
  letter-spacing: 2px;
  pointer-events: none;
  z-index: 10;
  white-space: nowrap;
  max-width: calc(100% - 30px);
  overflow: hidden;
  text-overflow: ellipsis;
}

/* ===== 七、正则+脚本易读+防误触 ===== */
#saved_regex_scripts,
#saved_scoped_scripts,
#saved_preset_scripts,
#global-script-list,
#character-script-list {
  margin-right: 80px !important;
}

.regex-script-label.flex-container,
.flex-container .script-item {
  flex-wrap: wrap !important;
  padding: 6px 12px;
  border-radius: 0;
  margin-bottom: 6px;
  background: rgba(42, 58, 88, 0.6);
  border: 1px solid rgba(224, 235, 255, 0.3);
}

.regex-script-label.flex-container .regex_script_name,
.script-item .script-item-name {
  flex-basis: 100%;
  white-space: normal;
  overflow: visible;
  text-overflow: clip;
  word-break: break-word;
  font-weight: bold;
  font-size: 1.05em;
  color: var(--rm-moon);
}

.regex-script-label.flex-container > .flex-container.flexnowrap,
.script-item .script-item-control {
  width: 100%;
  justify-content: flex-start;
}

/* ===== 八、"加载更多消息"美化 ===== */
#show_more_messages {
  font-size: 0 !important;
  color: transparent !important;
  display: block;
  padding: 10px 28px;
  margin: 20px auto;
  width: fit-content;
  background: rgba(88, 120, 168, 0.25) !important;
  backdrop-filter: blur(10px) !important;
  -webkit-backdrop-filter: blur(10px) !important;
  border: 1px solid rgba(224, 235, 255, 0.45) !important;
  border-radius: 0 !important;
  box-shadow:
    0 4px 14px rgba(0, 0, 0, 0.4),
    inset 0 0 20px rgba(224, 235, 255, 0.1),
    inset 0 0 0 1px rgba(255, 255, 255, 0.15);
  cursor: pointer;
  transition: all 0.3s ease;
  outline: 1px solid rgba(224, 235, 255, 0.2);
  outline-offset: 3px;
}

#show_more_messages::before {
  content: "☾ 要陪你上岸 ☽";
  font-size: 13px !important;
  color: #ffffff !important;
  letter-spacing: 3px;
  text-shadow: 0 0 8px rgba(224, 235, 255, 0.7);
}

#show_more_messages:hover {
  background: rgba(88, 120, 168, 0.4) !important;
  border-color: rgba(224, 235, 255, 0.7) !important;
  box-shadow:
    0 6px 20px rgba(0, 0, 0, 0.5),
    0 0 30px rgba(224, 235, 255, 0.3),
    inset 0 0 25px rgba(224, 235, 255, 0.15);
}

/* 九、思维链美化  */

/* 思维链整体容器 */
.mes_reasoning_details {
  margin: 12px 0 !important;
  position: relative;
}

/* summary  */
.mes_reasoning_summary {
  list-style: none;
  cursor: pointer;
  display: flex !important;
  align-items: center;
  padding: 0 !important;
}

/* header 背景框 */
.mes_reasoning_header {
  background: linear-gradient(135deg,
    rgba(42, 58, 88, 0.65),
    rgba(88, 120, 168, 0.35)) !important;
  backdrop-filter: blur(12px) !important;
  -webkit-backdrop-filter: blur(12px) !important;
  border: 1px solid rgba(224, 235, 255, 0.4) !important;
  border-radius: 0 !important;
  padding: 10px 20px !important;
  box-shadow:
    0 3px 12px rgba(0, 0, 0, 0.4),
    inset 0 0 0 1px rgba(255, 255, 255, 0.12),
    inset 0 1px 0 rgba(224, 235, 255, 0.2);
  transition: all 0.4s ease;
  position: relative;
  overflow: hidden;
  width: 100%;
}

/* header  */
.mes_reasoning_header::before {
  content: '';
  position: absolute;
  top: 0;
  left: -100%;
  width: 100%;
  height: 100%;
  background: linear-gradient(90deg,
    transparent,
    rgba(224, 235, 255, 0.08),
    rgba(224, 235, 255, 0.15),
    rgba(224, 235, 255, 0.08),
    transparent);
  animation: thinking-sweep 4s ease-in-out infinite;
  pointer-events: none;
}

@keyframes thinking-sweep {
  0% { left: -100%; }
  50% { left: 100%; }
  100% { left: 100%; }
}

/* header hover */
.mes_reasoning_summary:hover .mes_reasoning_header {
  border-color: rgba(224, 235, 255, 0.65) !important;
  box-shadow:
    0 3px 12px rgba(0, 0, 0, 0.4),
    0 0 20px rgba(224, 235, 255, 0.3),
    inset 0 0 0 1px rgba(255, 255, 255, 0.2),
    inset 0 0 30px rgba(224, 235, 255, 0.08);
}

/* 标题文字替换 */
.mes_reasoning_header_title {
  font-size: 0 !important;
  display: flex !important;
  align-items: center !important;
  gap: 8px !important;
}
.mes_reasoning_header_title::before {
  content: "☾ 醒时海 ☽";
  font-size: 13px;
  color: #ffffff;
  font-family: "ChillHuoSong_F", "Noto Serif SC", serif;
  font-weight: 600;
  letter-spacing: 3px;
  text-shadow:
    0 0 8px rgba(224, 235, 255, 0.7),
    0 1px 3px rgba(0, 0, 0, 0.4);
}

/* 时间/tokens 文字 */
.mes_reasoning_header_metadata {
  color: rgba(184, 200, 224, 0.7) !important;
  font-size: 11px !important;
  font-style: italic !important;
}

/* 箭头替换为月亮符号 + 旋转 */
.mes_reasoning_arrow {
  font-size: 0 !important;
  position: relative;
}
.mes_reasoning_arrow::before {
  content: '🌙';
  font-size: 14px;
  display: inline-block;
  transition: transform 0.5s cubic-bezier(0.34, 1.56, 0.64, 1);
  filter: drop-shadow(0 0 4px rgba(224, 235, 255, 0.6));
}
details[open] .mes_reasoning_arrow::before {
  transform: rotate(360deg) scale(1.15);
  filter: drop-shadow(0 0 8px rgba(224, 235, 255, 0.9));
}

/* 思维链内容区 */
.mes_reasoning {
  margin-top: 0 !important;
  padding: 18px 22px !important;
  background: linear-gradient(180deg,
    rgba(42, 58, 88, 0.5),
    rgba(42, 58, 88, 0.35)) !important;
  backdrop-filter: blur(10px) !important;
  -webkit-backdrop-filter: blur(10px) !important;
  border: 1px solid rgba(224, 235, 255, 0.2) !important;
  border-top: none !important;
  border-left: 3px solid rgba(224, 235, 255, 0.5) !important;
  border-radius: 0 !important;
  color: var(--rm-silver) !important;
  font-family: "ChillHuoSong_F", "LXGW WenKai", "楷体", KaiTi, "Noto Serif SC", serif !important;
  font-style: italic;
  font-size: 12.5px !important;
  line-height: 1.85 !important;
  letter-spacing: 0.5px;
  box-shadow:
    inset 0 0 25px rgba(88, 120, 168, 0.12),
    0 4px 16px rgba(0, 0, 0, 0.3);
  position: relative;
  overflow: hidden;
  animation: reasoning-fade-in 0.5s ease-out;
}

@keyframes reasoning-fade-in {
  from {
    opacity: 0;
    max-height: 0;
    padding-top: 0;
    padding-bottom: 0;
  }
  to {
    opacity: 1;
    max-height: 2000px;
    padding-top: 18px;
    padding-bottom: 18px;
  }
}

/* 思维链内容区左上角装饰 */
.mes_reasoning::before {
  content: '⊹ ˖ ࣪ 思绪如雨 ˖ ⊹';
  position: absolute;
  top: 6px;
  left: 14px;
  font-size: 9px;
  color: rgba(224, 235, 255, 0.3);
  letter-spacing: 2px;
  font-style: italic;
  pointer-events: none;
}

/* 思维链内容 */
.mes_reasoning::after {
  content: '☾ ⋆ ˖';
  position: absolute;
  bottom: 6px;
  right: 14px;
  font-size: 10px;
  color: rgba(224, 235, 255, 0.25);
  letter-spacing: 3px;
  pointer-events: none;
}

/* 思维链 */
.mes_reasoning {
  background-image:
    repeating-linear-gradient(
      180deg,
      transparent,
      transparent 24px,
      rgba(224, 235, 255, 0.04) 24px,
      rgba(224, 235, 255, 0.04) 25px
    ) !important;
  background-color: rgba(42, 58, 88, 0.42) !important;
}

/* ===== 十、收藏栏左右滑动查看角色 ===== */
.hotswap.avatars_inline {
  display: flex;
  flex-wrap: nowrap;
  overflow-x: auto;
  padding-right: 15px;
}
.hotswap.avatars_inline::-webkit-scrollbar { display: none; }
.hotswap.avatars_inline { scrollbar-width: none; }
#chat::-webkit-scrollbar {
  display: none;  /* 针对 Chrome/Safari/Edge */
}
#chat {
  -ms-overflow-style: none;  /* 针对 IE/Edge 旧版 */
  scrollbar-width: none;     /* 针对 Firefox */
}
/* --- 默认隐藏 QR 按钮容器，并设置平滑过渡 --- */
.qr--buttons {
  opacity: 0;
  visibility: hidden;
  max-height: 0;
  transform: translateY(20px);
  pointer-events: none;
  transition:
    opacity 0.3s ease-in-out,
    visibility 0.3s ease-in-out,
    max-height 0.5s ease,
    transform 0.5s ease;
}

/* --- 输入框获得焦点时显示 QR 区域 --- */
#send_form:focus-within .qr--buttons {
  opacity: 1;
  visibility: visible;
  max-height: 120px;
  transform: translateY(0);
  pointer-events: auto;
}

/* --- 新增：修复空白弹窗，仅隐藏空白背景，不影响点击 --- */
#qr--bar {
  opacity: 0;
  visibility: hidden;
  max-height: 0;
  pointer-events: none;
  transition:
    opacity 0.3s ease-in-out,
    visibility 0.3s ease-in-out,
    max-height 0.3s ease;
}

/* --- 当输入框聚焦或激活时才显示 QR bar 内容 --- */
#send_form:focus-within #qr--bar,
.qr--buttons.active #qr--bar {
  opacity: 1;
  visibility: visible;
  max-height: 200px;
  pointer-events: auto;
}
/* 以上隐藏qr感谢twelve.老和qiyigeming两位老师 */

