:root {
  --tf-ink: #0d1517;
  --tf-panel: rgba(16, 25, 27, .97);
  --tf-panel-soft: rgba(19, 30, 32, .84);
  --tf-panel-raised: rgba(24, 36, 37, .94);
  --tf-paper: #e5e5d9;
  --tf-paper-dim: #b6c0b9;
  --tf-muted: #87958f;
  --tf-line: rgba(185, 201, 186, .18);
  --tf-line-strong: rgba(185, 201, 186, .34);
  --tf-red: #bd554a;
  --tf-red-soft: rgba(189, 85, 74, .15);
  --tf-amber: #d1ad62;
  --tf-amber-soft: rgba(209, 173, 98, .13);
  --tf-green: #8ba69a;
  --tf-font-ui: "Noto Sans SC", "Source Han Sans SC", "Microsoft YaHei", sans-serif;
  --tf-font-text: "Noto Serif SC", "Source Han Serif SC", "Songti SC", "STSong", serif;
  --SmartThemeBodyColor: var(--tf-paper) !important;
  --SmartThemeEmColor: var(--tf-amber) !important;
  --SmartThemeQuoteColor: #c7d5cb !important;
  --blurStrength: 10px !important;
  --shadowWidth: 2px !important;
}

/* 02 / 背景：保留酒馆原壁纸，只压低亮度并叠加极轻的勘验网格 */
html, body, #sheld, #chat, #chat-wrapper, #form_sheld,
#send_form, #leftSendForm, #rightSendForm,
#chat .mes, #chat .mes_block, #chat .mes_text,
#chat .mes_reasoning, #chat .mes_reasoning_details {
  color: var(--tf-paper) !important;
  background-color: transparent !important;
  box-shadow: none;
}
body {
  --SmartThemeBlurTintColor: rgba(9, 15, 17, .88);
  --SmartThemeChatTintColor: rgba(7, 12, 13, .16);
  scrollbar-color: rgba(139, 166, 154, .55) rgba(9, 15, 17, .42);
}
#bg1::after, #bg_custom::after {
  content: "" !important;
  position: absolute !important;
  inset: 0 !important;
  pointer-events: none !important;
  background:
    linear-gradient(180deg, rgba(6, 12, 13, .18), rgba(6, 12, 13, .38)),
    repeating-linear-gradient(0deg, rgba(210, 223, 210, .018) 0 1px, transparent 1px 4px) !important;
}
#chat {
  border: 0 !important;
  padding: 1.1rem clamp(.6rem, 2vw, 1.5rem) 1.8rem !important;
}
#chat .mes, #chat .mesAvatarWrapper, #chat .mes_block { overflow: visible !important; }
#chat .mes {
  position: relative !important;
  display: flex !important;
  flex-direction: column !important;
  align-items: stretch !important;
  width: min(100%, 1040px) !important;
  max-width: 1040px !important;
  margin: 0 auto 1.6rem !important;
  padding: 0 0 1.1rem !important;
  border: 0 !important;
  border-bottom: 1px solid var(--tf-line) !important;
  background: transparent !important;
}
#chat .mes::after {
  content: "" !important;
  position: absolute !important;
  right: 0 !important;
  bottom: -2px !important;
  width: 54px !important;
  height: 3px !important;
  background: linear-gradient(90deg, transparent, rgba(189, 85, 74, .72)) !important;
  pointer-events: none !important;
}

/* 03 / 头像：像证件照夹入卷宗；不隐藏角色头像，也不额外生成大面积光效 */
#chat .mes .mesAvatarWrapper {
  display: flex !important;
  flex-direction: row !important;
  align-items: center !important;
  gap: .8rem !important;
  align-self: flex-start !important;
  width: fit-content !important;
  max-width: 100% !important;
  margin: .15rem 0 .55rem clamp(.15rem, 1vw, .7rem) !important;
  padding: 0 !important;
  position: relative !important;
  z-index: 5 !important;
  background: transparent !important;
}
#chat .mes[is_user="true"] .mesAvatarWrapper {
  align-self: flex-end !important;
  flex-direction: row-reverse !important;
  margin: .15rem clamp(.15rem, 1vw, .7rem) .55rem 0 !important;
}
#chat .mes .avatar {
  position: relative !important;
  isolation: isolate !important;
  width: 72px !important;
  height: 78px !important;
  flex: 0 0 72px !important;
  padding: 3px !important;
  box-sizing: border-box !important;
  overflow: visible !important;
  border: 1px solid rgba(185, 201, 186, .42) !important;
  border-radius: 2px !important;
  background: rgba(13, 21, 23, .9) !important;
  box-shadow: 3px 3px 0 rgba(189, 85, 74, .18) !important;
}
#chat .mes .avatar::before {
  content: "" !important;
  position: absolute !important;
  inset: -5px !important;
  z-index: -1 !important;
  border: 1px solid rgba(185, 201, 186, .12) !important;
  border-radius: 1px !important;
  background: transparent !important;
  pointer-events: none !important;
}
#chat .mes .avatar::after {
  content: "" !important;
  position: absolute !important;
  top: -4px !important;
  right: -4px !important;
  width: 12px !important;
  height: 12px !important;
  border-top: 2px solid var(--tf-amber) !important;
  border-right: 2px solid var(--tf-amber) !important;
  opacity: .8 !important;
  pointer-events: none !important;
}
#chat .mes .avatar img {
  width: 100% !important;
  height: 100% !important;
  object-fit: cover !important;
  border-radius: 0 !important;
