  background: linear-gradient(90deg, rgba(16, 25, 27, .20), rgba(16, 25, 27, .02) 72%) !important;
  box-shadow: none !important;
}
#chat .mes .mes_block::before {
  content: "" !important;
  position: absolute !important;
  top: 0 !important;
  left: -2px !important;
  width: 3px !important;
  height: 27px !important;
  background: var(--tf-red) !important;
  pointer-events: none !important;
}
#chat .mes[is_user="true"] .mes_block {
  border-left-color: transparent !important;
  border-right: 1px solid rgba(209, 173, 98, .38) !important;
