#chat .mes[is_user="true"] .mes_block::before {
  left: auto !important;
  right: -2px !important;
  background: var(--tf-amber) !important;
}
#chat .mes .mes_text,
#chat .mes .mes_reasoning,
#chat .mes .mes_reasoning_details,
#chat .mes .mes_buttons,
#chat .mes .ch_name { position: relative !important; z-index: 3 !important; }
#chat .mes .mes_text {
