  border-left: 2px solid var(--tf-red) !important;
  border-radius: 0 !important;
  color: #d5d9cf !important;
  background: linear-gradient(90deg, rgba(189, 85, 74, .10), rgba(189, 85, 74, .015)) !important;
}
#chat .mes .mes_text blockquote p { margin-bottom: .35em !important; }
#chat .mes .mes_text hr {
