/* 10 / 加载页：分别处理真正的 #preloader 遮罩与 #loader 品牌加载层。
   只美化可见状态，不强制 display，避免覆盖酒馆的加载结束逻辑。 */
#preloader {
  background:
    radial-gradient(ellipse at 50% 48%, rgba(61,88,75,.22), transparent 34%),
    radial-gradient(ellipse at 50% 50%, rgba(9,15,17,.14), rgba(4,8,9,.93) 76%),
    linear-gradient(145deg, #10191b 0%, #080e10 56%, #111719 100%) !important;
  color: var(--tf-paper) !important;
  -webkit-backdrop-filter: none !important;
  backdrop-filter: none !important;
}
#preloader::before {
  content: "" !important;
  position: absolute !important;
  inset: 0 !important;
  z-index: 1 !important;
  display: block !important;
  pointer-events: none !important;
  background:
    linear-gradient(90deg, transparent calc(50% - 1px), rgba(185,201,186,.08) 50%, transparent calc(50% + 1px)) center / 100% 100% no-repeat,
    linear-gradient(0deg, transparent calc(50% - 1px), rgba(185,201,186,.08) 50%, transparent calc(50% + 1px)) center / 100% 100% no-repeat,
    radial-gradient(circle at center, transparent 0 72px, rgba(185,201,186,.27) 73px 74px, transparent 75px),
    radial-gradient(circle at center, transparent 0 101px, rgba(185,201,186,.12) 102px 103px, transparent 104px),
    radial-gradient(circle at center, transparent 0 126px, rgba(189,85,74,.12) 127px 128px, transparent 129px),
    var(--tf-ico-seal) center / 164px 164px no-repeat !important;
  opacity: .94 !important;
  animation: tf-preloader-pulse 3.4s ease-in-out infinite !important;
}
#preloader::after {
  content: "TRACE FILE 07   /   SYSTEM INITIALIZING" !important;
  position: absolute !important;
  z-index: 2 !important;
  left: 50% !important;
  top: calc(50% + 153px) !important;
  transform: translateX(-50%) !important;
  width: max-content !important;
  max-width: calc(100vw - 34px) !important;
  color: rgba(199,213,203,.70) !important;
  font: 700 9px/1.6 ui-monospace, SFMono-Regular, Consolas, monospace !important;
  letter-spacing: .22em !important;
  text-align: center !important;
  white-space: normal !important;
  pointer-events: none !important;
}
#loader.splash-screen,
#loader:not(.splash-screen) {
  position: fixed !important;
  inset: 0 !important;
  width: 100vw !important;
  width: 100dvw !important;
  height: 100vh !important;
  height: 100dvh !important;
  min-height: 100vh !important;
  overflow: hidden !important;
  isolation: isolate !important;
  gap: 0 !important;
  padding: 0 !important;
  background:
    radial-gradient(ellipse at 50% 43%, rgba(63,91,76,.24), transparent 35%),
    radial-gradient(ellipse at 80% 20%, rgba(189,85,74,.065), transparent 32%),
    linear-gradient(145deg, #10191b 0%, #080e10 55%, #111719 100%) !important;
  color: var(--tf-paper) !important;
  -webkit-backdrop-filter: none !important;
  backdrop-filter: none !important;
}
#loader.splash-screen .splash-logo,
#loader:not(.splash-screen) .splash-logo,
#loader.splash-screen #load-spinner,
#loader:not(.splash-screen) #load-spinner {
  display: none !important;
  visibility: hidden !important;
  opacity: 0 !important;
}
#loader.splash-screen::before,
#loader:not(.splash-screen)::before {
  content: "" !important;
  position: absolute !important;
  inset: 0 !important;
  z-index: 1 !important;
  display: block !important;
  pointer-events: none !important;
  background:
    linear-gradient(90deg, transparent calc(50% - 1px), rgba(185,201,186,.06) 50%, transparent calc(50% + 1px)) center / 100% 100% no-repeat,
    linear-gradient(0deg, transparent calc(50% - 1px), rgba(185,201,186,.06) 50%, transparent calc(50% + 1px)) center / 100% 100% no-repeat,
    radial-gradient(circle at center, transparent 0 72px, rgba(185,201,186,.25) 73px 74px, transparent 75px),
    radial-gradient(circle at center, transparent 0 101px, rgba(185,201,186,.14) 102px 103px, transparent 104px),
    radial-gradient(circle at center, transparent 0 126px, rgba(189,85,74,.14) 127px 128px, transparent 129px),
    var(--tf-ico-seal) center / 164px 164px no-repeat !important;
  opacity: .96 !important;
  animation: tf-preloader-pulse 3.4s ease-in-out infinite !important;
}
#loader.splash-screen::after,
#loader:not(.splash-screen)::after {
  content: "" !important;
  position: absolute !important;
  z-index: 2 !important;
  display: block !important;
  left: 50% !important;
  top: 50% !important;
  width: 274px !important;
  height: 274px !important;
  margin: 0 !important;
  border: 0 !important;
  border-radius: 50% !important;
  transform: translate(-50%,-50%) !important;
  background: conic-gradient(from 8deg, transparent 0deg, transparent 230deg, rgba(209,173,98,.02) 242deg, rgba(209,173,98,.84) 257deg, transparent 268deg, transparent 360deg) !important;
  -webkit-mask: radial-gradient(circle, transparent 0 128px, #000 129px 131px, transparent 132px) !important;
  mask: radial-gradient(circle, transparent 0 128px, #000 129px 131px, transparent 132px) !important;
  animation: tf-orbit-sweep 5.8s linear infinite !important;
  pointer-events: none !important;
}
#loader.splash-screen .splash-message,
#loader:not(.splash-screen) .splash-message {
  position: absolute !important;
  z-index: 3 !important;
  top: calc(50% + 160px) !important;
  left: 50% !important;
  transform: translateX(-50%) !important;
  display: block !important;
  width: max-content !important;
  max-width: calc(100vw - 30px) !important;
  margin: 0 !important;
  padding: 0 !important;
  overflow: visible !important;
  color: transparent !important;
  font-size: 0 !important;
  line-height: 0 !important;
  text-shadow: none !important;
  text-align: center !important;
  white-space: normal !important;
}
#loader.splash-screen .splash-message::after,
#loader:not(.splash-screen) .splash-message::after {
