/* 顶栏抽屉入口：以线性档案图标替换原生字形，按钮本体与点击区域不变。 */
#top-settings-holder .drawer > .drawer-toggle,
#top-settings-holder #rightNavHolder > #unimportantYes {
  position: relative !important;
  box-sizing: border-box !important;
  min-width: 38px !important;
  min-height: 38px !important;
  border: 1px solid rgba(185,201,186,.23) !important;
  border-radius: 2px !important;
  background-color: rgba(12,20,21,.94) !important;
  box-shadow: inset 0 1px 0 rgba(229,229,217,.035), 0 3px 10px rgba(0,0,0,.14) !important;
  transition: border-color .18s ease, background-color .18s ease, transform .18s ease !important;
  background-repeat: no-repeat !important;
  background-position: center !important;
  background-size: 21px 21px, 100% 100% !important;
  background-position: center, center !important;
  background-repeat: no-repeat, no-repeat !important;
}
#top-settings-holder .drawer > .drawer-toggle:hover,
#top-settings-holder #rightNavHolder > #unimportantYes:hover {
  border-color: rgba(209,173,98,.58) !important;
  background-color: rgba(28,42,39,.98) !important;
  transform: translateY(-1px) !important;
}
#top-settings-holder .drawer > .drawer-toggle > .drawer-icon,
#top-settings-holder .drawer > .drawer-toggle .drawer-icon,
#top-settings-holder #rightNavHolder > #unimportantYes .drawer-icon {
  color: transparent !important;
  text-shadow: none !important;
  opacity: 0 !important;
  visibility: visible !important;
  pointer-events: none !important;
}
#top-settings-holder #ai-config-button > .drawer-toggle { background-image: var(--tf-ico-sliders), linear-gradient(145deg,rgba(30,43,42,.96),rgba(7,13,14,.96)) !important; }
#top-settings-holder #sys-settings-button > .drawer-toggle { background-image: var(--tf-ico-settings), linear-gradient(145deg,rgba(30,43,42,.96),rgba(7,13,14,.96)) !important; }
#top-settings-holder #WI-SP-button > .drawer-toggle { background-image: var(--tf-ico-book), linear-gradient(145deg,rgba(30,43,42,.96),rgba(7,13,14,.96)) !important; }
#top-settings-holder #user-settings-button > .drawer-toggle { background-image: var(--tf-ico-id), linear-gradient(145deg,rgba(30,43,42,.96),rgba(7,13,14,.96)) !important; }
#top-settings-holder #backgrounds-button > #backgrounds-drawer-toggle { background-image: var(--tf-ico-landscape), linear-gradient(145deg,rgba(30,43,42,.96),rgba(7,13,14,.96)) !important; }
#top-settings-holder #extensions-settings-button > .drawer-toggle { background-image: var(--tf-ico-puzzle), linear-gradient(145deg,rgba(30,43,42,.96),rgba(7,13,14,.96)) !important; }
#top-settings-holder #persona-management-button > .drawer-toggle { background-image: var(--tf-ico-id), linear-gradient(145deg,rgba(30,43,42,.96),rgba(7,13,14,.96)) !important; }
#top-settings-holder #advanced-formatting-button > .drawer-toggle { background-image: var(--tf-ico-book), linear-gradient(145deg,rgba(30,43,42,.96),rgba(7,13,14,.96)) !important; }
#top-settings-holder #rightNavHolder > #unimportantYes { background-image: var(--tf-ico-folder), linear-gradient(145deg,rgba(30,43,42,.96),rgba(7,13,14,.96)) !important; }
/* 第三方抽屉入口未有固定语义时使用统一的“工具箱”线稿图标。 */
#top-settings-holder .drawer:not(#ai-config-button):not(#sys-settings-button):not(#advanced-formatting-button):not(#WI-SP-button):not(#user-settings-button):not(#backgrounds-button):not(#extensions-settings-button):not(#persona-management-button):not(#rightNavHolder) > .drawer-toggle {
  background-image: var(--tf-ico-folder), linear-gradient(145deg,rgba(30,43,42,.96),rgba(7,13,14,.96)) !important;
}
/* 输入区与生成控制按键：同一规格、不同功能图标。 */
#send_but, #options_button, #extensionsMenuButton, #mes_stop,
#stscript_continue, #stscript_pause, #stscript_stop,
#mes_impersonate, #mes_continue {
  position: relative !important;
  box-sizing: border-box !important;
  width: 38px !important;
  height: 38px !important;
  min-width: 38px !important;
  min-height: 38px !important;
  padding: 0 !important;
  border: 1px solid rgba(185,201,186,.28) !important;
  border-radius: 2px !important;
  background: linear-gradient(145deg, rgba(29,43,41,.96), rgba(7,13,14,.98)) !important;
  box-shadow: inset 0 1px 0 rgba(229,229,217,.035), 0 3px 10px rgba(0,0,0,.15) !important;
  color: transparent !important;
  text-shadow: none !important;
  font-size: 0 !important;
  transition: border-color .18s ease, background .18s ease, box-shadow .18s ease, transform .18s ease !important;
}
#send_but:hover, #options_button:hover, #extensionsMenuButton:hover,
#mes_stop:hover, #stscript_continue:hover, #stscript_pause:hover,
#stscript_stop:hover, #mes_impersonate:hover, #mes_continue:hover {
  border-color: rgba(209,173,98,.63) !important;
  background: linear-gradient(145deg, rgba(47,60,53,.98), rgba(13,20,20,.98)) !important;
  box-shadow: 0 0 16px rgba(209,173,98,.07), inset 0 1px 0 rgba(229,229,217,.055) !important;
  transform: translateY(-1px) !important;
}
#send_but::before, #options_button::before, #extensionsMenuButton::before,
#mes_stop::before, #stscript_continue::before, #stscript_pause::before,
#stscript_stop::before, #mes_impersonate::before, #mes_continue::before {
  content: "" !important;
  position: absolute !important;
  display: block !important;
  left: 50% !important;
  top: 50% !important;
  width: 20px !important;
  height: 20px !important;
  transform: translate(-50%,-50%) !important;
  background-position: center !important;
  background-repeat: no-repeat !important;
  background-size: contain !important;
  pointer-events: none !important;
}
#options_button::before { background-image: var(--tf-ico-sliders) !important; }
#send_but::before { background-image: var(--tf-ico-send) !important; }
#extensionsMenuButton::before { background-image: var(--tf-ico-puzzle) !important; }
#mes_stop::before, #stscript_stop::before { background-image: var(--tf-ico-stop) !important; }
#stscript_continue::before, #mes_continue::before { background-image: var(--tf-ico-continue) !important; }
#stscript_pause::before { background-image: var(--tf-ico-pause) !important; }
#mes_impersonate::before { background-image: var(--tf-ico-id) !important; }
#options_button > i, #send_but > i, #mes_stop > i, #stscript_continue > i,
#stscript_pause > i, #stscript_stop > i, #mes_impersonate > i, #mes_continue > i,
#extensionsMenuButton > * { opacity: 0 !important; }
