/* =========================================================
   16 / TRACE FILE 07 — TARGET BOARD EDITION
   欢迎页：关联线索墙 + 动态人物档案卡
   加载页：纯 CSS 目标捕获 / 扫描线 / 锁定呼吸
   注意：本段不改动顶栏抽屉结构与点击目标。
   ========================================================= */
:root {
  --tf-target-red: #c4574b;
  --tf-target-amber: #dfbd71;
  --tf-target-green: #a2b9a8;
  --tf-target-paper: #e9e8dc;
}

@keyframes tf-target-orbit {
  from { transform: translate(-50%, -50%) rotate(0deg); }
  to { transform: translate(-50%, -50%) rotate(360deg); }
}
@keyframes tf-target-counter-orbit {
  from { transform: translate(-50%, -50%) rotate(360deg); }
  to { transform: translate(-50%, -50%) rotate(0deg); }
}
@keyframes tf-target-lock {
  0%, 100% { opacity: .55; filter: brightness(.9); }
  50% { opacity: 1; filter: brightness(1.22); }
}
@keyframes tf-target-scan {
  0% { background-position: 0 -45vh, 0 0, 0 0; }
  100% { background-position: 0 145vh, 0 0, 0 0; }
}
@keyframes tf-target-pulse {
  0%, 100% { opacity: .34; transform: translate(-50%, -50%) scale(.91); }
  50% { opacity: .82; transform: translate(-50%, -50%) scale(1.03); }
}
@keyframes tf-target-beam {
  0% { transform: translateY(-35vh); opacity: 0; }
  10% { opacity: .6; }
  82% { opacity: .38; }
  100% { transform: translateY(135vh); opacity: 0; }
}
@keyframes tf-map-node {
  0%, 100% { box-shadow: 0 0 0 0 rgba(209,173,98,0); }
  50% { box-shadow: 0 0 0 5px rgba(209,173,98,.08); }
}
@keyframes tf-card-sweep {
  0% { background-position: -120% 0, 0 0; }
  55%, 100% { background-position: 220% 0, 0 0; }
}
@keyframes tf-file-blink {
  0%, 93%, 100% { opacity: .9; }
  96% { opacity: .32; }
}

