/* 16.3 / 动态瞄准加载：保留 spinner DOM，只重做外观，不隐藏它 */
#preloader {
  overflow: hidden !important;
  background:
    radial-gradient(circle at 50% 50%, rgba(196,87,75,.11), transparent 17%),
    radial-gradient(circle at 50% 50%, transparent 0 69px, rgba(162,185,168,.22) 69.5px 70px, transparent 70.5px),
    radial-gradient(circle at 50% 50%, transparent 0 101px, rgba(162,185,168,.13) 101.5px 102px, transparent 102.5px),
    linear-gradient(145deg, #10191b, #070d0f 59%, #11191a) !important;
}
#preloader::before {
  content: "" !important;
  position: absolute !important;
  z-index: 1 !important;
  inset: 0 !important;
  pointer-events: none !important;
  background:
    linear-gradient(90deg, transparent calc(50% - .5px), rgba(162,185,168,.17) 50%, transparent calc(50% + .5px)),
    linear-gradient(0deg, transparent calc(50% - .5px), rgba(162,185,168,.17) 50%, transparent calc(50% + .5px)),
