  animation: tf-target-scan 3.5s linear infinite !important;
}
#preloader::after {
  content: "TARGET ACQUISITION  /  TRACE 07" !important;
  position: absolute !important;
  z-index: 3 !important;
  top: calc(50% + 94px) !important;
  left: 50% !important;
