}
#load-spinner::before {
  content: "" !important;
  position: absolute !important;
  inset: 12px !important;
  display: block !important;
  border: 1px dashed rgba(162,185,168,.7) !important;
  border-radius: 50% !important;
  background:
    radial-gradient(circle at 50% 50%, rgba(196,87,75,.95) 0 2px, transparent 3px),
    linear-gradient(90deg, transparent calc(50% - .5px), rgba(162,185,168,.5) 50%, transparent calc(50% + .5px)),
    linear-gradient(0deg, transparent calc(50% - .5px), rgba(162,185,168,.5) 50%, transparent calc(50% + .5px)) !important;
