#chat .mes {
  position: relative;
  box-sizing: border-box;
  width: auto !important;
  align-self: stretch !important;
  margin: 14px 10px !important;
  padding: 14px 16px 12px !important;
  background-color: rgba(var(--gm-lacquer), 0.9) !important;
  border: 1px solid rgba(var(--gm-gold), 0.42) !important;
  outline: 1px solid rgba(var(--gm-gold), 0.16);
  outline-offset: -5px;
  border-radius: 0 !important;
  box-shadow: none !important;
}
#chat .mes::before,
#chat .mes::after {
  content: "";
  position: absolute;
  width: 16px;
  height: 16px;
  pointer-events: none;
  border-color: rgb(var(--gm-gold));
