  border: 1px solid rgba(var(--gm-gold), 0.6);
}

#toast-container > .toast {
  background-image: none !important;
  background-color: rgba(var(--gm-onyx), 0.97) !important;
  border: 1px solid var(--gm-rule) !important;
  outline: 1px solid var(--gm-rule-soft);
  outline-offset: -4px;
  border-radius: 0 !important;
  box-shadow: none !important;
  color: rgb(var(--gm-ivory)) !important;
  opacity: 1 !important;
}
#toast-container .toast-title {
  font-family: var(--gm-caps);
  letter-spacing: 0.12em;
  color: rgb(var(--gm-gold-hi)) !important;
}
#toast-container > .toast-error { border-color: rgba(190, 92, 72, 0.7) !important; }
#toast-container > .toast-success { border-color: rgba(var(--gm-green), 0.6) !important; }
#toast-container .toast-progress { background: rgba(var(--gm-gold), 0.5) !important; }

@media (max-width: 1000px) {
  #chat .mes {
    margin: 10px 4px !important;
    padding: 10px 10px 8px !important;
  }
  #chat .mes::before,
  #chat .mes::after {
    width: 10px;
    height: 10px;
  }
  #chat .mes .name_text {
    font-size: 19px !important;
    letter-spacing: 0.1em !important;
  }
  #chat {
    border-left: 0;
    border-right: 0;
  }
}

@media (prefers-reduced-motion: reduce) {
  .drawer-icon,
  .menu_button { transition: none; }
}

/* 薄雾花园 · 暮色溪谷 (Misty Garden) */

/* 1. 全局调色盘与原生变量 (:root) */
:root {

  --mist-bg-base: #c8aea0;

  --mist-surface-main: linear-gradient(
    90deg,
    rgba(228, 210, 200, 0.00) 0%,
    rgba(228, 210, 200, 0.12) 3%,
    rgba(232, 214, 204, 0.25) 7%,
    rgba(235, 219, 209, 0.34) 14%,
    rgba(236, 221, 211, 0.38) 50%,
    rgba(235, 219, 209, 0.34) 86%,
    rgba(232, 214, 204, 0.25) 93%,
    rgba(228, 210, 200, 0.12) 97%,
    rgba(228, 210, 200, 0.00) 100%
  );
  --mist-surface-bar: linear-gradient(
    90deg,
    rgba(224, 206, 196, 0.00) 0%,
    rgba(224, 206, 196, 0.20) 5%,
    rgba(228, 210, 200, 0.42) 15%,
    rgba(230, 212, 202, 0.46) 50%,
    rgba(228, 210, 200, 0.42) 85%,
    rgba(224, 206, 196, 0.20) 95%,
    rgba(224, 206, 196, 0.00) 100%
  );

  --mist-surface-ai: transparent;
  --mist-surface-user: linear-gradient(
    90deg,
    rgba(198, 156, 152, 0.00) 0%,
    rgba(198, 156, 152, 0.12) 5%,
    rgba(198, 156, 152, 0.22) 14%,
    rgba(198, 156, 152, 0.22) 86%,
    rgba(198, 156, 152, 0.12) 95%,
    rgba(198, 156, 152, 0.00) 100%
  );
  --mist-surface-field: rgba(230, 214, 204, 0.34);
  --mist-surface-field-focus: rgba(240, 227, 218, 0.64);

  --mist-panel-solid: rgba(230, 214, 205, 0.97);
  --mist-panel-solid-light: rgba(236, 223, 214, 0.98);
  --mist-panel-solid-rose: rgba(220, 200, 193, 0.97);

  --mist-ink: #261512;
  --mist-ink-strong: #180c0a;
  --mist-muted: #543831;
  --mist-muted-light: #74564e;
  --mist-disabled-ink: #785b53;

  --mist-crimson: #8a2b2a;
  --mist-rose: #b06664;
  --mist-rose-soft: rgba(172, 98, 95, 0.16);
  --mist-rose-hover: rgba(172, 98, 95, 0.25);
  --mist-berry: #4c2623;
  --mist-gold: #ad865c;

  --mist-divider: rgba(138, 94, 82, 0.18);
  --mist-divider-soft: rgba(138, 94, 82, 0.12);
  --mist-divider-fade: linear-gradient(
    90deg,
    transparent 0%,
    transparent 5%,
    rgba(138, 94, 82, 0.18) 18%,
    rgba(138, 94, 82, 0.18) 82%,
    transparent 95%,
    transparent 100%
  );
  --mist-hairline: rgba(144, 100, 88, 0.22);
  --mist-shadow-float: 0 12px 34px rgba(38, 22, 16, 0.18);

  --mist-serif-font: "Songti SC", "Noto Serif SC", "Source Han Serif SC", "STSong", Georgia, serif;

  --SmartThemeBodyColor: #261512 !important;
  --SmartThemeEmColor: #543831 !important;
  --SmartThemeUnderlineColor: #8a2b2a !important;
  --SmartThemeQuoteColor: #8a2b2a !important;
  --SmartThemeBlurTintColor: transparent !important;
  --SmartThemeChatTintColor: transparent !important;
  --SmartThemeBotMesBlurTintColor: transparent !important;
  --SmartThemeUserMesBlurTintColor: rgba(198, 156, 152, 0.18) !important;
  --SmartThemeBorderColor: transparent !important;
  --SmartThemeShadowColor: transparent !important;

  --SmartThemeCheckboxTickColor: #fbf5ee !important;

  --white20a: rgba(136, 96, 86, 0.16) !important;
  --white30a: rgba(94, 64, 56, 0.66) !important;
  --white50a: rgba(78, 50, 42, 0.80) !important;
  --white60a: rgba(64, 38, 32, 0.88) !important;
  --white70a: rgba(50, 28, 22, 0.94) !important;
  --white100: #261512 !important;

  --grey10: #e8d9ce !important;
  --grey30: #dcc9bc !important;
  --grey30a: rgba(136, 96, 86, 0.12) !important;
  --grey50: #5e423a !important;
  --grey5020a: rgba(136, 96, 86, 0.14) !important;
  --grey5050a: rgba(136, 96, 86, 0.30) !important;
  --grey70: #483029 !important;
  --grey75: #3a241e !important;
  --grey7070a: rgba(132, 92, 82, 0.36) !important;
  --ivory: #261512 !important;
  --golden: #96642b !important;
  --active: #547344 !important;
  --fullred: #a83636 !important;
  --warning: #b05624 !important;

  --black30a: rgba(126, 86, 76, 0.08) !important;
  --black50a: rgba(126, 86, 76, 0.13) !important;
  --black60a: rgba(106, 70, 62, 0.16) !important;
  --black70a: rgba(86, 56, 48, 0.20) !important;
  --black90a: rgba(228, 212, 202, 0.92) !important;

  --ac-color-text: #261512 !important;
  --ac-style-color-text: #261512 !important;
  --ac-style-color-background: #e8d8cd !important;

  color-scheme: light;
}

* {
  text-shadow: none !important;
}

/* 2. 全屏油画背景与滚动条 */
html,
body {
  color: var(--mist-ink) !important;
  background-color: var(--mist-bg-base) !important;
  scrollbar-width: thin;
  scrollbar-color: rgba(144, 98, 88, 0.22) transparent;
}

body,
#bg1,
#bg2,
#bg_custom {
  background-color: var(--mist-bg-base) !important;
  background-image:
    linear-gradient(
      90deg,
      rgba(44, 26, 20, 0.06) 0%,
      rgba(224, 204, 194, 0.02) 16%,
      rgba(234, 218, 208, 0.18) 34%,
      rgba(236, 221, 211, 0.24) 50%,
      rgba(234, 218, 208, 0.18) 66%,
      rgba(224, 204, 194, 0.02) 84%,
      rgba(44, 26, 20, 0.06) 100%
    ),
    var(--mist-oil-painting) !important;
  background-size: cover, cover !important;
  background-position: center center, center center !important;
  background-repeat: no-repeat, no-repeat !important;
  background-attachment: fixed, fixed !important;
  filter: none !important;
  opacity: 1 !important;
}

::-webkit-scrollbar {
  width: 3px !important;
  height: 3px !important;
}
::-webkit-scrollbar-track {
  background: transparent !important;
}
::-webkit-scrollbar-thumb,
::-webkit-scrollbar-thumb:vertical,
::-webkit-scrollbar-thumb:horizontal {
  background-color: rgba(144, 98, 88, 0.18) !important;
  box-shadow: none !important;
  border: 0 !important;
  border-radius: 999px !important;
}
::-webkit-scrollbar-thumb:hover {
  background-color: rgba(138, 43, 42, 0.45) !important;
}

::selection {
  color: var(--mist-ink-strong);
  background-color: rgba(176, 102, 100, 0.28);
}

:focus-visible {
  outline: 1px solid rgba(138, 43, 42, 0.40) !important;
  outline-offset: 1px;
}

/* 3. 顶部工具栏与状态栏 */

#top-settings-holder,
#top-bar,
body.no-blur #top-settings-holder,
body.no-blur #top-bar {
  color: var(--mist-muted) !important;
  background: var(--mist-surface-bar) !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  border: 0 !important;
  border-bottom: 0 !important;
  border-radius: 0 !important;
  box-shadow: none !important;
  color-scheme: light;
}

#extensionTopBar,
#sheld > div:not(#chat):not(#form_sheld):not(#extensionConnectionProfiles) {
  color: var(--mist-muted) !important;
  background: linear-gradient(
    90deg,
    rgba(228, 210, 200, 0.00) 0%,
    rgba(230, 212, 202, 0.16) 4%,
    rgba(234, 218, 208, 0.34) 12%,
    rgba(236, 220, 210, 0.38) 50%,
    rgba(234, 218, 208, 0.34) 88%,
    rgba(230, 212, 202, 0.16) 96%,
    rgba(228, 210, 200, 0.00) 100%
  ) !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  border: 0 !important;
  border-bottom: 1px solid transparent !important;
  border-image: var(--mist-divider-fade) 1 !important;
  border-radius: 0 !important;
  box-shadow: none !important;
  padding: 3px 24px 5px 24px !important;
  font-size: 0.88rem !important;
  color-scheme: light;
}

#sheld > #extensionConnectionProfiles,
#extensionConnectionProfiles,
#extensionConnectionProfiles.visible {
  display: none !important;
}

#top-settings-holder > .drawer,
#top-settings-holder > .drawer > .drawer-icon {
  color: #64443d !important;
  background: transparent !important;
  background-image: none !important;
  border: 0 !important;
  outline: 0 !important;
  box-shadow: none !important;
  filter: none !important;
}

#top-settings-holder > .drawer > .drawer-icon::before,
#top-settings-holder > .drawer > .drawer-icon i {
  color: #64443d !important;
  filter: none !important;
  transition: color 150ms ease;
}

#top-settings-holder > .drawer > .drawer-icon:hover,
#top-settings-holder > .drawer.openDrawer > .drawer-icon,
#top-settings-holder > .drawer > .drawer-icon.openIcon {
  color: var(--mist-crimson) !important;
  background: var(--mist-rose-soft) !important;
  border-radius: 8px !important;
}

#top-settings-holder > .drawer > .drawer-icon:hover i,
#top-settings-holder > .drawer.openDrawer > .drawer-icon i,
#top-settings-holder > .drawer > .drawer-icon.openIcon i,
#top-settings-holder > .drawer > .drawer-icon:hover::before {
  color: var(--mist-crimson) !important;
}

#extensionTopBar select,
#extensionTopBar select.text_pole,
#sheld > div:not(#chat):not(#form_sheld):not(#extensionConnectionProfiles) select,
#sheld > div:not(#chat):not(#form_sheld):not(#extensionConnectionProfiles) select.text_pole {
  box-sizing: border-box !important;
  color: var(--mist-berry) !important;
  font-weight: 500 !important;
  font-size: 0.88rem !important;
  background: transparent !important;
  background-color: transparent !important;
  border: 1px solid transparent !important;
  border-radius: 6px !important;
  padding: 2px 6px !important;
  box-shadow: none !important;
  outline: none !important;
  cursor: pointer;
  transition: background-color 150ms ease, border-color 150ms ease, color 150ms ease;
}

#extensionTopBar input,
#extensionTopBar input.text_pole,
#extensionTopBar textarea,
#sheld > div:not(#chat):not(#form_sheld):not(#extensionConnectionProfiles) input,
#sheld > div:not(#chat):not(#form_sheld):not(#extensionConnectionProfiles) input.text_pole {
  box-sizing: border-box !important;
  color: var(--mist-ink) !important;
  font-size: 0.86rem !important;
  background: transparent !important;
  background-color: transparent !important;
  border: 0 !important;
  border-bottom: 1px solid rgba(138, 94, 82, 0.22) !important;
  border-radius: 0 !important;
  padding: 2px 6px !important;
  box-shadow: none !important;
  outline: none !important;
  transition: background-color 150ms ease, border-color 150ms ease;
}

#extensionTopBar select:hover,
#sheld > div:not(#chat):not(#form_sheld):not(#extensionConnectionProfiles) select:hover {
  color: var(--mist-crimson) !important;
  background: rgba(172, 98, 95, 0.12) !important;
  border-color: rgba(138, 94, 82, 0.16) !important;
}

#extensionTopBar input:focus,
#sheld > div:not(#chat):not(#form_sheld):not(#extensionConnectionProfiles) input:focus {
  background: rgba(238, 224, 214, 0.35) !important;
  border-bottom-color: var(--mist-crimson) !important;
  border-radius: 4px 4px 0 0 !important;
}

#extensionTopBar button,
#extensionTopBar .menu_button,
#extensionTopBar .menu_button_icon,
#extensionTopBar .interactable,
#extensionTopBar i,
#extensionTopBar [role="button"],
#sheld > div:not(#chat):not(#form_sheld):not(#extensionConnectionProfiles) button,
#sheld > div:not(#chat):not(#form_sheld):not(#extensionConnectionProfiles) .menu_button,
#sheld > div:not(#chat):not(#form_sheld):not(#extensionConnectionProfiles) .interactable,
#sheld > div:not(#chat):not(#form_sheld):not(#extensionConnectionProfiles) i {
  box-sizing: border-box !important;
  color: #684840 !important;
  opacity: 0.78;
  background: transparent !important;
  background-image: none !important;
  border: 0 !important;
  outline: 0 !important;
  box-shadow: none !important;
  filter: none !important;
  border-radius: 6px !important;
  transition: color 150ms ease, opacity 150ms ease, background-color 150ms ease;
}

#extensionTopBar button:hover,
#extensionTopBar .menu_button:hover,
#extensionTopBar .interactable:hover,
#sheld > div:not(#chat):not(#form_sheld):not(#extensionConnectionProfiles) button:hover,
#sheld > div:not(#chat):not(#form_sheld):not(#extensionConnectionProfiles) .menu_button:hover,
#sheld > div:not(#chat):not(#form_sheld):not(#extensionConnectionProfiles) .interactable:hover,
#sheld > div:not(#chat):not(#form_sheld):not(#extensionConnectionProfiles) i:hover {
  color: var(--mist-crimson) !important;
  opacity: 1 !important;
  background: var(--mist-rose-soft) !important;
}

/* 4. 聊天主容器与消息流 (#sheld & #chat) */

#sheld,
body.no-blur #sheld {
  color: var(--mist-ink);
  background: var(--mist-surface-main) !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  border: 0 !important;
  box-shadow: none !important;
}

#chat,
body.no-blur #chat {
  color: var(--mist-ink);
  background: transparent !important;
  background-color: transparent !important;
  background-image: none !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  border: 0 !important;
  border-radius: 0 !important;
  box-shadow: none !important;
}

#chat .mes,
body.no-blur #chat .mes {
  color: var(--mist-ink);
  margin: 0 !important;
  padding: 16px 28px !important;
  border-radius: 0 !important;
  background: var(--mist-surface-ai) !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  border: 0 !important;
  border-bottom: 1px solid transparent !important;
  border-image: var(--mist-divider-fade) 1 !important;
  box-shadow: none !important;
}

#chat .mes:not([is_user="true"]),
body.no-blur #chat .mes:not([is_user="true"]) {
  background: var(--mist-surface-ai) !important;
}

#chat .mes[is_user="true"],
body.no-blur #chat .mes[is_user="true"] {
  background: var(--mist-surface-user) !important;
}

#chat .mes.last_mes {
  border-bottom: 0 !important;
  border-image: none !important;
}

#chat .mes .avatar img,
.avatar img {
  border-radius: 10px !important;
  border: 1px solid rgba(168, 128, 110, 0.32) !important;
  box-shadow: 0 2px 6px rgba(48, 28, 22, 0.08) !important;
}

.mes .ch_name,
.mes .name_text,
.mes .name {
  font-family: var(--mist-serif-font);
  color: var(--mist-berry) !important;
  font-weight: 700 !important;
  letter-spacing: 0.02em;
}

.mes .mesIDDisplay,
.mes .timestamp,
.mes .tokenCounterDisplay,
.mes .mes_timer {
  color: var(--mist-muted-light) !important;
}

.mes .mes_buttons,
.mes .mes_buttons *,
.mes .mes_buttons .mes_button,
.mes .extraMesButtons .mes_button {
  color: var(--mist-muted) !important;
  background: transparent !important;
  border: 0 !important;
  box-shadow: none !important;
  filter: none !important;
  border-radius: 6px !important;
  opacity: 0.68;
  transition: opacity 150ms ease, background-color 150ms ease, color 150ms ease;
}

.mes .mes_buttons .mes_button:hover,
.mes .extraMesButtons .mes_button:hover {
  color: var(--mist-crimson) !important;
  background: var(--mist-rose-soft) !important;
  opacity: 1;
}

.mes_reasoning_details,
.mes details {
  background: transparent !important;
  background-color: transparent !important;
  border: 0 !important;
  padding: 0 !important;
  margin: 4px 0 8px 0 !important;
  box-shadow: none !important;
}

.mes_reasoning_header,
.mes_reasoning summary {
  position: relative !important;
  display: inline-flex !important;
  align-items: center !important;
  color: var(--mist-berry) !important;
  background: rgba(238, 222, 212, 0.38) !important;
  border: 1px solid rgba(138, 94, 82, 0.20) !important;
  border-radius: 999px !important;

  padding: 3px 28px 3px 12px !important;
  margin: 0 !important;
  font-size: 0.84em !important;
  font-weight: 500 !important;
  line-height: 1.4 !important;
  box-shadow: none !important;
  cursor: pointer;
  transition: background-color 150ms ease, border-color 150ms ease, color 150ms ease;
}

.mes details:not(.mes_reasoning_details) > summary {
  display: inline-flex !important;
  align-items: center !important;
  color: var(--mist-berry) !important;
  background: rgba(238, 222, 212, 0.38) !important;
  border: 1px solid rgba(138, 94, 82, 0.20) !important;
  border-radius: 999px !important;
  padding: 3px 14px !important;
  margin: 0 !important;
  font-size: 0.84em !important;
  font-weight: 500 !important;
  line-height: 1.4 !important;
  box-shadow: none !important;
  cursor: pointer;
  transition: background-color 150ms ease, border-color 150ms ease, color 150ms ease;
}

.mes_reasoning_header:hover,
.mes details > summary:hover {
  color: var(--mist-crimson) !important;
  background: rgba(242, 228, 218, 0.62) !important;
  border-color: rgba(138, 43, 42, 0.30) !important;
}

.mes_reasoning_header_title {
  background: transparent !important;
  border: 0 !important;
  padding: 0 !important;
  margin: 0 !important;
}

.mes_reasoning_arrow {
  right: 10px !important;
  color: var(--mist-muted) !important;
}

.mes_reasoning,
.mes .mes_reasoning {
  color: var(--mist-muted) !important;
  background: rgba(232, 216, 206, 0.28) !important;
  border: 0 !important;
  border-left: 2px solid rgba(173, 134, 92, 0.45) !important;
  border-radius: 0 8px 8px 0 !important;
  padding: 8px 14px !important;
  margin-top: 6px !important;
  box-shadow: none !important;
}

.swipes-counter {
  color: var(--mist-berry) !important;
  font-weight: 500 !important;
  opacity: 0.85 !important;
  filter: none !important;
}

.swipe_left,
.swipe_right {
  color: var(--mist-berry) !important;
  opacity: 0.78 !important;
  filter: none !important;
  border-radius: 999px !important;
  padding: 2px 5px !important;
  transition: color 150ms ease, opacity 150ms ease, background-color 150ms ease;
}

.swipe_left:hover,
.swipe_right:hover {
  color: var(--mist-crimson) !important;
  background: var(--mist-rose-soft) !important;
  opacity: 1 !important;
}

/* 5. 正文排版、代码块与表格 */
.mes .mes_text {
  color: var(--mist-ink) !important;
  line-height: 1.78;
  letter-spacing: 0.01em;
}

.mes .mes_text q,
#chat q {
  color: var(--mist-crimson) !important;
  background: transparent !important;
  font-weight: 500;
}

.mes .mes_text em,
.mes .mes_text i,
#chat em:not(.fa):not(.fa-solid):not(.fa-regular):not([class*="fa-"]),
#chat i:not(.fa):not(.fa-solid):not(.fa-regular):not([class*="fa-"]) {
  color: var(--mist-muted) !important;
}

.mes .mes_text strong,
.mes .mes_text b {
  color: var(--mist-ink-strong) !important;
  font-weight: 650;
}

#chat a,
.mes .mes_text a {
  color: var(--mist-crimson);
  text-decoration-color: rgba(138, 43, 42, 0.38);
  text-underline-offset: 2px;
}

#chat a:hover,
.mes .mes_text a:hover {
  color: var(--mist-berry);
}

.mes blockquote,
blockquote {
  color: #462d26 !important;
  border: 0 !important;
  border-left: 2px solid var(--mist-gold) !important;
  background-color: rgba(218, 200, 190, 0.26) !important;
  border-radius: 0 6px 6px 0;
}

.mes pre,
.mes code,
pre,
code,
.custom-code {
  color: #462421 !important;
  background-color: rgba(220, 202, 192, 0.38) !important;
  border: 1px solid rgba(156, 114, 102, 0.20) !important;
  border-radius: 6px;
}

.mes pre code,
pre code {
  background: transparent !important;
  border: 0 !important;
}

.code-copy {
  color: var(--mist-berry) !important;
  background: rgba(236, 220, 210, 0.72) !important;
  border: 1px solid rgba(138, 94, 82, 0.22) !important;
  border-radius: 5px !important;
  box-shadow: none !important;
  filter: none !important;
}

.code-copy:hover {
  color: var(--mist-crimson) !important;
  background: rgba(242, 228, 218, 0.92) !important;
}

mark {
  color: var(--mist-ink-strong) !important;
  background-color: rgba(196, 136, 112, 0.28) !important;
  border-radius: 3px;
  padding: 0 3px;
}

kbd {
  color: var(--mist-berry) !important;
  background-color: rgba(232, 216, 206, 0.65) !important;
  border: 1px solid rgba(138, 94, 82, 0.26) !important;
  border-radius: 4px;
  padding: 1px 5px;
  box-shadow: none !important;
}

