.mes[hide_name="true"],
.mes[is_system="true"] {
    opacity: 0.45 !important; /* 透明度可调：0.1~0.9，越小越淡 */
    transition: opacity 0.3s ease !important;
}

/* 2. 悬停在已隐藏消息上时稍微加亮，方便查看和取消隐藏 */
.mes.hide_mes:hover,
.mes.hide_name:hover,
.mes[hide_name="true"]:hover,
.mes[is_system="true"]:hover {
    opacity: 0.85 !important;
}


/* 悬停/触摸头像时平滑回正与轻微浮起 */
.mes .avatar {
    transition: transform 0.3s cubic-bezier(0.34, 1.56, 0.64, 1), box-shadow 0.3s ease !important;
}

.mes .avatar:hover {
    transform: rotate(0deg) scale(1.05) translateY(-2px) !important;
    box-shadow: 0 6px 16px rgba(0, 0, 0, 0.3) !important;
}


/* ==========================================================
   切页组件（页码 & 左右箭头）默认淡化控制
   ========================================================== */

/* 1. 全局配置区追加变量（如已声明可放入 :root 内，或直接保留在这里） */
:root {
    --swipe-idle-opacity: 0.35; /* 默认淡化透明度，范围 0~1 (例如 0.2 很淡，0.5 较清晰) */
}

/* 2. 默认应用淡化透明度 */
.swipes-counter,
.swipe_left,
.swipe_right,
[title="Swipe left"],
[title="Swipe right"] {
    opacity: var(--swipe-idle-opacity) !important;
    transition: opacity 0.3s ease !important;
}



/* ==========================================================
   美化 Toast 系统通知弹窗（保存提示、消息通知等）
   ========================================================== */

/* 1. 提示框总容器定位与层级 */
#toast-container {
    top: 20px !important;                 /* 距离顶部高度 */
    right: 20px !important;               /* 距离右侧间距 */
    z-index: 999999 !important;           /* 确保最外层置顶 */
}

/* 2. Toast 提示框本体外观美化 */
#toast-container > .toast {
    /* 基础形变与圆角 */
    border-radius: 12px !important;
    padding: 10px 18px !important;
    margin-bottom: 8px !important;
    box-shadow: 0 8px 24px rgba(0, 0, 0, 0.35) !important;

    /* 高透毛玻璃 */
    background: color-mix(in srgb, var(--SmartThemeBlurTintColor, var(--smart-bg, #121216)) 80%, transparent) !important;
    backdrop-filter: blur(4px) !important;
    -webkit-backdrop-filter: blur(4px) !important;
    border: 1px solid var(--SmartThemeBorderColor, rgba(255, 255, 255, 0.15)) !important;

    /* 字体与排版 */
    font-family: var(--my-custom-font, inherit) !important;
    font-size: 12.5px !important;
    letter-spacing: 0.5px !important;
    color: var(--SmartThemeBodyColor, #fff) !important;

    /* 滑入弹跳入场动画 */
    animation: toast_bounce_in 0.35s cubic-bezier(0.175, 0.885, 0.32, 1.275) forwards !important;
    opacity: 1 !important;
}

/* 3. 不同类型提示框的边框/小发光色彩（成功、错误、警告、信息） */

/* 成功提示（如：保存成功、加载成功） */
#toast-container > .toast-success {
    border-left: 3px solid #4CAF50 !important; /* 翡翠绿发光条 */
}

/* 错误提示（如：API报错、请求失败） */
#toast-container > .toast-error {
    border-left: 3px solid #FF5252 !important; /* 珊瑚红发光条 */
}

/* 警告提示 */
#toast-container > .toast-warning {
    border-left: 3px solid #FFB74D !important; /* 琥珀黄发光条 */
}

/* 普通信息提示 */
#toast-container > .toast-info {
    border-left: 3px solid #64B5F6 !important; /* 湛蓝发光条 */
}

/* 4. 隐藏自带的粗劣图标背景，保持纯净文本 */
#toast-container > .toast-success,
#toast-container > .toast-error,
#toast-container > .toast-warning,
#toast-container > .toast-info {
    background-image: none !important;
}

/* 5. 提示框文字排版 */
#toast-container > .toast .toast-title {
    font-weight: 700 !important;
    font-size: 13px !important;
    margin-bottom: 2px !important;
    color: var(--SmartThemeBodyColor, #fff) !important;
}

#toast-container > .toast .toast-message {
    opacity: 0.85 !important;
    line-height: 1.4 !important;
}

/* 6. 柔和滑入与微弹跳动画 */
@keyframes toast_bounce_in {
    0% {
        opacity: 0;
        transform: translateY(-12px) scale(0.95);
    }
    100% {
        opacity: 1;
        transform: translateY(0) scale(1);
    }
}


/* ==========================================================
   彻底隐藏世界书（World Info）右侧与底部滚动条
   ========================================================== */

/* 1. 禁止世界书面板横向溢出，彻底消除底部横条 */
#WorldInfo,
#world_info_sheet,
.drawer-content:has(#world_info_sheet) {
    overflow-x: hidden !important;
}

/* 2. 隐藏世界书及其所有子元素的原生滚动条（Firefox / Edge 视角） */
#WorldInfo,
#world_info_sheet,
#WorldInfo *,
#world_info_sheet * {
    scrollbar-width: none !important;
    -ms-overflow-style: none !important;
}

/* 3. 隐藏 WebKit 内核（Chrome / Safari / iOS / 安卓）的滚动条 */
#WorldInfo::-webkit-scrollbar,
#world_info_sheet::-webkit-scrollbar,
#WorldInfo *::-webkit-scrollbar,
#world_info_sheet *::-webkit-scrollbar {
    display: none !important;
    width: 0 !important;
    height: 0 !important;
    background: transparent !important;
}



/* ==========================================================
   极简高透思考胶囊（绝对精准触发 + 彻底解决刷新误显 BUG）
   ========================================================== */

/* 1. 将主输入框（#send_form）设为定位参照物 */
#send_form {
    position: relative !important;
    overflow: visible !important;
}

/* 2. 胶囊默认基础状态（严格强制隐藏） */
#send_form::before {
    content: "SillyTavern is generating..." !important;
    position: absolute !important;
    top: -42px !important;                 /* 悬浮于输入框正上方 */
    left: 0 !important;                    /* 水平居中 */
    right: 0 !important;
    margin: 0 auto !important;
    width: fit-content !important;

    /* 字体与排版 */
    font-size: 11.5px !important;
    letter-spacing: 0.8px !important;
    color: var(--SmartThemeBodyColor, rgba(255, 255, 255, 0.95)) !important;

    /* 高透毛玻璃背景与圆角 */
    background: color-mix(in srgb, var(--SmartThemeBlurTintColor, var(--smart-bg, #121216)) 75%, transparent) !important;
    backdrop-filter: blur(22px) !important;
    -webkit-backdrop-filter: blur(22px) !important;

    /* 尺寸与边框 */
    padding: 5px 15px !important;
    border-radius: 100px !important;
    border: 1px solid var(--SmartThemeBorderColor, rgba(255, 255, 255, 0.15)) !important;
    box-shadow: 0 4px 14px rgba(0, 0, 0, 0.25) !important;

    /* 纯展示与触摸穿透 */
    pointer-events: none !important;
    z-index: 1000 !important;
    white-space: nowrap !important;

    /* 严格隐形，默认不播放动画 */
    opacity: 0 !important;
    visibility: hidden !important;
    transform: translateY(0);
    transition: opacity 0.3s ease, visibility 0.3s ease, transform 0.3s ease !important;
}

/* 3. 严格判定：只有当页面明确处于生成状态（.generating），或者暂停按钮真正呈 flex/block 显示时才触发 */
#form_sheld.generating #send_form::before,
body.generating #send_form::before,
#send_form:has(.mes_stop[style*="display: flex"])::before,
#send_form:has(.mes_stop[style*="display: block"])::before,
#send_form:has(.mes_stop[style*="display: inline"])::before,
#form_sheld:has(.mes_stop[style*="display: flex"]) #send_form::before,
#form_sheld:has(.mes_stop[style*="display: block"]) #send_form::before {
    opacity: 1 !important;
    visibility: visible !important;
    animation: capsule_float_fade 2.4s ease-in-out infinite !important;
}

/* 4. 从淡到深（0.35 -> 1.0）的柔和渐变呼吸与纯 Y 轴沉浮动画 */
@keyframes capsule_float_fade {
    0%, 100% {
        transform: translateY(0);
        opacity: 0.35; /* 淡：微弱透明 */
    }
    50% {
        transform: translateY(-4px);
        opacity: 1;    /* 深：饱满亮起 */
    }
}






/* ==========================================================
   精准隐藏设置顶部滑块提示文字与问号图标组合
   ========================================================== */

/* 1. 隐藏“单击滑块以手动输入值”提示文字块 */
#clickSlidersTips,
div[data-i18n="clickslidertips"],
.editable-slider-notification {
    display: none !important;
}

/* 2. 精准隐藏与其组合的问号图标 */
span[name="samplerHelpButton"],
span.note-link-span.fa-circle-question {
    display: none !important;
}




/*消除思维链展开时的下沉抖动与位移 */
details.mes_reasoning_details,
details.mes_reasoning_details .mes_reasoning,
.mes .mes_text {
    transition: none !important;
    animation: none !important;
}



/* === iOS 触摸响应加速：明确告诉浏览器"垂直滚动，立即响应" === */
  #user-settings-button .drawer-content.openDrawer,
