      overscroll-behavior: contain;
  }





/* ==========================================================
   彻底解决小手机脚本点击输入框时整个界面上抬/顶起 BUG
   ========================================================== */

/* 1. 强制锁死页面根容器，禁止软键盘唤醒时推顶整个网页 */
html, body {
    position: fixed !important;
    width: 100% !important;
    height: 100% !important;
    height: 100dvh !important;
    overflow: hidden !important;
    top: 0 !important;
    left: 0 !important;
}




/* ==========================================================
   安卓触屏优化：扩展顶栏图标的“隐形热区”（视觉不变，更好点击）
   ========================================================== */

/* 1. 给顶栏每一个按钮容器增加隐形触控热区（扩展到 38px 见方） */
#top-bar .drawer,
#top-bar .drawer-icon,
#top-settings-holder .drawer-icon {
    position: relative !important;
    min-width: 38px !important;
    min-height: 38px !important;
    display: inline-flex !important;
    align-items: center !important;
    justify-content: center !important;
    touch-action: manipulation !important; /* 禁用双击缩放延迟，提升安卓响应速度 */
}

/* 2. 利用伪元素把点击响应范围往外扩，手指按在图标周围也能精准触发 */
#top-bar .drawer::after,
#top-bar .drawer-icon::after {
    content: "" !important;
    position: absolute !important;
    top: -6px !important;
    bottom: -6px !important;
    left: -6px !important;
    right: -6px !important;
    background: transparent !important; /* 纯透明隐形 */
    z-index: 10 !important;
}




/* ==========================================================
   完美避开顶部工具栏
   ========================================================== */

.drawer-content,
.drawer-content.openDrawer,
#user-settings-block {
    top: 30px !important;
    height: calc(100dvh - 40px) !important;
    max-height: calc(100dvh - 40px) !important;
    margin-top: 0 !important;
    box-sizing: border-box !important;
}


/* ==========================================================
   ★ 顶栏美化与弹窗完美居中适配（极简精简版）
   ========================================================== */

/* 1. 顶栏图标尺寸与透明度 */
#top-bar .drawer-icon,
#top-settings-holder .drawer-icon {
