/* ==========================================================
   全局滑动条（Slider）背景色去除与极简线条化
   ========================================================== */

/* 1. 清除原生滑动条主体背景 */
input[type="range"] {
    -webkit-appearance: none !important;
    appearance: none !important;
    background: transparent !important;      /* 去除整个框的背景色 */
    border: none !important;                 /* 去除外层边框 */
    box-shadow: none !important;
}

/* 2. 重置滑动条轨道（Track）：完全透明背景 */
input[type="range"]::-webkit-slider-runnable-track {
    background: transparent !important;      /* 去除滑轨长条背景 */
    border: 1px solid var(--SmartThemeBorderColor, rgba(255, 255, 255, 0.15)) !important; /* 保留极简微边框，若不需要可改为 none */
    border-radius: 6px !important;
    height: 8px !important;                  /* 轨道高度可调整 */
}

/* 3. 火狐浏览器 (Firefox) 轨道兼容 */
input[type="range"]::-moz-range-track {
    background: transparent !important;
    border: 1px solid var(--SmartThemeBorderColor, rgba(255, 255, 255, 0.15)) !important;
    border-radius: 6px !important;
    height: 8px !important;
}


