/* ==========================================================
   全局复选框（纯扁平直角风 + 几何硬朗单勾 + 扩展列表全兼容）
   ========================================================== */

/* 1. 强制普通文字选项整行垂直居中（包含扩展列表容器，严格排除滑动开关） */
.extension_toggle,
.checkbox_label:not([class*="switch"]):not([class*="toggle"]),
label:has(> input[type="checkbox"]):not([class*="switch"]):not([class*="toggle"]):not(.switch):not(.toggle),
.drawer-content label:has(input[type="checkbox"]):not([class*="switch"]):not([class*="toggle"]) {
    display: inline-flex !important;
    align-items: center !important;         /* 文字与选框中轴线严格对齐 */
    vertical-align: middle !important;
    line-height: 1.4 !important;
    cursor: pointer !important;
    margin: 4px 0 !important;
}

.extension_toggle {
    margin: 0 !important;
    justify-content: center !important;
}

/* 2. ★ 核心选框重置：纯粹直角矩形、无圆角、零立体投影 */
.extension_toggle input[type="checkbox"],
input[type="checkbox"]:not(.switch input):not(.toggle input):not([class*="switch"] input):not([class*="toggle"] input):not([class*="switch"]):not([class*="toggle"]) {
    -webkit-appearance: none !important;
    -moz-appearance: none !important;
    appearance: none !important;

    /* 严格锁死紧凑的 15px 正方形 */
    width: 15px !important;
    height: 15px !important;
    min-width: 15px !important;
    min-height: 15px !important;
    max-width: 15px !important;
    max-height: 15px !important;
    box-sizing: border-box !important;

    /* 👈 核心：完全直角化 */
    border-radius: 0 !important;

    /* 基础扁平外观：透明底 + 细直边框 */
    margin: 0 8px 0 0 !important;
    vertical-align: middle !important;
    position: relative !important;
    flex-shrink: 0 !important;
    pointer-events: auto !important;
    z-index: 10 !important;

    background: transparent !important;
    background-color: transparent !important;
    border: 1.5px solid var(--SmartThemeBorderColor, rgba(255, 255, 255, 0.35)) !important;
    box-shadow: none !important;
    outline: none !important;
    transition: border-color 0.15s ease, background-color 0.15s ease !important;
}

/* ★ 扩展列表专属覆盖：未启用状态下的复选框边框跟随酒馆斜体色 */
.extension_toggle input[type="checkbox"]:not(:checked) {
    border-color: var(--SmartThemeItalicsColor, #888) !important;
}

/* 3. 消息气泡与独立容器选框居中适配（消除右侧多余间距） */
.extension_toggle input[type="checkbox"],
.mes input[type="checkbox"]:not([class*="switch"]):not([class*="toggle"]),
#chat input[type="checkbox"]:not([class*="switch"]):not([class*="toggle"]) {
    margin: auto !important;
    align-self: center !important;
}

/* 4. 悬停与激活响应：扁平色块填充，边框硬朗对齐 */
.extension_toggle input[type="checkbox"]:hover,
input[type="checkbox"]:not([class*="switch"]):not([class*="toggle"]):hover {
    border-color: var(--SmartThemeQuoteColor, #7ebac3) !important;
    background-color: color-mix(in srgb, var(--SmartThemeQuoteColor, #7ebac3) 10%, transparent) !important;
}

.extension_toggle input[type="checkbox"]:checked,
input[type="checkbox"]:not([class*="switch"]):not([class*="toggle"]):checked {
    /* 选中后边框和背景直接跟随引用高亮色，形成清晰的扁平直角色块 */
    background-color: color-mix(in srgb, var(--SmartThemeQuoteColor, #7ebac3) 22%, transparent) !important;
    border-color: var(--SmartThemeQuoteColor, #7ebac3) !important;
}

/* 5. 清除残留原生伪元素与图标干扰 */
.extension_toggle input[type="checkbox"]::before,
input[type="checkbox"]:not([class*="switch"]):not([class*="toggle"]):before,
input[type="checkbox"]:not([class*="switch"]):not([class*="toggle"]) i,
