/* ==========================================================
   角色面板：标签筛选栏（展开向下平铺 + 收起单行水平横向滑动）
   ========================================================== */

/* 1. 外层控制器 */
.rm_tag_controls {
    width: 100% !important;
    margin: 2px 0 4px 0 !important;
    padding: 0 !important;
    box-sizing: border-box !important;
}

/* 2. 状态分流核心容器 */

/* --- 【收起状态（默认）】：单行横向顺滑滑动，不折叠、不堆叠 --- */
.rm_tag_controls .rm_tag_filter,
.rm_tag_controls .tags {
    display: flex !important;
    flex-wrap: nowrap !important;                  /* 👈 单行永不换行 */
    flex-direction: row !important;
    align-items: center !important;

    /* 开启原生弹性水平滚动 */
    overflow-x: auto !important;
    overflow-y: hidden !important;
    -webkit-overflow-scrolling: touch !important;
    touch-action: pan-x !important;

    /* 锁死高度，彻底切断原生折叠压扁动画，杜绝重影卡帧 */
    height: 32px !important;
    min-height: 32px !important;
    max-height: 32px !important;
    transition: none !important;
    animation: none !important;

    gap: 4px !important;
    padding: 2px 2px !important;
    width: 100% !important;
    box-sizing: border-box !important;

    scrollbar-width: none !important;
    -ms-overflow-style: none !important;
}

.rm_tag_controls .rm_tag_filter::-webkit-scrollbar,
.rm_tag_controls .tags::-webkit-scrollbar {
    display: none !important;
    width: 0 !important;
    height: 0 !important;
}

/* 滚动末尾留 10px 缓冲垫，防止最后一个标签贴死右侧边缘 */
.rm_tag_controls .rm_tag_filter::after {
    content: "" !important;
    display: block !important;
    flex: 0 0 10px !important;
    min-width: 10px !important;
    height: 1px !important;
}

/* --- 【展开状态】：向下排版（多行平铺显示） --- */
.rm_tag_controls .rm_tag_filter.expanded,
.rm_tag_controls .tags.expanded,
.rm_tag_controls:has(.showTagList.active) .rm_tag_filter,
.rm_tag_controls:has(.showTagList.selected) .rm_tag_filter,
.rm_tag_controls:has(.showTagList[data-toggle-state="INCLUDE"]) .rm_tag_filter {
    flex-wrap: wrap !important;                    /* 👈 展开时自然向下换行 */
    overflow-x: hidden !important;
    overflow-y: auto !important;
    height: auto !important;
    min-height: 32px !important;
    max-height: 200px !important;                  /* 展开后最大高度 */
    row-gap: 4px !important;
    column-gap: 4px !important;
    padding: 2px !important;
}

/* 3. ★ 核心突破：让被原生收起的文本标签在单行轨道中重新显示并可滑动 ★ */
/* 真正要隐藏的只有叉号、空元素和特定垃圾节点 */
.rm_tag_filter .tag_remove,
.rm_tag_filter i.tag_remove,
.rm_tag_filter .fa-circle-xmark:not(.clearAllFilters *),
.rm_tag_bogus_drilldown:empty,
.rm_tag_filter .tag.hidden:empty {
    display: none !important;
    width: 0 !important;
    min-width: 0 !important;
    margin: 0 !important;
    padding: 0 !important;
    border: none !important;
    visibility: hidden !important;
}

/* 4. 单个标签卡片基础外观（文字与图标均正常展现，绝不被压成 0 宽） */
#rightNavHolder .rm_tag_filter .tag,
#rm_print_characters_block .rm_tag_filter .tag,
.rm_tag_filter .tag {
    /* 👈 哪怕原生写了 display: none，也将其唤醒排列在横向滚动条中 */
    display: inline-flex !important;
    visibility: visible !important;
    flex: 0 0 auto !important;                     /* 👈 核心：绝不允许被挤压变形 */
    align-items: center !important;
    justify-content: center !important;
    width: auto !important;
    min-width: 26px !important;
    height: 25px !important;
    min-height: 25px !important;
    line-height: 23px !important;
    margin: 0 !important;
    box-sizing: border-box !important;

    background: transparent !important;
    background-color: transparent !important;
    border: 1px solid var(--SmartThemeBorderColor, rgba(127, 127, 127, 0.2)) !important;
    border-radius: 6px !important;
    box-shadow: none !important;
    text-shadow: none !important;
    filter: none !important;

    color: var(--SmartThemeBodyColor, inherit) !important;
    opacity: 0.65 !important;
    cursor: pointer !important;
    white-space: nowrap !important;                /* 文本一行到底，不折行 */

    transition: background 0.15s ease, border-color 0.15s ease, opacity 0.15s ease !important;
    animation: none !important;
}

/* 5. 前排固定功能按钮与后排文本标签分流 */
.rm_tag_filter .filterByFavorites,
.rm_tag_filter .filterByGroups,
.rm_tag_filter .filterByFolder,
.rm_tag_filter .manageTags,
.rm_tag_filter .showTagList,
.rm_tag_filter .clearAllFilters,
.rm_tag_filter .tag:has(> .tag_name.fa-solid:only-child) {
    width: 26px !important;
    min-width: 26px !important;
    padding: 0 !important;
    margin-right: 2px !important;
}

.rm_tag_filter .clearAllFilters {
    margin-right: 6px !important;                   /* 功能区与文本标签区的自然过渡 */
}

/* 纯文本标签左右内边距微调 */
.rm_tag_filter .tag:not(.filterByFavorites):not(.filterByGroups):not(.filterByFolder):not(.manageTags):not(.showTagList):not(.clearAllFilters):not(:has(> .tag_name.fa-solid:only-child)) {
    min-width: unset !important;
    padding: 0 5px !important;
    margin-right: 1px !important;
}

/* 内部文字排版 */
.rm_tag_filter .tag .tag_name {
    position: static !important;
    display: inline-block !important;
    background: transparent !important;
    border: none !important;
    color: inherit !important;
    font-size: 11.5px !important;
    white-space: nowrap !important;
    line-height: 1 !important;
    margin: 0 !important;
    padding: 0 !important;
    box-shadow: none !important;
    text-shadow: none !important;
}

/* 悬停反馈 */
.rm_tag_filter .tag:hover {
    opacity: 0.95 !important;
    border-color: var(--SmartThemeQuoteColor, #7ebac3) !important;
}

/* 6. 激活点亮状态（引用色填充 + 亮框） */
#rightNavHolder .rm_tag_filter .tag.include,
#rightNavHolder .rm_tag_filter .tag[data-toggle-state="INCLUDE"],
#rightNavHolder .rm_tag_filter .tag[data-toggle-state="include"],
#rightNavHolder .rm_tag_filter .tag.active,
#rightNavHolder .rm_tag_filter .tag.selected,
.rm_tag_filter .tag.include,
.rm_tag_filter .tag[data-toggle-state="INCLUDE"],
.rm_tag_filter .tag[data-toggle-state="include"],
.rm_tag_filter .tag.active,
.rm_tag_filter .tag.selected {
    background: color-mix(in srgb, var(--SmartThemeQuoteColor, #7ebac3) 32%, transparent) !important;
    background-color: color-mix(in srgb, var(--SmartThemeQuoteColor, #7ebac3) 32%, transparent) !important;
    border-color: var(--SmartThemeQuoteColor, #7ebac3) !important;
    color: var(--SmartThemeQuoteColor, #7ebac3) !important;
    opacity: 1 !important;
    font-weight: 600 !important;
    box-shadow: 0 0 6px color-mix(in srgb, var(--SmartThemeQuoteColor, #7ebac3) 25%, transparent) !important;
}

.rm_tag_filter .tag.include *,
.rm_tag_filter .tag[data-toggle-state="INCLUDE"] *,
.rm_tag_filter .tag[data-toggle-state="include"] *,
.rm_tag_filter .tag.active *,
.rm_tag_filter .tag.selected * {
    color: var(--SmartThemeQuoteColor, #7ebac3) !important;
}

/* 7. 排除态（EXCLUDE）退化 */
#rightNavHolder .rm_tag_filter .tag.exclude,
#rightNavHolder .rm_tag_filter .tag[data-toggle-state="EXCLUDE"],
#rightNavHolder .rm_tag_filter .tag[data-toggle-state="exclude"],
.rm_tag_filter .tag.exclude,
.rm_tag_filter .tag[data-toggle-state="EXCLUDE"],
.rm_tag_filter .tag[data-toggle-state="exclude"] {
    background: transparent !important;
    background-color: transparent !important;
    border-color: var(--SmartThemeBorderColor, rgba(127, 127, 127, 0.15)) !important;
    color: var(--SmartThemeBodyColor, inherit) !important;
    opacity: 0.35 !important;
    box-shadow: none !important;
}

.rm_tag_filter .tag.exclude * {
    color: inherit !important;
}

