/* ==========================================================
   0. 引入外部网络字体（必须放在整个 Custom CSS 输入框的最第一行！）
   ========================================================== */
@import url("https://fontsapi.zeoseven.com/292/main/result.css");

/* ==========================================================
   1. 全局排版与数值自定义区 (统一修改此处冒号后的数值或变量即可)
   ========================================================== */
:root {
    /* --- 【1. 聊天区布局与间距调节】 --- */

    --chat-bottom-spacing: 0px;       /* 聊天记录底部留白 */
    --input-form-bottom-lift: 0px;    /* 输入框距离屏幕底边缘的抬高高度 */

    --text-left-padding: 0px;         /* 正文左侧留白间距 */
    --text-right-padding: 0px;        /* 正文右侧留白间距 */
    --text-top-padding: 0px;          /* 正文上方留白间距 */

    --ai-bottom-padding: 12px;        /* ★ AI消息气泡底部留白 */
    --user-bottom-padding: 12px;      /* ★ 用户消息气泡底部留白 */

    --mes-bottom-gap: -16px;           /* 上下两条消息气泡之间的间距 */
    --avatar-size: 110px;             /* 消息头像的宽度和高度尺寸 */

    /* --- 【2. 颜色跟随配置区】 --- */
    --custom-name-color: var(--SmartThemeBodyColor, #2c3e50);
    --custom-solid-line-color: var(--SmartThemeQuoteColor, #2c3e50);
    --custom-dashed-line-color: var(--SmartThemeEmphasisColor, #888);
    --custom-meta-text-color: var(--SmartThemeEmphasisColor, #888);
    --custom-avatar-border-color: var(--SmartThemeBorderColor, rgba(127, 127, 127, 0.3));

    /* --- 【3. 字体与排版参数】删除掉 Noto Serif CJK 前的 @ 就是思源宋体，我故意加的 --- */
    --my-custom-font: "LXGW WenKai", -apple-system, "PingFang SC", "Microsoft YaHei", sans-serif;
    --text-font-size: 16px;        
    --text-font-weight: 400;       
    --text-line-height: 1.8;       
    --text-letter-spacing: 0.2px;  
    --text-paragraph-gap: 0px;     
    --text-align-mode: left;    

    /* --- 【4. 沉浸式底部输入框参数】 --- */
    --input-bottom-dist: 25px;        /* 输入框距离屏幕底部的悬浮高度 */
    --input-idle-opacity: 0.6;        /* 未激活/静止时的输入框透明度 (0为完全隐形) */
    --input-active-opacity: 0.9;      /* 聚焦/悬停/有字时的输入框透明度 */
    --input-button-scale: 0.6;        /* ★ 输入框左右发送/扩展按钮的缩放比例 (默认 0.6) */
    --input-stop-button-scale: 0.7;   /* 单独控制暂停按钮的倍率，如 0.8、1.2 等 */


    /* --- 【5. 编辑状态大文本框参数】 --- */
    --edit-min-height: 200px;         /* 编辑状态下框体最小高度 */
    --edit-default-height: 360px;     /* 编辑状态下框体默认高度 */
    --edit-max-height: 550px;         /* 编辑状态下框体最大展开限制 */

    /* --- 【6. 顶栏动效与外观参数】 --- */
    --topbar-idle-bg-opacity: 0.4;    /* 未点开时背景透明度 (0全透明 ~ 1实色) */
    --topbar-idle-icon-opacity: 0.3;  /* 未点开时图标的淡化透明度 */
    --topbar-icon-size: 16px;         /* ★ 顶栏抽屉图标的字号/尺寸 */
    --topbar-bottom-radius: 16px;     /* 顶栏底部两侧圆角大小 */
    --topbar-shadow: 0 4px 8px rgba(0, 0, 0, 0.3); /* 顶栏阴影效果 */
    --topbar-border-style: 0.15px solid var(--SmartThemeBorderColor, rgba(255, 255, 255, 0.15)); /* 边框样式 */
}

/* ==========================================================
   2. 将定义的参数真正“应用”到酒馆的聊天文本上
   ========================================================== */
.mes_text {
    font-family: var(--my-custom-font) !important;
    font-size: var(--text-font-size) !important;
    font-weight: var(--text-font-weight) !important;
    line-height: var(--text-line-height) !important;
    letter-spacing: var(--text-letter-spacing) !important;
    text-align: var(--text-align-mode) !important;
