    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
}

.mes_text p { margin-bottom: var(--text-paragraph-gap) !important; }


.mes .mes_text p {
    text-indent: 2em !important;                    
    text-align: var(--text-align-mode) !important;       
    margin-left: 0 !important; margin-right: 0 !important;
}


/* ==========================================================
   消息排版与布局设置
   ========================================================== */

/* ==========================================================
   ★ 聊天气泡全宽/极限加宽修复（击穿外层 padding 锁死，严格居中对称）
   ========================================================== */

/* 1. 变量层突破：允许 100% 极限通栏 */
:root {
    --mes-max-width: 100% !important;
    --mes-width: 100% !important;
}

/* 2. 剥离外层容器的所有内缩 padding（核心卡点所在） */
#sheld,
#chat-container,
#chat {
    width: 100% !important;
    max-width: 100% !important;
    padding-left: 0 !important;
    padding-right: 0 !important;
    margin-left: auto !important;
    margin-right: auto !important;
    box-sizing: border-box !important;
    align-items: center !important;
}

/* 3. 消息块容器（.mes_block）：彻底撑开并居中 */
.mes_block {
    width: 100% !important;
    max-width: 100% !important;
    padding-left: 0 !important;
    padding-right: 0 !important;
    margin: 0 auto !important;
    box-sizing: border-box !important;
}

/* 4. 气泡本体（.mes）：左右对称加宽 */
.mes {
    /* 👈 如果想完全贴屏拉满，写 100%；如果想留精致微边距，写 calc(99) 或 95% */
    width: calc(96%) !important;
    max-width: calc(96%) !important;

    /* 👈 左右 auto 保证无论怎么放宽，都以屏幕中心点为基准左右同时扩展 */
    margin-left: auto !important;
    margin-right: auto !important;
    margin-top: 6px !important;
    margin-bottom: 6px !important;
    box-sizing: border-box !important;
}

/* 5. 气泡内部排版：防止内容文字贴死卡片边框 */
.mes .mes_text {
