/* ==========================================================
   美化 Toast 系统通知弹窗（保存提示、消息通知等）
   ========================================================== */

/* 1. 提示框总容器定位与层级 */
#toast-container {
    top: 20px !important;                 /* 距离顶部高度 */
    right: 20px !important;               /* 距离右侧间距 */
    z-index: 999999 !important;           /* 确保最外层置顶 */
}

/* 2. Toast 提示框本体外观美化 */
#toast-container > .toast {
    /* 基础形变与圆角 */
    border-radius: 12px !important;
    padding: 10px 18px !important;
    margin-bottom: 8px !important;
    box-shadow: 0 8px 24px rgba(0, 0, 0, 0.35) !important;

    /* 高透毛玻璃 */
    background: color-mix(in srgb, var(--SmartThemeBlurTintColor, var(--smart-bg, #121216)) 80%, transparent) !important;
    backdrop-filter: blur(4px) !important;
    -webkit-backdrop-filter: blur(4px) !important;
    border: 1px solid var(--SmartThemeBorderColor, rgba(255, 255, 255, 0.15)) !important;

    /* 字体与排版 */
    font-family: var(--my-custom-font, inherit) !important;
    font-size: 12.5px !important;
    letter-spacing: 0.5px !important;
    color: var(--SmartThemeBodyColor, #fff) !important;

    /* 滑入弹跳入场动画 */
    animation: toast_bounce_in 0.35s cubic-bezier(0.175, 0.885, 0.32, 1.275) forwards !important;
    opacity: 1 !important;
}

/* 3. 不同类型提示框的边框/小发光色彩（成功、错误、警告、信息） */

/* 成功提示（如：保存成功、加载成功） */
#toast-container > .toast-success {
    border-left: 3px solid #4CAF50 !important; /* 翡翠绿发光条 */
}

/* 错误提示（如：API报错、请求失败） */
#toast-container > .toast-error {
    border-left: 3px solid #FF5252 !important; /* 珊瑚红发光条 */
}

/* 警告提示 */
#toast-container > .toast-warning {
    border-left: 3px solid #FFB74D !important; /* 琥珀黄发光条 */
}

/* 普通信息提示 */
#toast-container > .toast-info {
    border-left: 3px solid #64B5F6 !important; /* 湛蓝发光条 */
}

/* 4. 隐藏自带的粗劣图标背景，保持纯净文本 */
#toast-container > .toast-success,
#toast-container > .toast-error,
#toast-container > .toast-warning,
#toast-container > .toast-info {
    background-image: none !important;
}

/* 5. 提示框文字排版 */
#toast-container > .toast .toast-title {
    font-weight: 700 !important;
    font-size: 13px !important;
    margin-bottom: 2px !important;
    color: var(--SmartThemeBodyColor, #fff) !important;
}

#toast-container > .toast .toast-message {
    opacity: 0.85 !important;
    line-height: 1.4 !important;
}

/* 6. 柔和滑入与微弹跳动画 */
@keyframes toast_bounce_in {
    0% {
        opacity: 0;
        transform: translateY(-12px) scale(0.95);
    }
    100% {
        opacity: 1;
        transform: translateY(0) scale(1);
    }
}


/* ==========================================================
   彻底隐藏世界书（World Info）右侧与底部滚动条
   ========================================================== */

/* 1. 禁止世界书面板横向溢出，彻底消除底部横条 */
