/* 2. 折叠箭头图标：彻底透明底色 + 颜色跟随引用色 */
.inline-drawer-icon,
.fa-circle-chevron-down,
.fa-circle-chevron-up,
.fa-chevron-down,
.fa-chevron-up,
.inline-drawer-header i,
.title_restorable i {
