}



/* ==========================================================
   自定义 CSS 放大编辑器（顶部避让灵动岛 + 下移微调版）
   ========================================================== */

/* 1. 弹窗主框体：向下平移避开灵动岛，保持居中与比例协调 */
dialog.popup:has(textarea[data-for="customCSS"]),
dialog.wide_dialogue_popup:has(.maximized_textarea),
dialog.large_dialogue_popup:has(.maximized_textarea) {
    position: fixed !important;
    /* 👈 核心下移：状态栏安全区之上再下移 36px，彻底离开灵动岛区域 */
    top: calc(env(safe-area-inset-top, 20px) + 36px) !important;
    bottom: calc(env(safe-area-inset-bottom, 15px) + 12px) !important;
    left: 50% !important;
    transform: translateX(-50%) !important;

    width: 95vw !important;
    max-width: 95vw !important;
    min-width: 95vw !important;
    /* 严格同步扣减高度，防止底部溢出或被遮挡 */
    height: calc(100dvh - env(safe-area-inset-top, 20px) - env(safe-area-inset-bottom, 15px) - 60px) !important;
    max-height: calc(100dvh - env(safe-area-inset-top, 20px) - env(safe-area-inset-bottom, 15px) - 60px) !important;

    margin: 0 !important;
    padding: 10px 8px !important;
    box-sizing: border-box !important;

    display: flex !important;
    flex-direction: column !important;
    border-radius: 14px !important;
    overflow: hidden !important;
}

/* 2. 弹窗内胆与内容层充满可用高度 */
dialog:has(textarea[data-for="customCSS"]) .popup-body,
dialog:has(textarea[data-for="customCSS"]) .popup-content,
dialog:has(textarea[data-for="customCSS"]) .popup-content > div {
    display: flex !important;
    flex-direction: column !important;
    flex: 1 1 auto !important;
    height: 100% !important;
    max-height: 100% !important;
    width: 100% !important;
    padding: 0 !important;
    margin: 0 !important;
    overflow: hidden !important;
    box-sizing: border-box !important;
}

/* 3. 核心 textarea：双向自由滑动，高度自适应拉满 */
dialog textarea.maximized_textarea[data-for="customCSS"],
dialog textarea.maximized_textarea {
    flex: 1 1 auto !important;
    width: 100% !important;
    height: 100% !important;
    min-height: 0 !important;                     /* 释放固定高度，完全跟随弹性容器自适应 */
    box-sizing: border-box !important;

    font-size: 11px !important;
    line-height: 1.35 !important;
    font-family: Consolas, "Courier New", monospace !important;
    tab-size: 2 !important;
    -moz-tab-size: 2 !important;

    padding: 8px !important;
    white-space: pre !important;
    word-break: normal !important;
    overflow-wrap: normal !important;

    overflow-x: auto !important;
    overflow-y: auto !important;
    -webkit-overflow-scrolling: touch !important;
    touch-action: pan-x pan-y !important;
}

/* 4. 底部确定按钮保持下压居中 */
dialog:has(textarea[data-for="customCSS"]) .popup-controls {
    flex: 0 0 auto !important;
    padding-top: 6px !important;
    margin-top: 2px !important;
    display: flex !important;
    justify-content: center !important;
}

dialog:has(textarea[data-for="customCSS"]) .popup-controls .menu_button {
    height: 30px !important;
    min-height: 30px !important;
    padding: 2px 22px !important;
    font-size: 12px !important;
    line-height: 26px !important;
}


/* ==========================================================
   ★ 角色筛选栏图标精修（修复文本标签被 28px 锁死挤压 Bug）
   ========================================================== */

/* 1. 清洗外层包裹容器（.tag），消除原生大圆底与硬编码背景 */
#rm_print_characters_block .tag,
#rightNavHolder .tag,
#char_tags .tag,
.tags_holder .tag,
div:has(> .tag_name) {
    background: transparent !important;
    background-color: transparent !important;
    border: none !important;
    box-shadow: none !important;
    border-radius: 0 !important;
    padding: 0 !important;
    margin: 0 3px !important;
    display: inline-flex !important;
    align-items: center !important;
    justify-content: center !important;
}

/* 2. 标签与按钮本体基础风格：弹性宽度，不再写死 28px 宽度 */
#rm_print_characters_block .tag_name,
#rightNavHolder .tag_name,
#char_tags .tag_name,
.tags_holder .tag_name {
    display: inline-flex !important;
    align-items: center !important;
    justify-content: center !important;
    box-sizing: border-box !important;

    /* 👈 核心修复：高度固定 26px，宽度自适应文本长度并加左右留白 */
    width: auto !important;
    min-width: 26px !important;
    height: 26px !important;
    padding: 0 8px !important;
    white-space: nowrap !important;        /* 杜绝换行切字 */

    /* 微质感硬朗微圆角 */
    border-radius: 6px !important;

    /* 默认毛玻璃低透底色 + 极细微边框 */
    background: color-mix(in srgb, var(--SmartThemeBodyColor, #000) 8%, transparent) !important;
    border: 1px solid var(--SmartThemeBorderColor, rgba(127, 127, 127, 0.25)) !important;
    color: var(--SmartThemeBodyColor, inherit) !important;
    opacity: 0.7 !important;
    font-size: 12px !important;
    line-height: 1 !important;
    cursor: pointer !important;
    margin: 0 !important;
    box-shadow: none !important;
    transition: all 0.2s ease !important;
}

/* 3. ★ 专门针对“单纯是单个图标”的筛选小方块，才锁死 26x26 正方形 */
#rm_print_characters_block .tag_name.fa-solid,
#rm_print_characters_block .tag_name[class*="fa-"],
#rm_print_characters_block .tag:has(i:only-child) .tag_name,
span.tag_name.fa-star {
    width: 26px !important;
    padding: 0 !important;
}

/* 4. 悬停反馈 */
#rm_print_characters_block .tag:hover .tag_name,
span.tag_name:hover {
    opacity: 1 !important;
    border-color: var(--SmartThemeQuoteColor, #7ebac3) !important;
    background: color-mix(in srgb, var(--SmartThemeQuoteColor, #7ebac3) 12%, transparent) !important;
}

/* 5. 激活点亮状态 */
#rm_print_characters_block .tag.active .tag_name,
#rm_print_characters_block .tag.selected .tag_name,
#rm_print_characters_block .tag[style*="background"] .tag_name,
.tag_name.active,
.tag_name.selected,
span.tag_name.fa-star.active,
span.tag_name.fa-star[style*="color"] {
    opacity: 1 !important;
    color: var(--SmartThemeQuoteColor, #7ebac3) !important;
    border-color: var(--SmartThemeQuoteColor, #7ebac3) !important;
    background: color-mix(in srgb, var(--SmartThemeQuoteColor, #7ebac3) 20%, transparent) !important;
    box-shadow: 0 0 8px color-mix(in srgb, var(--SmartThemeQuoteColor, #7ebac3) 40%, transparent) !important;
    transform: scale(1.03) !important;
}



/* ==========================================================
   角色面板：标签筛选栏（展开向下平铺 + 收起单行水平横向滑动）
   ========================================================== */

/* 1. 外层控制器 */
.rm_tag_controls {
    width: 100% !important;
    margin: 2px 0 4px 0 !important;
    padding: 0 !important;
    box-sizing: border-box !important;
}

/* 2. 状态分流核心容器 */

/* --- 【收起状态（默认）】：单行横向顺滑滑动，不折叠、不堆叠 --- */
.rm_tag_controls .rm_tag_filter,
.rm_tag_controls .tags {
    display: flex !important;
    flex-wrap: nowrap !important;                  /* 👈 单行永不换行 */
    flex-direction: row !important;
    align-items: center !important;

    /* 开启原生弹性水平滚动 */
    overflow-x: auto !important;
    overflow-y: hidden !important;
    -webkit-overflow-scrolling: touch !important;
    touch-action: pan-x !important;

    /* 锁死高度，彻底切断原生折叠压扁动画，杜绝重影卡帧 */
    height: 32px !important;
    min-height: 32px !important;
    max-height: 32px !important;
    transition: none !important;
    animation: none !important;

    gap: 4px !important;
    padding: 2px 2px !important;
    width: 100% !important;
    box-sizing: border-box !important;

    scrollbar-width: none !important;
    -ms-overflow-style: none !important;
}

.rm_tag_controls .rm_tag_filter::-webkit-scrollbar,
.rm_tag_controls .tags::-webkit-scrollbar {
    display: none !important;
    width: 0 !important;
    height: 0 !important;
}

/* 滚动末尾留 10px 缓冲垫，防止最后一个标签贴死右侧边缘 */
.rm_tag_controls .rm_tag_filter::after {
    content: "" !important;
    display: block !important;
    flex: 0 0 10px !important;
    min-width: 10px !important;
    height: 1px !important;
}

/* --- 【展开状态】：向下排版（多行平铺显示） --- */
.rm_tag_controls .rm_tag_filter.expanded,
.rm_tag_controls .tags.expanded,
.rm_tag_controls:has(.showTagList.active) .rm_tag_filter,
.rm_tag_controls:has(.showTagList.selected) .rm_tag_filter,
.rm_tag_controls:has(.showTagList[data-toggle-state="INCLUDE"]) .rm_tag_filter {
    flex-wrap: wrap !important;                    /* 👈 展开时自然向下换行 */
    overflow-x: hidden !important;
    overflow-y: auto !important;
    height: auto !important;
    min-height: 32px !important;
    max-height: 200px !important;                  /* 展开后最大高度 */
    row-gap: 4px !important;
    column-gap: 4px !important;
    padding: 2px !important;
}

/* 3. ★ 核心突破：让被原生收起的文本标签在单行轨道中重新显示并可滑动 ★ */
/* 真正要隐藏的只有叉号、空元素和特定垃圾节点 */
.rm_tag_filter .tag_remove,
.rm_tag_filter i.tag_remove,
.rm_tag_filter .fa-circle-xmark:not(.clearAllFilters *),
.rm_tag_bogus_drilldown:empty,
.rm_tag_filter .tag.hidden:empty {
    display: none !important;
    width: 0 !important;
    min-width: 0 !important;
    margin: 0 !important;
    padding: 0 !important;
    border: none !important;
    visibility: hidden !important;
}

/* 4. 单个标签卡片基础外观（文字与图标均正常展现，绝不被压成 0 宽） */
#rightNavHolder .rm_tag_filter .tag,
#rm_print_characters_block .rm_tag_filter .tag,
.rm_tag_filter .tag {
    /* 👈 哪怕原生写了 display: none，也将其唤醒排列在横向滚动条中 */
    display: inline-flex !important;
    visibility: visible !important;
    flex: 0 0 auto !important;                     /* 👈 核心：绝不允许被挤压变形 */
    align-items: center !important;
    justify-content: center !important;
    width: auto !important;
    min-width: 26px !important;
    height: 25px !important;
    min-height: 25px !important;
    line-height: 23px !important;
    margin: 0 !important;
    box-sizing: border-box !important;

    background: transparent !important;
    background-color: transparent !important;
    border: 1px solid var(--SmartThemeBorderColor, rgba(127, 127, 127, 0.2)) !important;
    border-radius: 6px !important;
    box-shadow: none !important;
    text-shadow: none !important;
    filter: none !important;

    color: var(--SmartThemeBodyColor, inherit) !important;
    opacity: 0.65 !important;
    cursor: pointer !important;
    white-space: nowrap !important;                /* 文本一行到底，不折行 */

    transition: background 0.15s ease, border-color 0.15s ease, opacity 0.15s ease !important;
    animation: none !important;
}

/* 5. 前排固定功能按钮与后排文本标签分流 */
.rm_tag_filter .filterByFavorites,
.rm_tag_filter .filterByGroups,
.rm_tag_filter .filterByFolder,
.rm_tag_filter .manageTags,
.rm_tag_filter .showTagList,
.rm_tag_filter .clearAllFilters,
.rm_tag_filter .tag:has(> .tag_name.fa-solid:only-child) {
    width: 26px !important;
    min-width: 26px !important;
    padding: 0 !important;
    margin-right: 2px !important;
}

.rm_tag_filter .clearAllFilters {
    margin-right: 6px !important;                   /* 功能区与文本标签区的自然过渡 */
}

/* 纯文本标签左右内边距微调 */
.rm_tag_filter .tag:not(.filterByFavorites):not(.filterByGroups):not(.filterByFolder):not(.manageTags):not(.showTagList):not(.clearAllFilters):not(:has(> .tag_name.fa-solid:only-child)) {
    min-width: unset !important;
    padding: 0 5px !important;
    margin-right: 1px !important;
}

/* 内部文字排版 */
.rm_tag_filter .tag .tag_name {
    position: static !important;
    display: inline-block !important;
    background: transparent !important;
    border: none !important;
    color: inherit !important;
    font-size: 11.5px !important;
    white-space: nowrap !important;
    line-height: 1 !important;
    margin: 0 !important;
    padding: 0 !important;
    box-shadow: none !important;
    text-shadow: none !important;
}

/* 悬停反馈 */
.rm_tag_filter .tag:hover {
    opacity: 0.95 !important;
    border-color: var(--SmartThemeQuoteColor, #7ebac3) !important;
}

/* 6. 激活点亮状态（引用色填充 + 亮框） */
#rightNavHolder .rm_tag_filter .tag.include,
#rightNavHolder .rm_tag_filter .tag[data-toggle-state="INCLUDE"],
#rightNavHolder .rm_tag_filter .tag[data-toggle-state="include"],
#rightNavHolder .rm_tag_filter .tag.active,
#rightNavHolder .rm_tag_filter .tag.selected,
.rm_tag_filter .tag.include,
.rm_tag_filter .tag[data-toggle-state="INCLUDE"],
.rm_tag_filter .tag[data-toggle-state="include"],
.rm_tag_filter .tag.active,
.rm_tag_filter .tag.selected {
    background: color-mix(in srgb, var(--SmartThemeQuoteColor, #7ebac3) 32%, transparent) !important;
    background-color: color-mix(in srgb, var(--SmartThemeQuoteColor, #7ebac3) 32%, transparent) !important;
    border-color: var(--SmartThemeQuoteColor, #7ebac3) !important;
    color: var(--SmartThemeQuoteColor, #7ebac3) !important;
    opacity: 1 !important;
    font-weight: 600 !important;
